static Color IconWeaponColor(string item, Color fallback)
{
    if (item == null) return fallback;
    foreach (string mat in armorMaterials)
        if (item.Contains(mat)) return MaterialColor(mat);
    return fallback;
}

static void UpdateTutorial(float dt)
{
    if (tutorialMessageTimer > 0) tutorialMessageTimer -= dt;
    if (tutorialCompleted) { tutorialActive = false; return; }
    if (!tutorialActive) return;

    
    if (tutorialStep >= tutorialTasks.Count)
    {
        tutorialActive = false;
        tutorialCompleted = true;
        tutorialMessage = "Training complete! The farm gates are open. Good luck!";
        tutorialMessageTimer = 4f;
        return;
    }

    var task = tutorialTasks[tutorialStep];

    // NPC smoothly follows behind the player, drifting toward the current guide spot
    tutorialNpcBob += dt;
    Vector2 followTarget = Vector2.Lerp(player.Position + new Vector2(-60, -40), task.GuidePos, 0.35f);
    tutorialNpcPos = Vector2.Lerp(tutorialNpcPos, followTarget, 2.5f * dt);

    // ---- AUTO-DETECT task completion ----
    bool justCompleted = false;
    switch (tutorialStep)
    {
        case 0: // Woodcutting — detect a tree chop via XP gain
            if (player.WoodcuttingXP > tutorialWoodMark || player.WoodcuttingLevel > 1) justCompleted = true;
            break;
        case 1: // Mining
            if (player.MiningXP > tutorialMineMark || player.MiningLevel > 1) justCompleted = true;
            break;
        case 2: // Fishing
            if (player.FishingXP > tutorialFishMark || player.FishingLevel > 1) justCompleted = true;
            break;
        case 3: // Combat
            if (player.CombatXP > tutorialCombatMark || player.CombatLevel > 1) justCompleted = true;
            break;
    }

    if (justCompleted)
    {
        task.Done = true;
        tutorialStep++;
        tutorialMessage = $"Great! {task.Title} learned. Gate opened!";
        tutorialMessageTimer = 4f;

        // snapshot marks for the next task so we detect fresh XP gains
        SnapshotTutorialMarks();
    }
}

static void TryFireSpell(Vector2 dir)
{
    // staff must come from the actually-equipped weapon
    string staff = (equipped2H != null && equipped2H.EndsWith("Staff")) ? equipped2H
                 : (equipped1H != null && equipped1H.EndsWith("Staff")) ? equipped1H
                 : null;
    string spell = GetStaffSpell(staff);

    if (spell == null)
    {
        floatingTexts.Add(new FloatingText {
            Position = player.Position - new Vector2(0, 40),
            Text = "Equip a staff first!",
            Timer = 1.5f, TextColor = Color.Purple
        });
        return;
    }

    // essence must be loaded in the ammo slot
    if (equippedAmmo != "Arcane Essence")
    {
        floatingTexts.Add(new FloatingText {
            Position = player.Position - new Vector2(0, 40),
            Text = "Load Arcane Essence in your ammo slot!",
            Timer = 1.5f, TextColor = Color.Purple
        });
        return;
    }

    if (player.ArcaneEssence <= 0)
    {
        floatingTexts.Add(new FloatingText {
            Position = player.Position - new Vector2(0, 40),
            Text = "Not enough Arcane Essence!",
            Timer = 1.5f, TextColor = Color.Purple
        });
        return;
    }

    if (spellCooldown > 0) return;

    float maxLife = 1.2f + (player.ElementalLevel * 0.015f);
    float speed   = 380f;
    spellCooldown = 0.5f;

    player.ArcaneEssence--;
    spellProjectiles.Add(new SpellProjectile(player.Center, dir * speed, spell, maxLife, maxLife));
    multiplayer.SendProjectile(player.Center.X, player.Center.Y, (dir * speed).X, (dir * speed).Y,
    maxLife, spell, true);
    player.AddElementalXP(1);

    // auto-clear ammo slot when essence runs out
    if (player.ArcaneEssence <= 0) equippedAmmo = null;
}

static void UpdateSpellProjectiles(float dt)
{
    if (spellCooldown > 0) spellCooldown -= dt;

    for (int i = spellProjectiles.Count - 1; i >= 0; i--)
    {
        var p = spellProjectiles[i];
        p = p with { Pos = p.Pos + p.Vel * dt, Life = p.Life - dt };

        if (p.Life <= 0) { spellProjectiles.RemoveAt(i); continue; }

        bool hit = false;
        foreach (var enemy in enemies)
        {
            if (enemy.Dead) continue;
            Rectangle bounds = new Rectangle(p.Pos.X - 6, p.Pos.Y - 6, 12, 12);
            if (!Raylib.CheckCollisionRecs(bounds, enemy.Bounds)) continue;

            int baseDmg  = GetSpellDamage(p.SpellType);
            int lvlBonus = player.ElementalLevel / 5;
            int dmg      = baseDmg + lvlBonus;

            int actualDmg = Math.Min(dmg, enemy.Health);
            enemy.Health -= dmg;
            enemy.TriggerFlash();
            SpawnSplat(enemy.Center, GetSpellColor(p.SpellType));
            if (enemy.Health <= 0)
            {
                enemy.Dead = true;
                SpawnDeathFx(enemy.Center, enemy.EnemyColor, enemy.Type);
            }

            floatingTexts.Add(new FloatingText {
                Position = enemy.Position - new Vector2(0, 20),
                Text = $"-{dmg}",
                Timer = 1f,
                TextColor = GetSpellColor(p.SpellType)
            });

            player.AddElementalXP(Math.Max(1, actualDmg));
            hit = true;
            break;
        }

        // ── world boss hit ──
        if (!hit && worldBoss != null && !worldBoss.Dead
    && Raylib.CheckCollisionPointRec(p.Pos, worldBoss.Bounds))
{
    int dmg = GetSpellDamage(p.SpellType) + player.ElementalLevel / 3;

    if (multiplayer.IsHost || !multiplayer.Connected)
    {
        // host (or single-player) applies damage directly
        worldBoss.Health -= dmg;
        if (worldBoss.Health <= 0)
        {
            worldBoss.Dead = true;
            player.AddCombatXP(500);
            player.Money += 1000;
            ShowLevelUp($"{worldBoss.Name} defeated!", 0);
        }
        if (multiplayer.Connected)
            multiplayer.BroadcastBossState(false, worldBoss.Health, worldBoss.MaxHealth, worldBoss.Dead,
                worldBoss.Position.X, worldBoss.Position.Y);
    }
    else
    {
        // client: report the hit, let the host apply real damage and broadcast back
        multiplayer.SendBossHit(false, dmg);
    }

    floatingTexts.Add(new FloatingText {
        Position = worldBoss.Center - new Vector2(0, worldBoss.Size / 2f),
        Text = $"-{dmg}", Timer = 1f, TextColor = GetSpellColor(p.SpellType)
    });
    player.AddElementalXP(dmg);
    hit = true;
}

        if (hit) spellProjectiles.RemoveAt(i);
        else     spellProjectiles[i] = p;
    }
}
static void TryFireProjectile(Vector2 dir)
{
    
    bool isBow      = equipped2H != null && equipped2H.Contains("Bow") && !equipped2H.Contains("Crossbow");
    bool isCrossbow = equipped2H != null && equipped2H.Contains("Crossbow");

    bool hasBow      = isBow      && equippedAmmo == "Arrows" && player.Arrows > 0;
    bool hasCrossbow = isCrossbow && equippedAmmo == "Bolts"  && player.Bolts  > 0;

    if (!hasBow && !hasCrossbow)
    {
        if (isBow || isCrossbow)
        {
            string requiredAmmo = isCrossbow ? "Bolts" : "Arrows";
            int    have         = isCrossbow ? player.Bolts : player.Arrows;
            string msg = have <= 0
                ? $"Out of {requiredAmmo}! This {equipped2H} needs {requiredAmmo}."
                : $"Equip {requiredAmmo} as ammo to fire the {equipped2H}!";

            ShowNotification(msg);
        }
        return;
    }

    float cooldown = hasCrossbow ? 1.2f : 0.6f;
    if (bowCooldown > 0) return;
    bowCooldown = cooldown;

    float speed = hasCrossbow ? 700f : 500f;

    projectiles.Add(new Projectile(player.Center, dir * speed,
        hasCrossbow ? "Bolts" : "Arrows", 3f));

    multiplayer.SendProjectile(player.Center.X, player.Center.Y, (dir * speed).X, (dir * speed).Y,
    3f, hasCrossbow ? "Bolts" : "Arrows", false);

    if (hasCrossbow) player.Bolts--;
    else             player.Arrows--;
    player.AddRangedXP(1);
}

static void UpdateProjectiles(float dt)
{
    
    if (bowCooldown > 0) bowCooldown -= dt;

    for (int i = projectiles.Count - 1; i >= 0; i--)
    {
        var p = projectiles[i];
        p = p with { Pos = p.Pos + p.Vel * dt, Life = p.Life - dt };

        if (p.Life <= 0) { projectiles.RemoveAt(i); continue; }

        bool hit = false;
        foreach (var enemy in enemies)
        {
            if (enemy.Dead) continue;
            if (!Raylib.CheckCollisionPointRec(p.Pos, enemy.Bounds)) continue;

            int baseDmg  = p.AmmoType == "Bolts" ? 18 : 12;
            int dmg      = baseDmg + (player.RangedLevel / 5);
            enemy.Health -= dmg;
            enemy.TriggerFlash();
            SpawnSplat(enemy.Center, new Color((byte)170, (byte)20, (byte)20, (byte)255));
            if (enemy.Health <= 0)
            {
                enemy.Dead = true;
                SpawnDeathFx(enemy.Center, enemy.EnemyColor, enemy.Type);
            }


            floatingTexts.Add(new FloatingText {
                Position = enemy.Position - new Vector2(0, 20),
                Text = $"-{dmg}",
                Timer = 1f,
                TextColor = Color.Orange
            });

            int actualDmg = Math.Min(dmg, Math.Max(0, enemy.Health + dmg)); // HP dealt
            player.AddRangedXP(Math.Max(1, actualDmg));
            hit = true;  
            break; 
        }

        // also check the world boss
        if (!hit && worldBoss != null && !worldBoss.Dead
    && Raylib.CheckCollisionPointRec(p.Pos, worldBoss.Bounds))
{
    int dmg = p.AmmoType == "Bolts" ? 18 : 12;

    if (multiplayer.IsHost || !multiplayer.Connected)
    {
        worldBoss.Health -= dmg;
        if (worldBoss.Health <= 0) worldBoss.Dead = true;
        if (multiplayer.Connected)
            multiplayer.BroadcastBossState(false, worldBoss.Health, worldBoss.MaxHealth, worldBoss.Dead,
                worldBoss.Position.X, worldBoss.Position.Y);
    }
    else
    {
        multiplayer.SendBossHit(false, dmg);
    }

    player.AddRangedXP(p.AmmoType == "Bolts" ? 6 : 4);
    hit = true;
}

        if (hit) projectiles.RemoveAt(i);
        else     projectiles[i] = p;
    }
}

static void UpdateRemoteVisualProjectiles(float dt)
{
    for (int i = remoteVisualProjectiles.Count - 1; i >= 0; i--)
    {
        var p = remoteVisualProjectiles[i];
        p.Pos += p.Vel * dt;
        p.Life -= dt;
        if (p.Life <= 0) remoteVisualProjectiles.RemoveAt(i);
    }
}
static float bossSyncTimer = 0f;
static float superBossSyncTimer = 0f;
static void UpdateWorldBoss(WorldBoss boss, float dt)
{
    if (boss == null) return;
    bool isSuper = boss.ShakesWhenNear;
    bool amHost = multiplayer.IsHost && multiplayer.Connected;

    if (amHost)
    {
        boss.Update(dt, player.Center);

        if (isSuper)
        {
            superBossSyncTimer -= dt;
            if (superBossSyncTimer <= 0f)
            {
                superBossSyncTimer = 0.1f;
                multiplayer.BroadcastBossState(true, boss.Health, boss.MaxHealth, boss.Dead,
                    boss.Position.X, boss.Position.Y);
            }
        }
        else
        {
            bossSyncTimer -= dt;
            if (bossSyncTimer <= 0f)
            {
                bossSyncTimer = 0.1f;
                multiplayer.BroadcastBossState(false, boss.Health, boss.MaxHealth, boss.Dead,
                    boss.Position.X, boss.Position.Y);
            }
        }
    }
    else if (!multiplayer.Connected)
    {
        boss.Update(dt, player.Center);
    }
    // else: client — boss state comes entirely from BossStateReceived; no local Update() at all.

    if (boss.Dead) return;

    // proximity rumble for super bosses
    if (boss.ShakesWhenNear)
    {
        float dist = Vector2.Distance(player.Center, boss.Center);
        if (dist < boss.ProximityShakeRange)
        {
            float intensity = 0.15f * (1f - dist / boss.ProximityShakeRange);
            TriggerShake(intensity);
        }
    }

    // contact damage
    if (Raylib.CheckCollisionRecs(player.Bounds, boss.Bounds) && boss.AttackCooldown <= 0)
    {
        int def = GetTotalDefense();
        int dmg = Math.Max(1, boss.ContactDamage - def);
        player.TakeDamage(dmg);
        boss.AttackCooldown = 1.0f;
        TriggerShake(0.3f);
        floatingTexts.Add(new FloatingText {
            Position = player.Position - new Vector2(0, 20),
            Text = $"-{dmg}", Timer = 1f, TextColor = Color.Red
        });
    }

    // player melee
    float reach = 70f;
    Rectangle hitBox = new Rectangle(
        boss.Position.X - reach, boss.Position.Y - reach,
        boss.Size + reach * 2, boss.Size + reach * 2);

    if (Raylib.CheckCollisionRecs(player.Bounds, hitBox)
        && (Raylib.IsKeyPressed(KeyboardKey.Space) || Raylib.IsMouseButtonPressed(MouseButton.Left))
        && currentPhase == HandPhase.Combat)
    {
        string equipped = GetActiveWeapon();
        if (equipped != null && GetItemSlot(equipped) == "WEAPON")
        {
            int dmg = 1 + (player.CombatLevel / 10) + GetWeaponDamage(equipped);

            if (amHost || !multiplayer.Connected)
            {
                boss.Health -= dmg;
                if (boss.Health <= 0)
                {
                    boss.Dead = true;
                    player.AddCombatXP(isSuper ? 1500 : 500);
                    player.Money += isSuper ? 3000 : 1000;
                    ShowLevelUp($"{boss.Name} defeated!", 0);
                    if (Raylib.GetRandomValue(1, 100) <= eggDropChance)
                    {
                        string egg = $"{boss.Name} Egg";
                        droppedEggs.Add((boss.Center, egg, 0f));
                        ShowNotification($" RARE DROP   {egg}!");
                        TriggerShake(0.25f);
                    }
                }
                if (multiplayer.Connected)
                    multiplayer.BroadcastBossState(isSuper, boss.Health, boss.MaxHealth, boss.Dead,
                        boss.Position.X, boss.Position.Y);
            }
            else
            {
                multiplayer.SendBossHit(isSuper, dmg);
            }

            floatingTexts.Add(new FloatingText {
                Position = boss.Center - new Vector2(0, boss.Size / 2f),
                Text = $"-{dmg}", Timer = 1f, TextColor = Color.Orange
            });
        }
    }
}

static int tutorialWoodMark, tutorialMineMark, tutorialFishMark, tutorialCombatMark;

static void SnapshotTutorialMarks()
{
    tutorialWoodMark   = player.WoodcuttingXP;
    tutorialMineMark   = player.MiningXP;
    tutorialFishMark   = player.FishingXP;
    tutorialCombatMark = player.CombatXP;
}
static void AcquireGear(string item, bool announce = true)
{
    player.AddGear(item);

    string slot = GetItemSlot(item);
    if (slot == null) { if (announce) ShowNotification($"Got {item}!"); return; }

    // figure out if the target slot is empty
    bool slotEmpty = slot switch
    {
        "HELMET" => armorHelmet == null,
        "BODY"   => armorBody   == null,
        "LEGS"   => armorLegs   == null,
        "BOOTS"  => armorBoots  == null,
        "GLOVES" => armorGloves == null,
        "CAPE"   => armorCape   == null,
        "WEAPON" => armorWeapon == null,
        "SHIELD" => armorShield == null,
        _ => false
    };

    if (slotEmpty)
    {
        // respect two-handed rules on auto-equip
        if (slot == "SHIELD" && IsTwoHandedWeapon(armorWeapon))
        {
            if (announce) ShowNotification($"Got {item} (stored — 2H weapon equipped)");
            return;
        }
        if (slot == "WEAPON" && IsTwoHandedWeapon(item) && armorShield != null)
        {
            if (announce) ShowNotification($"Got {item} (stored — unequip shield to use)");
            return;
        }
        TryEquipItem(item);
    }
    else if (announce)
    {
        ShowNotification($"Got {item}! (stored in gear)");
    }
}
static bool IsGearSellable(string item)
{
    // basic/common gear can be sold; rare or starter gear can't
    return item switch
    {
        "Leather Cap" or "Leather Vest" or "Leather Pants" or "Leather Boots" or "Leather Gloves"
            or "Iron Helmet" or "Iron Chestplate" or "Iron Leggings" or "Iron Boots" or "Iron Gauntlets"
            or "Wooden Shield" or "Iron Shield" or "Wool Cape" or "Sword"
            => true,
        // not sellable: steel tier, magic cape, two-handers, bows/crossbows
        _ => false
    };
}

static int GetGearSellPrice(string item)
{
    return item switch
    {
        "Leather Cap" or "Leather Vest" or "Leather Pants" or "Leather Boots" or "Leather Gloves" => 15,
        "Iron Helmet" or "Iron Chestplate" or "Iron Leggings" or "Iron Boots" or "Iron Gauntlets" => 40,
        "Wooden Shield" => 20,
        "Iron Shield" => 45,
        "Wool Cape" => 25,
        "Sword" => 50,
        _ => 0
    };
}
static bool IsTwoHandedMeleeWeapon(string w) =>
    w != null && (w.Contains("Great Sword") || w.Contains("War Axe"));

static bool IsOneHandedWeapon(string w) =>
    w != null && !IsTwoHandedMeleeWeapon(w) && (w.Contains("Sword") || w.Contains("Stick"));

static bool IsRangedWeapon(string w) =>
    w != null && (w.Contains("Bow") || w.Contains("Crossbow"));

static void AwardMeleeXP(string weapon, int amount)
{
    if (IsTwoHandedMeleeWeapon(weapon)) player.AddTwoHandMeleeXP(amount);
    else                                player.AddOneHandMeleeXP(amount);
}

// weapons the player owns, split by hand
static List<string> OwnedOneHanded()
{
    var list = new List<string>();

    // owned-gear one-handers
    foreach (var g in player.OwnedGear)
        if (IsOneHandedWeapon(g) && !list.Contains(g)) list.Add(g);

    // flag-based weapons (Sword, Stick)
    if (swordPickedUp && !list.Contains("Sword")) list.Add("Sword");
    if (stickPickedUp && !list.Contains("Stick")) list.Add("Stick");

    // staffs (1H = plain staff, not "Great")
    foreach (var g in player.OwnedGear)
        if (g.EndsWith("Staff") && !g.Contains("Great") && !list.Contains(g)) list.Add(g);

    return list;
}
static List<string> OwnedTwoHanded()
{
    var list = new List<string>();
    foreach (var g in player.OwnedGear)
        if ((IsTwoHandedWeapon(g) || IsRangedWeapon(g)) && !list.Contains(g)) list.Add(g);

    // flag-based ranged weapons (plain Bow / Crossbow)
    if (player.HasBow && !list.Contains("Bow")) list.Add("Bow");
    if (player.HasCrossbow && !list.Contains("Crossbow")) list.Add("Crossbow");

    // great staffs (2H)
    foreach (var g in player.OwnedGear)
        if (g.Contains("Great") && g.EndsWith("Staff") && !list.Contains(g)) list.Add(g);

    return list;
}
static void Cycle1HSlot()
{
    var owned = OwnedOneHanded();
    if (owned.Count == 0)
    {
        if (equipped1H == "Sword") swordPickedUp = true;
        else if (equipped1H == "Stick") stickPickedUp = true;
        equipped1H = null;
        armorWeapon = null;
        player.EquippedStaff = null;
        return;
    }

    int idx = equipped1H == null ? -1 : owned.IndexOf(equipped1H);
    idx++;
    if (idx >= owned.Count)
    {
        if (equipped1H == "Sword") swordPickedUp = true;
        else if (equipped1H == "Stick") stickPickedUp = true;
        equipped1H = null;
        equipped2H = null;
        armorWeapon = null;
        player.EquippedStaff = null;
    }
    else
    {
        equipped1H = owned[idx];
        equipped2H = null;
        armorWeapon = equipped1H;
        player.EquippedStaff = equipped1H.EndsWith("Staff") ? equipped1H : null;
    }
}
static void Cycle2HSlot()
{
    var owned = OwnedTwoHanded();
    if (owned.Count == 0)
    {
        if (equipped2H == "Bow") player.HasBow = true;
        else if (equipped2H == "Crossbow") player.HasCrossbow = true;
        equipped2H = null;
        armorWeapon = null;
        player.EquippedStaff = null;
        return;
    }

    int idx = equipped2H == null ? -1 : owned.IndexOf(equipped2H);
    idx++;
    if (idx >= owned.Count)
    {
        if (equipped2H == "Bow") player.HasBow = true;
        else if (equipped2H == "Crossbow") player.HasCrossbow = true;
        equipped2H = null;
        armorWeapon = null;
        player.EquippedStaff = null;
    }
    else
    {
        equipped2H = owned[idx];
    }

    if (equipped2H != null)
    {
        equipped1H = null;
        armorShield = null;
        armorWeapon = equipped2H;
        player.EquippedStaff = equipped2H.EndsWith("Staff") ? equipped2H : null;
    }
    else if (equipped1H == null)
    {
        armorWeapon = null;
        player.EquippedStaff = null;
    }
}

static void CycleAmmoSlot()
{
    var opts = new List<string>();
    if (player.Arrows > 0) opts.Add("Arrows");
    if (player.Bolts > 0)  opts.Add("Bolts");
    if (player.ArcaneEssence > 0) opts.Add("Arcane Essence");
    if (opts.Count == 0) { equippedAmmo = null; return; }

    int idx = equippedAmmo == null ? -1 : opts.IndexOf(equippedAmmo);
    idx++;
    equippedAmmo = idx >= opts.Count ? null : opts[idx];
}
static int ChestSlotsUsed(int[] chestCounts)
{
    int used = 0;
    foreach (int c in chestCounts)
        if (c > 0) used++;
    return used;
}

static void TryStartFishing(string water)
