static void StartTennisPoint(bool playerServes)
{
    tennisPlayerServing = playerServes;
    tennisServePhase = 1;
    tennisServeToss = 0f;
    tennisServeTossUp = true;
    tennisServeTimer = 0f;
    tennisBallInFlight = false;
    tennisBallBounced = false;
    tennisSwinging = false;

    // position players at their baselines
    tennisPlayerPos = new Vector2(CourtLeft + 60, (CourtTop + CourtBottom) / 2f);
    tennisAIPos     = new Vector2(CourtRight - 60, (CourtTop + CourtBottom) / 2f);

    // ball starts at the server's racket
    tennisBallPos = playerServes
        ? new Vector2(tennisPlayerPos.X + 20, tennisPlayerPos.Y)
        : new Vector2(tennisAIPos.X - 20, tennisAIPos.Y);
}

static void HitBall(Vector2 from, Vector2 target, float power, bool towardPlayer)
{
    tennisBallStart = from;
    tennisBallTarget = target;
    tennisBallPos = from;
    tennisBallT = 0f;
    tennisBallDuration = Math.Clamp(Vector2.Distance(from, target) / (power), 0.45f, 1.4f);
    tennisBallInFlight = true;
    tennisBallBounced = false;
    tennisBallToPlayer = towardPlayer;
}

static bool InCourt(Vector2 p, bool playerHalf)
{
    if (p.Y < CourtTop || p.Y > CourtBottom) return false;
    if (playerHalf) return p.X >= CourtLeft && p.X <= CourtMidX;
    return p.X >= CourtMidX && p.X <= CourtRight;
}

static void TennisPoint(bool playerWon)
{
    if (playerWon)
    {
        tennisPlayerScore++;
        player.AddSportsXP(8);
        tennisLastResult = "You win the point!";
    }
    else
    {
        tennisAIScore++;
        tennisLastResult = "AI wins the point.";
    }

    if (tennisPlayerScore >= tennisPointsToWin)
    {
        tennisMessage = "GAME! You win the match! +40 Sports XP";
        tennisMessageTimer = 4f;
        player.AddSportsXP(40);
        tennisActive = false;
        return;
    }
    if (tennisAIScore >= tennisPointsToWin)
    {
        tennisMessage = "Match over — AI wins.";
        tennisMessageTimer = 4f;
        tennisActive = false;
        return;
    }

    tennisMessage = $"{tennisLastResult}  {tennisPlayerScore} - {tennisAIScore}";
    tennisMessageTimer = 2f;
    // loser serves next
    StartTennisPoint(!playerWon ? true : false);
}

static void UpdateTennisPlay(float dt)
{
    const float reach = 70f;   // how close you must be to swing at the ball

    // ---- PLAYER MOVEMENT (free roam own half) ----
    Vector2 mv = Vector2.Zero;
    if (Raylib.IsKeyDown(KeyboardKey.W) || Raylib.IsKeyDown(KeyboardKey.Up))    mv.Y -= 1;
    if (Raylib.IsKeyDown(KeyboardKey.S) || Raylib.IsKeyDown(KeyboardKey.Down))  mv.Y += 1;
    if (Raylib.IsKeyDown(KeyboardKey.A) || Raylib.IsKeyDown(KeyboardKey.Left))  mv.X -= 1;
    if (Raylib.IsKeyDown(KeyboardKey.D) || Raylib.IsKeyDown(KeyboardKey.Right)) mv.X += 1;
    if (mv != Vector2.Zero) mv = Vector2.Normalize(mv);
    tennisPlayerPos += mv * tennisPlayerSpeed * dt;
    tennisPlayerPos.X = Math.Clamp(tennisPlayerPos.X, CourtLeft, CourtMidX - 10);
    tennisPlayerPos.Y = Math.Clamp(tennisPlayerPos.Y, CourtTop, CourtBottom);

    // trigger a swing
    if (tennisServePhase == 0 && tennisBallInFlight && Raylib.IsKeyPressed(KeyboardKey.Space) && tennisSwingCooldown <= 0)
    {
        tennisSwinging = true;
        tennisSwingTimer = 0.25f;     // quarter-second window to connect
        tennisSwingCooldown = 0.35f;
    }

    // swing window
    if (tennisSwinging)
    {
        tennisSwingTimer -= dt;
        if (tennisSwingTimer <= 0) tennisSwinging = false;
    }

    // ---- SERVE ----
    if (tennisServePhase != 0)
    {
        if (tennisPlayerServing)
        {
            // hold SPACE to build toss power, release to serve
            if (Raylib.IsKeyDown(KeyboardKey.Space))
            {
                tennisServePhase = 2;
                tennisServeToss += (tennisServeTossUp ? 1f : -1f) * 1.3f * dt;
                if (tennisServeToss >= 1f) { tennisServeToss = 1f; tennisServeTossUp = false; }
                if (tennisServeToss <= 0f) { tennisServeToss = 0f; tennisServeTossUp = true; }
                tennisBallPos = new Vector2(tennisPlayerPos.X + 20, tennisPlayerPos.Y);
            }
            else if (tennisServePhase == 2)
            {
                // released — serve toward AI service box
                float power = 700f + tennisServeToss * 500f;
                Vector2 target = new Vector2(
                    CourtMidX + Raylib.GetRandomValue(60, (int)(CourtRight - CourtMidX - 40)),
                    Raylib.GetRandomValue((int)CourtTop + 40, (int)CourtBottom - 40));
                HitBall(tennisBallPos, target, power, false);
                tennisServePhase = 0;
            }
        }
        else
        {
            // AI serve after a short delay
            tennisServeTimer += dt;
            tennisBallPos = new Vector2(tennisAIPos.X - 20, tennisAIPos.Y);
            if (tennisServeTimer > 1.0f)
            {
                Vector2 target = new Vector2(
                    Raylib.GetRandomValue((int)CourtLeft + 40, (int)CourtMidX - 40),
                    Raylib.GetRandomValue((int)CourtTop + 40, (int)CourtBottom - 40));
                HitBall(tennisBallPos, target, 850f, true);
                tennisServePhase = 0;
            }
        }
        return;
    }

    // ---- BALL IN FLIGHT ----
    if (tennisBallInFlight)
    {
        tennisBallT += dt / tennisBallDuration;
        tennisBallPos = Vector2.Lerp(tennisBallStart, tennisBallTarget, Math.Min(tennisBallT, 1f));

        // ---- AI MOVEMENT: chase the ball when it's coming to its side ----
        if (!tennisBallToPlayer)
        {
            Vector2 aiTarget = tennisBallTarget;
            Vector2 dir = aiTarget - tennisAIPos;
            if (dir.Length() > 4f)
                tennisAIPos += Vector2.Normalize(dir) * Math.Min(dir.Length(), tennisAIMaxSpeed * dt);
            tennisAIPos.X = Math.Clamp(tennisAIPos.X, CourtMidX + 10, CourtRight);
            tennisAIPos.Y = Math.Clamp(tennisAIPos.Y, CourtTop, CourtBottom);
        }

        // ball lands
        if (tennisBallT >= 1f)
        {
            bool landedInPlayerHalf = tennisBallToPlayer;
            bool landedIn = InCourt(tennisBallTarget, landedInPlayerHalf);

            if (!landedIn)
            {
                // shot went out — point to the receiver of this shot's hitter
                // if ball was heading to player and landed out, the hitter (AI) loses the point
                TennisPoint(tennisBallToPlayer ? true : false);
                return;
            }

            // ball bounced in — now the receiver must return it
            if (tennisBallToPlayer)
            {
                // PLAYER must swing in time and be near the ball
                bool near = Vector2.Distance(tennisPlayerPos, tennisBallPos) < reach;
                if (tennisSwinging && near)
                {
                    // return toward AI side, aim based on player vertical position
                    float power = 750f + Raylib.GetRandomValue(0, 200);
                    Vector2 target = new Vector2(
                        CourtMidX + Raylib.GetRandomValue(40, (int)(CourtRight - CourtMidX)),
                        Math.Clamp(tennisPlayerPos.Y + Raylib.GetRandomValue(-120, 120), CourtTop, CourtBottom));
                    HitBall(tennisBallPos, target, power, false);
                    player.AddSportsXP(3);
                }
                else
                {
                    TennisPoint(false); // missed the return
                }
            }
            else
            {
                // AI returns automatically if it reached the ball
                bool aiNear = Vector2.Distance(tennisAIPos, tennisBallPos) < reach + 10f;
                if (aiNear)
                {
                    float power = 720f;
                    Vector2 target = new Vector2(
                        Raylib.GetRandomValue((int)CourtLeft + 30, (int)CourtMidX - 20),
                        Math.Clamp(tennisAIPos.Y + Raylib.GetRandomValue(-140, 140), CourtTop, CourtBottom));
                    HitBall(tennisBallPos, target, power, true);
                }
                else
                {
                    TennisPoint(true); // AI couldn't reach
                }
            }
        }
    }
}
static void CookRawItemFromToolbar(string rawItem)
{
    if (isCooking || quickCooking) return;   // already cooking — no spam

    string result = rawItem switch {
        "Fish"     => "Cooked Fish",
        "Raw Meat" => "Cooked Meat",
        "Potato"   => "Roast Potato",
        "Corn"     => "Cooked Corn",
        _ => null
    };
    if (result == null) return;

    int slot = toolbarSelectedSlot;
    if (toolbarSlots[slot] != rawItem || toolbarCounts[slot] <= 0) return;

    // need somewhere for the output; the slot frees if this is the last raw one
    bool slotWillFree = toolbarCounts[slot] == 1;
    bool hasRoom = slotWillFree
                || toolbarSlots.Any(s => s == result || s == "Ashes")
                || !ToolbarFull();
    if (!hasRoom)
    {
        ShowNotification("Your inventory is too full to cook!");
        return;
    }

    // start the timed cook
    quickCooking   = true;
    quickCookTimer = QuickCookDuration;
    quickCookRaw   = rawItem;
    quickCookResult = result;
    quickCookSlot  = slot;
}
static void UpdateQuickCook(float dt)
{
    if (!quickCooking) return;

    quickCookTimer -= dt;
    if (quickCookTimer > 0f) return;

    quickCooking = false;

    // validate the slot still holds the raw item (player may have swapped)
    if (quickCookSlot < 0 || quickCookSlot >= toolbarSlots.Length
        || toolbarSlots[quickCookSlot] != quickCookRaw
        || toolbarCounts[quickCookSlot] <= 0)
    {
        ShowNotification("Cooking cancelled.");
        return;
    }

    // consume one raw item
    toolbarCounts[quickCookSlot]--;
    if (toolbarCounts[quickCookSlot] <= 0) toolbarSlots[quickCookSlot] = null;

    // burn chance: 30% base, -2% per cooking level, floor 5%
    float burnChance = Math.Max(0.05f, 0.30f - (player.CookingLevel * 0.02f));
    bool burned = Raylib.GetRandomValue(0, 100) < (int)(burnChance * 100);

    string output = burned ? "Ashes" : quickCookResult;
    if (!AddOneItemToToolbar(output))
    {
        ShowNotification("Your inventory is too full to cook!");
        return;
    }

    if (burned)
    {
        ShowNotification($"Burnt the {quickCookRaw}! Got Ashes.");
        player.AddCookingXP(2);
    }
    else
    {
        int xp = quickCookResult == "Cooked Meat" ? 12 : 10;
        player.AddCookingXP(xp);
        ShowNotification($"Cooked {quickCookResult}! +{xp} Cooking XP");
    }
}
static void DrawQuickCookBar()
{
    if (!quickCooking) return;

    int bw = 360, bh = 22;
    int bx = ScreenWidth / 2 - bw / 2;
    int by = ScreenHeight - 160;

    float prog = Math.Clamp(1f - quickCookTimer / QuickCookDuration, 0f, 1f);
    Color orange = new Color((byte)220,(byte)120,(byte)20,(byte)255);

    Raylib.DrawRectangle(bx - 4, by - 22, bw + 8, bh + 30, new Color((byte)0,(byte)0,(byte)0,(byte)180));
    Raylib.DrawText($"Cooking {quickCookRaw}...", bx, by - 20, 16, Color.LightGray);
    Raylib.DrawRectangle(bx, by, bw, bh, new Color((byte)40,(byte)40,(byte)40,(byte)255));
    Raylib.DrawRectangle(bx, by, (int)(bw * prog), bh, orange);
    Raylib.DrawRectangleLines(bx, by, bw, bh, Color.White);
}
static void DrawCookingMenu()
{
    if (!cookingMenuOpen) return;

    bool isKitchen = cookingContext == "kitchen";
    var available = cookingRecipes.Where(r => !r.KitchenOnly || isKitchen).ToArray();

    int px = ScreenWidth/2 - 360, py = 50;
    int pw = 720, ph = 560;
    Color orange = new Color((byte)220,(byte)120,(byte)20,(byte)255);

    Raylib.DrawRectangle(px, py, pw, ph, new Color((byte)15,(byte)10,(byte)5,(byte)245));
    Raylib.DrawRectangleLines(px, py, pw, ph, orange);
    string title = isKitchen ? "KITCHEN — COOK" : "CAMPFIRE — COOK";
    Raylib.DrawText(title, px + pw/2 - Raylib.MeasureText(title,26)/2, py + 10, 26, orange);
    Raylib.DrawText($"Cooking Lv {player.CookingLevel}", px + 10, py + 10, 16, Color.LightGray);

    // cooking progress bar
    if (isCooking)
    {
        cookingTimer -= Raylib.GetFrameTime();
        int bw = pw - 40;
        float prog = Math.Max(0, 1f - cookingTimer / 2f);
        Raylib.DrawRectangle(px + 20, py + 46, bw, 14, new Color((byte)40,(byte)40,(byte)40,(byte)255));
        Raylib.DrawRectangle(px + 20, py + 46, (int)(bw * prog), 14, orange);
        Raylib.DrawRectangleLines(px + 20, py + 46, bw, 14, Color.White);
        Raylib.DrawText($"Cooking {cookingItem}...", px + 20, py + 64, 16, Color.LightGray);
        if (cookingTimer <= 0f)
        {
            isCooking = false;
            AddToToolbar(cookingItem);
            player.AddCookingXP(cookingRecipes.FirstOrDefault(r => r.Result == cookingItem)?.XP ?? 10);
            ShowNotification($"Cooked {cookingItem}!");
        }
        Raylib.DrawText("Q = Cancel", px + pw/2 - 40, py + ph - 20, 16, Color.DarkGray);
        if (Raylib.IsKeyPressed(KeyboardKey.Q)) { isCooking = false; cookingMenuOpen = false; }
        return;
    }

    Vector2 mouse = Raylib.GetMousePosition();
    int rowH = 68, startY = py + 86;

    for (int i = 0; i < available.Length; i++)
    {
        var r = available[i];
        bool canCook = CanCook(r);
        Rectangle row = new Rectangle(px + 12, startY + i * rowH, pw - 24, rowH - 6);
        bool hover = canCook && Raylib.CheckCollisionPointRec(mouse, row);

        Raylib.DrawRectangleRec(row, new Color((byte)25,(byte)15,(byte)5,(byte)255));
        Raylib.DrawRectangleLinesEx(row, hover ? 2 : 1, hover ? orange : (canCook ? new Color((byte)80,(byte)50,(byte)10,(byte)255) : new Color((byte)40,(byte)40,(byte)40,(byte)255)));

        // result name
        Color nameCol = canCook ? Color.White : Color.DarkGray;
        Raylib.DrawText(r.Result, px + 22, startY + i * rowH + 8, 20, nameCol);
        // HP restore
        Raylib.DrawText($"+{r.HpRestore} HP", px + 22, startY + i * rowH + 32, 14, canCook ? new Color((byte)80,(byte)200,(byte)80,(byte)255) : Color.DarkGray);
        // XP
        Raylib.DrawText($"+{r.XP} XP", px + 110, startY + i * rowH + 32, 14, canCook ? new Color((byte)200,(byte)160,(byte)20,(byte)255) : Color.DarkGray);
        // ingredients
        string ingList = string.Join(" + ", r.Ingredients);
        Raylib.DrawText(ingList, px + 220, startY + i * rowH + 22, 14, canCook ? Color.LightGray : Color.DarkGray);
        // kitchen only tag
        if (r.KitchenOnly)
            Raylib.DrawText("[Kitchen]", px + pw - 110, startY + i * rowH + 8, 13, new Color((byte)100,(byte)160,(byte)220,(byte)255));

        if (hover && Raylib.IsMouseButtonPressed(MouseButton.Left))
        {
            ConsumeIngredients(r);
            cookingItem = r.Result;
            isCooking = true;
            cookingTimer = 2f;
        }
    }

    Raylib.DrawText("Q = Close", px + pw/2 - 38, py + ph - 20, 16, Color.DarkGray);
    if (Raylib.IsKeyPressed(KeyboardKey.Q)) cookingMenuOpen = false;
}

static void DrawAAMenu()
{
    if (!aaMenuOpen || currentBuilding?.BuildingName != "AA") return;

    Color aaBlue = new Color((byte)0,(byte)80,(byte)160,(byte)255);
    int px = ScreenWidth/2 - 300, py = 60;
    Raylib.DrawRectangle(px, py, 600, 520, new Color((byte)5,(byte)20,(byte)40,(byte)245));
    Raylib.DrawRectangleLines(px, py, 600, 520, aaBlue);
    Raylib.DrawText("AA DRIVING SERVICES", px + 130, py + 12, 26, new Color((byte)0,(byte)200,(byte)255,(byte)255));
    Raylib.DrawText($"Driving Lv {player.DrivingLevel}  |  Class: {CurrentLicenceClass}  |  ${player.Money}", px + 60, py + 46, 16, Color.LightGray);

    // current licence status
    Raylib.DrawText($"Theory: {(HasTheoryForCurrentClass ? "PASSED " : "NOT PASSED")}",   px + 20, py + 80, 18, HasTheoryForCurrentClass ? Color.Green : Color.Red);
    Raylib.DrawText($"Practical: {(HasPracticalForCurrentClass ? "PASSED " : "NOT PASSED")}", px + 20, py + 104, 18, HasPracticalForCurrentClass ? Color.Green : Color.Red);
