    Vector2 mouse = Raylib.GetMousePosition();

    // Theory test button
    bool theoryAvail = !HasTheoryForCurrentClass;
    Rectangle theoryBtn = new Rectangle(px + 20, py + 170, 560, 60);
    bool hT = Raylib.CheckCollisionPointRec(mouse, theoryBtn);
    Raylib.DrawRectangleRec(theoryBtn, theoryAvail ? new Color((byte)0,(byte)40,(byte)80,(byte)255) : new Color((byte)20,(byte)20,(byte)20,(byte)255));
    Raylib.DrawRectangleLinesEx(theoryBtn, 2, theoryAvail && hT ? Color.Gold : aaBlue);
    Raylib.DrawText($"THEORY TEST  Class {CurrentLicenceClass}  ($50)", px + 30, py + 182, 20, theoryAvail ? Color.White : Color.DarkGray);
    Raylib.DrawText(theoryAvail ? "10 questions, need 8/10 to pass" : "Already passed ", px + 30, py + 204, 14, theoryAvail ? Color.LightGray : Color.Green);
    if (theoryAvail && hT && Raylib.IsMouseButtonPressed(MouseButton.Left))
    {
        if (player.Money >= 50)
        {
            player.Money -= 50;
            aaTheoryQuestion = 0;
            aaTheoryScore = 0;
            aaTheorySelected = -1;
            aaTheoryFinished = false;
            aaTheoryPassed = false;
            aaTheoryOpen = true;
            aaMenuOpen = false;
        }
        else { shopMessage = "Need $50 for the theory test bro!"; shopMessageTimer = 2f; }
    }

    // Practical test button
    bool practAvail = HasTheoryForCurrentClass && PracticalAvailable;
    Rectangle practBtn = new Rectangle(px + 20, py + 250, 560, 60);
    bool hP = Raylib.CheckCollisionPointRec(mouse, practBtn);
    Raylib.DrawRectangleRec(practBtn, practAvail ? new Color((byte)0,(byte)60,(byte)20,(byte)255) : new Color((byte)20,(byte)20,(byte)20,(byte)255));
    Raylib.DrawRectangleLinesEx(practBtn, 2, practAvail && hP ? Color.Gold : new Color((byte)0,(byte)100,(byte)40,(byte)255));

    string practLabel = !HasTheoryForCurrentClass ? "Pass theory first!" :
                        !PracticalAvailable       ? $"Reach Lv {PracticalUnlockLevel()} first" :
                                                    $"PRACTICAL TEST — Class {CurrentLicenceClass}  ($100)";
    Raylib.DrawText(practLabel, px + 30, py + 262, 20, practAvail ? Color.White : Color.DarkGray);
    Raylib.DrawText(practAvail ? "Drive a test course within time limit" : "", px + 30, py + 284, 14, Color.LightGray);

    if (practAvail && hP && Raylib.IsMouseButtonPressed(MouseButton.Left))
    {
        if (player.Money >= 100)
        {
            player.Money -= 100;
            preTestScene = currentScene;
            StartDrivingTest();
            aaMenuOpen = false;
        }
        else { shopMessage = "Need $100 for the practical test bro!"; shopMessageTimer = 2f; }
    }

    // Licence info panel
    Raylib.DrawRectangle(px + 20, py + 330, 560, 160, new Color((byte)5,(byte)15,(byte)30,(byte)255));
    Raylib.DrawRectangleLines(px + 20, py + 330, 560, 160, new Color((byte)0,(byte)60,(byte)100,(byte)255));
    Raylib.DrawText("LICENCE CLASSES", px + 190, py + 340, 18, new Color((byte)0,(byte)200,(byte)255,(byte)255));
    string[] info = {
        "D (Lv 1-19)  — Basic vehicles, 6am-10pm restricted",
        "C (Lv 20-39) — All standard vehicles",
        "B (Lv 40-59) — Trucks & large vehicles",
        "A (Lv 60-79) — High performance vehicles",
        "S (Lv 80+)   — Unrestricted, all vehicles anytime"
    };
    for (int i = 0; i < 5; i++)
        Raylib.DrawText(info[i], px + 30, py + 362 + i * 22, 13, i == (int)CurrentLicenceClass - 1 ? Color.Gold : Color.LightGray);

    Raylib.DrawText("Q = Close", px + 260, py + 498, 18, Color.DarkGray);
    if (Raylib.IsKeyPressed(KeyboardKey.Q)) aaMenuOpen = false;
}

static int PracticalUnlockLevel() => CurrentLicenceClass switch {
    LicenceClass.D => 10, LicenceClass.C => 30, LicenceClass.B => 50,
    LicenceClass.A => 70, LicenceClass.S => 90, _ => 999
};

static void DrawAATheoryTest()
{
    if (!aaTheoryOpen || currentBuilding?.BuildingName != "AA") return;

    int testIdx = (int)CurrentLicenceClass - 1;
    var questions = theoryTests[Math.Clamp(testIdx, 0, 4)];

    Color aaBlue = new Color((byte)0,(byte)80,(byte)160,(byte)255);
    int px = ScreenWidth/2 - 380, py = 40;
    Raylib.DrawRectangle(px, py, 760, 620, new Color((byte)5,(byte)15,(byte)30,(byte)245));
    Raylib.DrawRectangleLines(px, py, 760, 620, aaBlue);
    Raylib.DrawText($"THEORY TEST — Class {CurrentLicenceClass}", px + 210, py + 12, 26, new Color((byte)0,(byte)200,(byte)255,(byte)255));

    if (aaTheoryFinished)
    {
        // results screen
        Color resCol = aaTheoryPassed ? Color.Green : Color.Red;
        string resText = aaTheoryPassed ? "PASSED! ✓" : "FAILED ✗";
        int rw = Raylib.MeasureText(resText, 40);
        Raylib.DrawText(resText, px + 380 - rw/2, py + 160, 40, resCol);
        Raylib.DrawText($"Score: {aaTheoryScore} / {questions.Length}", px + 300, py + 220, 26, Color.White);
        Raylib.DrawText(aaTheoryPassed ? "Your theory licence is now active!" : "Need 8/10 to pass. Try again ($50).", px + 80, py + 270, 20, Color.LightGray);

        Rectangle closeBtn = new Rectangle(px + 280, py + 340, 200, 50);
        bool hC = Raylib.CheckCollisionPointRec(Raylib.GetMousePosition(), closeBtn);
        Raylib.DrawRectangleRec(closeBtn, new Color((byte)0,(byte)40,(byte)80,(byte)255));
        Raylib.DrawRectangleLinesEx(closeBtn, 2, hC ? Color.Gold : aaBlue);
        Raylib.DrawText("Continue", px + 320, py + 357, 22, hC ? Color.Gold : Color.White);
        if ((hC && Raylib.IsMouseButtonPressed(MouseButton.Left)) || Raylib.IsKeyPressed(KeyboardKey.Q))
        {
            aaTheoryOpen = false;
            aaMenuOpen = true;
        }
        return;
    }

    var q = questions[aaTheoryQuestion];
    Raylib.DrawText($"Question {aaTheoryQuestion + 1} of {questions.Length}   Score: {aaTheoryScore}", px + 20, py + 50, 16, Color.LightGray);

    // progress bar
    float prog = (float)aaTheoryQuestion / questions.Length;
    Raylib.DrawRectangle(px + 20, py + 72, 720, 10, new Color((byte)20,(byte)20,(byte)40,(byte)255));
    Raylib.DrawRectangle(px + 20, py + 72, (int)(720 * prog), 10, aaBlue);

    // question
    Raylib.DrawText(q.Question, px + 20, py + 100, 22, Color.White);

    // options
    Vector2 mouse = Raylib.GetMousePosition();
    for (int i = 0; i < q.Options.Length; i++)
    {
        Rectangle opt = new Rectangle(px + 20, py + 160 + i * 80, 720, 68);
        bool hover = Raylib.CheckCollisionPointRec(mouse, opt) && aaTheorySelected < 0;
        Color bg = aaTheorySelected >= 0
            ? (i == q.Correct ? new Color((byte)0,(byte)80,(byte)20,(byte)255)
               : i == aaTheorySelected ? new Color((byte)80,(byte)10,(byte)10,(byte)255)
               : new Color((byte)20,(byte)20,(byte)30,(byte)255))
            : hover ? new Color((byte)0,(byte)50,(byte)100,(byte)255) : new Color((byte)15,(byte)25,(byte)45,(byte)255);
        Color border = aaTheorySelected >= 0
            ? (i == q.Correct ? Color.Green : i == aaTheorySelected ? Color.Red : new Color((byte)40,(byte)40,(byte)60,(byte)255))
            : hover ? Color.Gold : aaBlue;

        Raylib.DrawRectangleRec(opt, bg);
        Raylib.DrawRectangleLinesEx(opt, 2, border);
        Raylib.DrawText($"{(char)('A' + i)}. {q.Options[i]}", px + 34, py + 175 + i * 80, 20, Color.White);

        if (hover && aaTheorySelected < 0 && Raylib.IsMouseButtonPressed(MouseButton.Left))
        {
            aaTheorySelected = i;
            if (i == q.Correct) aaTheoryScore++;
        }
    }

    // next button after selection
    if (aaTheorySelected >= 0)
    {
        Rectangle nextBtn = new Rectangle(px + 560, py + 560, 180, 44);
        bool hN = Raylib.CheckCollisionPointRec(mouse, nextBtn);
        Raylib.DrawRectangleRec(nextBtn, new Color((byte)0,(byte)60,(byte)130,(byte)255));
        Raylib.DrawRectangleLinesEx(nextBtn, 2, hN ? Color.Gold : aaBlue);
        Raylib.DrawText(aaTheoryQuestion < questions.Length - 1 ? "Next >" : "Finish", px + 590, py + 573, 20, hN ? Color.Gold : Color.White);

        if ((hN && Raylib.IsMouseButtonPressed(MouseButton.Left)) || Raylib.IsKeyPressed(KeyboardKey.Space))
        {
            aaTheoryQuestion++;
            aaTheorySelected = -1;
            if (aaTheoryQuestion >= questions.Length)
            {
                aaTheoryFinished = true;
                aaTheoryPassed = aaTheoryScore >= 8;
                if (aaTheoryPassed)
                {
                    switch (CurrentLicenceClass) {
                        case LicenceClass.D: hasTheoryD = true; break;
                        case LicenceClass.C: hasTheoryC = true; break;
                        case LicenceClass.B: hasTheoryB = true; break;
                        case LicenceClass.A: hasTheoryA = true; break;
                        case LicenceClass.S: hasTheoryS = true; break;
                    }
                }
            }
        }
    }
}
static void StartDrivingTest()
{
    testingForClass = CurrentLicenceClass;
    testReturnPos = player.Position;

    Vehicle.VehicleType vtype = testingForClass switch {
        LicenceClass.D => Vehicle.VehicleType.Sedan,
        LicenceClass.C => Vehicle.VehicleType.SUV,
        LicenceClass.B => Vehicle.VehicleType.Truck,
        LicenceClass.A => Vehicle.VehicleType.Sedan,
        LicenceClass.S => Vehicle.VehicleType.PoliceCar,
        _ => Vehicle.VehicleType.Sedan
    };
    Color vCol = testingForClass switch {
        LicenceClass.D => new Color((byte)60,(byte)120,(byte)200,(byte)255),
        LicenceClass.C => new Color((byte)60,(byte)160,(byte)60,(byte)255),
        LicenceClass.B => new Color((byte)160,(byte)100,(byte)40,(byte)255),
        LicenceClass.A => new Color((byte)180,(byte)20,(byte)20,(byte)255),
        LicenceClass.S => new Color((byte)20,(byte)20,(byte)20,(byte)255),
        _ => Color.Gray
    };
    float spd = testingForClass switch {
        LicenceClass.D => 280f, LicenceClass.C => 340f, LicenceClass.B => 260f,
        LicenceClass.A => 500f, LicenceClass.S => 600f, _ => 300f
    };

    testVehicle = new Vehicle(new Vector2(200, 500), vCol, spd, vtype);
    testVehicle.Driving = true;
    testVehicle.Fuel = 100f;
    player.Hidden = true;

    testCamera = new Camera2D();
    testCamera.Offset = new Vector2(ScreenWidth / 2, ScreenHeight / 2);
    testCamera.Zoom = 1f;
    testCamera.Target = testVehicle.Position;

    testStage = 0;
    testComplete = false;
    testFailed = false;
    testConesHit = 0;
    maxConesAllowed = testingForClass switch {
        LicenceClass.D => 3, LicenceClass.C => 3, LicenceClass.B => 2,
        LicenceClass.A => 1, LicenceClass.S => 0, _ => 3
    };

    LoadStage(0);

    currentScene = SceneState.DrivingTest;
}

static void LoadStage(int stage)
{
    testStage = stage;
    stageFailed = false;
    stageComplete = false;
    testCones.Clear();
    parkingCars.Clear();
    trafficCars.Clear();
    trafficVelocities.Clear();
    laneBoundaries.Clear();

    switch (stage)
    {
        case 0: // ── SLALOM ────────────────────────────────────────────────
            testVehicle.Position = new Vector2(100, 500);
            stageTimeLimit = 30f;
            stageTimer = stageTimeLimit;
            // staggered cones in two rows
            for (int i = 0; i < 8; i++)
            {
                float x = 200 + i * 150f;
                float y = i % 2 == 0 ? 460f : 540f;
                testCones.Add(new Vector2(x, y));
            }
            // end gate cones
            testCones.Add(new Vector2(1450, 460));
            testCones.Add(new Vector2(1450, 540));
            testCheckpoints = new Vector2[] { new Vector2(1500, 500) };
            testCurrentCheckpoint = 0;
            testMessage = "Stage 1: Slalom! Weave through the cones!";
            testMessageTimer = 3f;
            break;

        case 1: // ── BAY PARKING ───────────────────────────────────────────
            testVehicle.Position = new Vector2(400, 300);
            stageTimeLimit = 30f;
            stageTimer = stageTimeLimit;
            parkedSuccessfully = false;
            parkingTimer = 0f;
            // two parked cars either side of the bay
            parkingCars.Add(new Rectangle(580, 500, 80, 40));  // left car
            parkingCars.Add(new Rectangle(780, 500, 80, 40));  // right car
            // bay is the gap between them
            parkingBay = new Rectangle(662, 500, 116, 40);
            testMessage = "Stage 2: Bay Parking! Drive into the marked bay!";
            testMessageTimer = 3f;
            break;

        case 2: // ── INTERSECTION ──────────────────────────────────────────
            testVehicle.Position = new Vector2(200, 500);
            stageTimeLimit = 45f;
            stageTimer = stageTimeLimit;
            intersectionCleared = false;
            // traffic cars and their velocities
            trafficCars.Add(new Vector2(1200, 500)); trafficVelocities.Add(new Vector2(-180f, 0));
            trafficCars.Add(new Vector2(100, 480));  trafficVelocities.Add(new Vector2(160f, 0));
            trafficCars.Add(new Vector2(700, 100));  trafficVelocities.Add(new Vector2(0, 150f));
            trafficCars.Add(new Vector2(750, 900));  trafficVelocities.Add(new Vector2(0, -170f));
            // goal checkpoint on far side
            testCheckpoints = new Vector2[] { new Vector2(1200, 500) };
            testCurrentCheckpoint = 0;
            testMessage = "Stage 3: Intersection! Cross safely — avoid all traffic!";
            testMessageTimer = 3f;
            break;

        case 3: // ── LANE KEEPING ──────────────────────────────────────────
            testVehicle.Position = new Vector2(100, 480);
            stageTimeLimit = 45f;
            stageTimer = stageTimeLimit;
            laneCheckpointsHit = 0;
            laneCheckpointsRequired = 5;
            // road boundaries — top and bottom of lane
            laneBoundaries.Add(new Rectangle(0, 420, 2000, 20));    // top wall
            laneBoundaries.Add(new Rectangle(0, 560, 2000, 20));    // bottom wall
            // checkpoints spaced along the lane
            laneCheckpoints = new Vector2[] {
                new Vector2(300,  500),
                new Vector2(600,  480),
                new Vector2(900,  520),
                new Vector2(1200, 490),
                new Vector2(1500, 500)
            };
            testCheckpoints = laneCheckpoints;
            testCurrentCheckpoint = 0;
            testMessage = "Stage 4: Lane Keeping! Stay inside the lane markings!";
            testMessageTimer = 3f;
            break;

        case 4: // ── TEST COURSE ───────────────────────────────────────────
            testVehicle.Position = new Vector2(600, 800);
            stageTimeLimit = testingForClass switch {
                LicenceClass.D => 90f, LicenceClass.C => 80f, LicenceClass.B => 100f,
                LicenceClass.A => 75f, LicenceClass.S => 70f, _ => 90f
            };
            stageTimer = stageTimeLimit;
            testLap = 0;
            testLapsRequired = testingForClass switch {
                LicenceClass.D => 1, LicenceClass.C => 1, LicenceClass.B => 2,
                LicenceClass.A => 2, LicenceClass.S => 3, _ => 1
            };
            testCheckpoints = new Vector2[] {
                new Vector2(600,  500),
                new Vector2(1000, 300),
                new Vector2(1400, 500),
                new Vector2(1000, 900)
            };
            testCurrentCheckpoint = 0;
            testMessage = $"Stage 5: Test Course! Complete {testLapsRequired} lap(s)!";
            testMessageTimer = 3f;
            break;
    }
}

static List<Vector2> GenerateCones(LicenceClass cls)
{
    var cones = new List<Vector2>();

    // slalom cones - two staggered rows leading to the track
    float spacing = cls switch {
        LicenceClass.D => 120f, LicenceClass.C => 100f, LicenceClass.B => 90f,
        LicenceClass.A => 80f, LicenceClass.S => 70f, _ => 120f
    };
    for (int i = 0; i < 8; i++)
    {
        float x = 300 + i * spacing;
        float yOffset = (i % 2 == 0) ? -60f : 60f;
        cones.Add(new Vector2(x, 1800 + yOffset));
    }

    // cones marking track entry
    cones.Add(new Vector2(1340, 1720));
    cones.Add(new Vector2(1340, 1880));

    return cones;
}

static List<Rectangle> GenerateBarriers()
{
    var barriers = new List<Rectangle>();

    // barriers defining the track edges (outer and inner wall segments)
    // outer track boundary
    barriers.Add(new Rectangle(1400, 800, 20, 1200));   // right wall
    barriers.Add(new Rectangle(600, 800, 20, 20));       // top left corner
    barriers.Add(new Rectangle(600, 800, 1820, 20));     // top wall
    barriers.Add(new Rectangle(600, 1980, 820, 20));     // bottom wall

    // inner island (creates the loop)
    barriers.Add(new Rectangle(900, 1000, 700, 800));    // inner block

    return barriers;
}

static Vector2[] GenerateTestCourse(int count, LicenceClass cls)
{
    // cone slalom checkpoints (first half)
    int slalomCps = count / 2;
    int trackCps = count - slalomCps;
    var pts = new Vector2[count];

    // slalom section checkpoints down the cone lane
    float spacing = cls switch {
        LicenceClass.D => 120f, LicenceClass.C => 100f, LicenceClass.B => 90f,
        LicenceClass.A => 80f, LicenceClass.S => 70f, _ => 120f
    };
    for (int i = 0; i < slalomCps; i++)
        pts[i] = new Vector2(360 + i * spacing * 1.5f, 1800f);

    // timed track lap checkpoints (loop around the track)
    float[] trackAngles = { 0f, MathF.PI * 0.5f, MathF.PI, MathF.PI * 1.5f };
    for (int i = 0; i < trackCps; i++)
    {
        float angle = i * (MathF.PI * 2f / trackCps);
        pts[slalomCps + i] = new Vector2(
            1150 + MathF.Cos(angle) * 340f,
            1390 + MathF.Sin(angle) * 340f);
    }
    return pts;
}
static void ExitDrivingTest()
{
    testVehicle = null;
    player.Hidden = false;

    if (preTestScene == SceneState.Building)
    {
      aaMenuOpen = true;
    }
  else
    {
      player.Position = testReturnPos; // world position saved at F7 press
    }

    testCones.Clear();
    testBarriers.Clear();
    testConesHit = 0;
    testConePenaltyTimer = 0f;
    testComplete = false;
    testFailed = false;
    currentScene = preTestScene;
}

static void UpdateDrivingTest(float dt)
{
    if (testComplete || testFailed)
    {
        if (Raylib.IsKeyPressed(KeyboardKey.Space))
            ExitDrivingTest();
        return;
    }

    if (testMessageTimer > 0) testMessageTimer -= dt;
    if (testConePenaltyTimer > 0) testConePenaltyTimer -= dt;

    stageTimer -= dt;
    if (stageTimer <= 0f)
    {
        testFailed = true;
        testMessage = $"{testStageName} — Time's up! Test failed!";
        testMessageTimer = 4f;
        return;
    }

    // ── VEHICLE MOVEMENT ──────────────────────────────────────────────────
    Vector2 move = Vector2.Zero;
    if (Raylib.IsKeyDown(KeyboardKey.Up))    move.Y -= 1;
    if (Raylib.IsKeyDown(KeyboardKey.Down))  move.Y += 1;
    if (Raylib.IsKeyDown(KeyboardKey.Left))  move.X -= 1;
    if (Raylib.IsKeyDown(KeyboardKey.Right)) move.X += 1;
    if (move != Vector2.Zero) move = Vector2.Normalize(move);
    testVehicle.velocity = Vector2.Lerp(testVehicle.velocity, move * testVehicle.TopSpeed, dt * 5f);

    Vector2 oldPos = testVehicle.Position;
    testVehicle.Position += testVehicle.velocity * dt;

    Rectangle vehicleRect = new Rectangle(
        testVehicle.Position.X, testVehicle.Position.Y, 50, 30);

    // ── FACING ────────────────────────────────────────────────────────────
    if (testVehicle.velocity.Length() > 20f)
    {
        if (MathF.Abs(testVehicle.velocity.X) >= MathF.Abs(testVehicle.velocity.Y))
            testVehicle.Facing = testVehicle.velocity.X < 0 ? Vehicle.FacingDirection.Left : Vehicle.FacingDirection.Right;
        else
            testVehicle.Facing = testVehicle.velocity.Y < 0 ? Vehicle.FacingDirection.Up : Vehicle.FacingDirection.Down;
    }

    // ── STAGE SPECIFIC LOGIC ──────────────────────────────────────────────
    switch (testStage)
    {
        case 0: // SLALOM
            // cone collision
            if (testConePenaltyTimer <= 0)
            {
                for (int i = testCones.Count - 1; i >= 0; i--)
                {
                    if (Vector2.Distance(testVehicle.Position + new Vector2(25, 15), testCones[i]) < 24f)
                    {
                        testCones.RemoveAt(i);
                        testConesHit++;
                        testConePenaltyTimer = 1f;
                        if (testConesHit > maxConesAllowed)
                        {
                            testFailed = true;
                            testMessage = "Too many cones hit! Test failed!";
                            testMessageTimer = 4f;
                            return;
                        }
                        stageTimer -= 10f;
                        testMessage = $"Cone hit! -10s ({testConesHit}/{maxConesAllowed} allowed)";
                        testMessageTimer = 1.5f;
                        break;
                    }
                }
            }
            // end gate checkpoint
            if (testCurrentCheckpoint < testCheckpoints.Length)
            {
                if (Vector2.Distance(testVehicle.Position + new Vector2(25, 15),
                    testCheckpoints[testCurrentCheckpoint]) < 60f)
                {
                    stageComplete = true;
                    testMessage = "Slalom complete! Well done!";
                    testMessageTimer = 2f;
                    AdvanceStage();
                }
            }
            break;

        case 1: // BAY PARKING
            // collision with parked cars = instant fail
            foreach (Rectangle car in parkingCars)
            {
                if (Raylib.CheckCollisionRecs(vehicleRect, car))
                {
                    testFailed = true;
                    testMessage = "You hit a parked car! Test failed!";
                    testMessageTimer = 4f;
                    return;
                }
            }
            // check if parked in bay
            if (Raylib.CheckCollisionRecs(vehicleRect, parkingBay) &&
                testVehicle.velocity.Length() < 10f)
            {
                parkingTimer += dt;
                if (parkingTimer >= 2f) // must stay still for 2 seconds
                {
                    stageComplete = true;
                    testMessage = "Parked! Great job!";
                    testMessageTimer = 2f;
                    AdvanceStage();
                }
            }
            else
            {
                parkingTimer = 0f;
            }
            break;

        case 2: // INTERSECTION
            // update traffic cars
            for (int i = 0; i < trafficCars.Count; i++)
            {
                trafficCars[i] = trafficCars[i] + trafficVelocities[i] * dt;
                // wrap traffic around
                if (trafficCars[i].X > 1400) trafficCars[i] = new Vector2(-100, trafficCars[i].Y);
                if (trafficCars[i].X < -100) trafficCars[i] = new Vector2(1400, trafficCars[i].Y);
                if (trafficCars[i].Y > 1000) trafficCars[i] = new Vector2(trafficCars[i].X, -50);
                if (trafficCars[i].Y < -50)  trafficCars[i] = new Vector2(trafficCars[i].X, 1000);

                // collision with traffic = instant fail
                Rectangle trafficRect = new Rectangle(
                    trafficCars[i].X, trafficCars[i].Y, 50, 30);
                if (Raylib.CheckCollisionRecs(vehicleRect, trafficRect))
                {
                    testFailed = true;
                    testMessage = "You hit a traffic car! Test failed!";
                    testMessageTimer = 4f;
                    return;
                }
            }
            // reach far side checkpoint
            if (Vector2.Distance(testVehicle.Position + new Vector2(25,15),
                testCheckpoints[0]) < 80f)
            {
                stageComplete = true;
                testMessage = "Intersection cleared!";
                testMessageTimer = 2f;
                AdvanceStage();
            }
            break;

        case 3: // LANE KEEPING
            // boundary collision = instant fail
            foreach (Rectangle boundary in laneBoundaries)
            {
                if (Raylib.CheckCollisionRecs(vehicleRect, boundary))
                {
                    testFailed = true;
                    testMessage = "Left the lane! Test failed!";
                    testMessageTimer = 4f;
                    return;
                }
            }
            // lane checkpoints
            if (testCurrentCheckpoint < testCheckpoints.Length)
            {
                if (Vector2.Distance(testVehicle.Position + new Vector2(25, 15),
                    testCheckpoints[testCurrentCheckpoint]) < 50f)
                {
                    testCurrentCheckpoint++;
                    laneCheckpointsHit++;
                    testMessage = $"Checkpoint {laneCheckpointsHit}/{laneCheckpointsRequired}!";
                    testMessageTimer = 1f;
                    if (laneCheckpointsHit >= laneCheckpointsRequired)
                    {
                        stageComplete = true;
                        testMessage = "Lane keeping complete!";
                        testMessageTimer = 2f;
                        AdvanceStage();
                    }
                }
            }
            break;

        case 4: // TEST COURSE
            // checkpoint loop
            if (testCurrentCheckpoint < testCheckpoints.Length)
            {
                if (Vector2.Distance(testVehicle.Position + new Vector2(25, 15),
                    testCheckpoints[testCurrentCheckpoint]) < 60f)
                {
                    testCurrentCheckpoint++;
                    if (testCurrentCheckpoint >= testCheckpoints.Length)
                    {
                        testLap++;
                        if (testLap >= testLapsRequired)
                        {
                            testComplete = true;
                            testMessage = $"Test Passed! Class {testingForClass} licence earned!";
                            testMessageTimer = 4f;
                            GrantLicence();
                        }
                        else
                        {
                            testCurrentCheckpoint = 0;
                            testMessage = $"Lap {testLap}/{testLapsRequired} done! Keep going!";
                            testMessageTimer = 2f;
                        }
                    }
                    else
                    {
                        testMessage = $"CP {testCurrentCheckpoint}/{testCheckpoints.Length}";
                        testMessageTimer = 1f;
                    }
                }
            }
            break;
    }

    testCamera.Target = testVehicle.Position;
}

static void AdvanceStage()
{
    int next = testStage + 1;
    if (next >= testStageCount)
    {
        testComplete = true;
        testMessage = $"All stages complete! Class {testingForClass} licence earned!";
        testMessageTimer = 4f;
        GrantLicence();
    }
    else
    {
        // short delay then load next stage
        testMessage = $"Stage {testStage + 1} complete! Loading next stage...";
        testMessageTimer = 2f;
        LoadStage(next);
    }
}

static void GrantLicence()
{
    switch (testingForClass) {
        case LicenceClass.D: hasPracticalD = true; break;
        case LicenceClass.C: hasPracticalC = true; break;
        case LicenceClass.B: hasPracticalB = true; break;
        case LicenceClass.A: hasPracticalA = true; break;
        case LicenceClass.S: hasPracticalS = true; break;
    }
    player.AddDrivingXP(200);
}

static void UpdateUnderwater(float dt)
{
    float swimSpeed = 320f;
    Vector2 move = Vector2.Zero;
    if (Raylib.IsKeyDown(KeyboardKey.W) || Raylib.IsKeyDown(KeyboardKey.Up))    move.Y -= 1;
    if (Raylib.IsKeyDown(KeyboardKey.S) || Raylib.IsKeyDown(KeyboardKey.Down))  move.Y += 1;
    if (Raylib.IsKeyDown(KeyboardKey.A) || Raylib.IsKeyDown(KeyboardKey.Left))  move.X -= 1;
    if (Raylib.IsKeyDown(KeyboardKey.D) || Raylib.IsKeyDown(KeyboardKey.Right)) move.X += 1;

    if (move != Vector2.Zero)
    {
        move = Vector2.Normalize(move);
        if (MathF.Abs(move.X) >= MathF.Abs(move.Y))
            underwaterFacing = move.X < 0 ? Player.FacingDirection.Left : Player.FacingDirection.Right;
        else
            underwaterFacing = move.Y < 0 ? Player.FacingDirection.Up : Player.FacingDirection.Down;
    }

    underwaterPos += move * swimSpeed * dt;

    // clamp to world bounds
    underwaterPos.X = Math.Clamp(underwaterPos.X, 40f, UnderwaterSize - 40f);
    underwaterPos.Y = Math.Clamp(underwaterPos.Y, 40f, UnderwaterSize - 40f);

    // exit back to World with J
    if (Raylib.IsKeyPressed(KeyboardKey.J))
    {
        player.Position = underwaterWorldReturnPos;
        currentScene = SceneState.World;
        lastZoneMusic = default;
        CheckZoneMusic();
        return;
    }

    // camera follows player
    underwaterCamera.Target = underwaterPos;
    underwaterCamera.Offset = new Vector2(ScreenWidth / 2f, ScreenHeight / 2f);
    underwaterCamera.Zoom = 1f;
}
static void EnterSpace()
{
    spaceWorldReturnPos = player.Position;
    spacePos = new Vector2(SpaceSize / 2f, SpaceSize / 2f);
    spaceVel = Vector2.Zero;
    spaceAngle = 0f;
    currentScene = SceneState.Space;
}
static void UpdateSpace(float dt)
{
    float turnSpeed = 3.0f;      // radians per second
    float thrustPower = 400f;    // acceleration
    float drag = 0.4f;           // very light drag so you keep drifting
    float maxSpeed = 900f;

    // rotate ship (A/D or Left/Right)
    if (Raylib.IsKeyDown(KeyboardKey.A) || Raylib.IsKeyDown(KeyboardKey.Left))  spaceAngle -= turnSpeed * dt;
    if (Raylib.IsKeyDown(KeyboardKey.D) || Raylib.IsKeyDown(KeyboardKey.Right)) spaceAngle += turnSpeed * dt;

    // thrust forward (W/Up) in the direction the ship faces
    bool thrusting = Raylib.IsKeyDown(KeyboardKey.W) || Raylib.IsKeyDown(KeyboardKey.Up);
    if (thrusting)
    {
        Vector2 forward = new Vector2(MathF.Cos(spaceAngle), MathF.Sin(spaceAngle));
        spaceVel += forward * thrustPower * dt;
    }

    // optional reverse/brake (S/Down)
    if (Raylib.IsKeyDown(KeyboardKey.S) || Raylib.IsKeyDown(KeyboardKey.Down))
        spaceVel -= spaceVel * 1.5f * dt;

    // light drag so it slowly settles but mostly drifts
    spaceVel -= spaceVel * drag * dt;

    // clamp top speed
    if (spaceVel.Length() > maxSpeed)
        spaceVel = Vector2.Normalize(spaceVel) * maxSpeed;

    spacePos += spaceVel * dt;

    // clamp to bounds (bounce gently off edges)
    if (spacePos.X < 40f)            { spacePos.X = 40f;            spaceVel.X *= -0.4f; }
    if (spacePos.X > SpaceSize - 40f){ spacePos.X = SpaceSize - 40f;spaceVel.X *= -0.4f; }
    if (spacePos.Y < 40f)            { spacePos.Y = 40f;            spaceVel.Y *= -0.4f; }
    if (spacePos.Y > SpaceSize - 40f){ spacePos.Y = SpaceSize - 40f;spaceVel.Y *= -0.4f; }

    // exit back to World
    if (Raylib.IsKeyPressed(KeyboardKey.J))
    {
        player.Position = spaceWorldReturnPos;
        currentScene = SceneState.World;
        lastZoneMusic = default;
        CheckZoneMusic();
        return;
    }

    spaceCamera.Target = spacePos;
    spaceCamera.Offset = new Vector2(ScreenWidth / 2f, ScreenHeight / 2f);
    spaceCamera.Zoom = 1f;
}

static void StartDive()
{
    diveWorldReturnPos = player.Position;
    diveSwimPos = new Vector2(640, 120);   // start just under the surface
    currentScene = SceneState.Dive;
}

static bool IsNearDeepWater(Vector2 pos)
{
    // ocean zone — adjust to wherever your water actually is
    return pos.X > 26000 && pos.X < 45000;
}

static void UpdateDive(float dt)
{
    float swimSpeed = 280f;
    Vector2 move = Vector2.Zero;
    if (Raylib.IsKeyDown(KeyboardKey.W) || Raylib.IsKeyDown(KeyboardKey.Up))    move.Y -= 1;
    if (Raylib.IsKeyDown(KeyboardKey.S) || Raylib.IsKeyDown(KeyboardKey.Down))  move.Y += 1;
    if (Raylib.IsKeyDown(KeyboardKey.A) || Raylib.IsKeyDown(KeyboardKey.Left))  move.X -= 1;
    if (Raylib.IsKeyDown(KeyboardKey.D) || Raylib.IsKeyDown(KeyboardKey.Right)) move.X += 1;

    // face left or right only (side-on swimmer)
    if (move.X < 0) diveFacing = Player.FacingDirection.Left;
    else if (move.X > 0) diveFacing = Player.FacingDirection.Right;

    if (move != Vector2.Zero) move = Vector2.Normalize(move);
    diveSwimPos += move * swimSpeed * dt;

    // keep within horizontal bounds
    diveSwimPos.X = Math.Clamp(diveSwimPos.X, 40f, 1240f);

    // touch the surface → exit back to World
    if (diveSwimPos.Y <= diveSurfaceY)
    {
        player.Position = diveWorldReturnPos;
        currentScene = SceneState.World;
        lastZoneMusic = default;
        CheckZoneMusic();
        return;
    }

    // reach the bottom → enter the underwater world
    if (diveSwimPos.Y >= diveBottomY)
    {
        EnterUnderwater();
        return;
    }

    // camera follows vertically, locked horizontally to screen centre
    diveCamera.Target = new Vector2(640, diveSwimPos.Y);
    diveCamera.Offset = new Vector2(ScreenWidth / 2f, ScreenHeight / 2f);
    diveCamera.Zoom = 1f;
}

static void EnterUnderwater()
{
    underwaterWorldReturnPos = diveWorldReturnPos;   // return to where the dive started
    underwaterPos = new Vector2(UnderwaterSize / 2f, UnderwaterSize / 2f);
    currentScene = SceneState.Underwater;
}

static void DrawDive()
{
    Raylib.BeginMode2D(diveCamera);

    // water column — gets darker with depth
    for (int band = 0; band < 40; band++)
    {
        int by = (int)(diveSurfaceY + band * 100);
        byte shade = (byte)Math.Max(20, 130 - band * 3);
        Raylib.DrawRectangle(-200, by, 1700, 100, new Color((byte)10,(byte)(shade/2),(byte)shade,(byte)255));
    }

    // surface line
    Raylib.DrawRectangle(-200, (int)diveSurfaceY - 6, 1700, 6, new Color((byte)180,(byte)230,(byte)255,(byte)200));
    Raylib.DrawText("SURFACE — swim up to exit", 420, (int)diveSurfaceY - 30, 20, Color.White);

    // sea bed marker near the bottom
    Raylib.DrawRectangle(-200, (int)diveBottomY, 1700, 200, new Color((byte)40,(byte)35,(byte)20,(byte)255));
    Raylib.DrawText("Swim down to the depths...", 420, (int)diveBottomY - 30, 20, Color.White);

    // bubbles for ambience
    float t = (float)Raylib.GetTime();
    for (int i = 0; i < 12; i++)
    {
        float bx = 200 + i * 90;
        float by = diveBottomY - ((t * 60 + i * 200) % diveBottomY);
        Raylib.DrawCircle((int)bx, (int)by, 3, new Color((byte)200,(byte)230,(byte)255,(byte)90));
    }

    // the swimmer — simple side-on figure facing left/right
    int px = (int)diveSwimPos.X, py = (int)diveSwimPos.Y;
    bool faceLeft = diveFacing == Player.FacingDirection.Left;
    Raylib.DrawCircle(px + (faceLeft ? -8 : 8), py, 9, player.SkinColor);    // head
    Raylib.DrawRectangle(px - 6, py - 4, 12, 20, player.ShirtColor);          // body
    Raylib.DrawRectangle(px - 4, py + 16, 12, 8, player.PantsColor);          // legs/fins

    Raylib.EndMode2D();

    // HUD
    Raylib.DrawText("DIVE — W/S/A/D to swim", 10, 10, 20, Color.White);
    float depthPct = (diveSwimPos.Y - diveSurfaceY) / (diveBottomY - diveSurfaceY);
    Raylib.DrawRectangle(10, 40, 200, 14, new Color((byte)20,(byte)20,(byte)30,(byte)255));
    Raylib.DrawRectangle(10, 40, (int)(200 * Math.Clamp(depthPct, 0f, 1f)), 14, new Color((byte)60,(byte)160,(byte)220,(byte)255));
    Raylib.DrawText("Depth", 220, 38, 16, Color.LightGray);
}

static void DrawUnderwater()
{
    Raylib.ClearBackground(new Color((byte)10,(byte)40,(byte)80,(byte)255));

    Raylib.BeginMode2D(underwaterCamera);

    // faint grid so movement is visible in the bare world
    int grid = 1000;
    Color gridCol = new Color((byte)20,(byte)60,(byte)110,(byte)255);
    for (int gx = 0; gx <= UnderwaterSize; gx += grid)
        Raylib.DrawLine(gx, 0, gx, UnderwaterSize, gridCol);
    for (int gy = 0; gy <= UnderwaterSize; gy += grid)
        Raylib.DrawLine(0, gy, UnderwaterSize, gy, gridCol);

    // boundary walls
    int t = 40;
    Color wall = new Color((byte)30,(byte)25,(byte)15,(byte)255);
    Raylib.DrawRectangle(0, 0, UnderwaterSize, t, wall);                       // top
    Raylib.DrawRectangle(0, UnderwaterSize - t, UnderwaterSize, t, wall);      // bottom
    Raylib.DrawRectangle(0, 0, t, UnderwaterSize, wall);                       // left
    Raylib.DrawRectangle(UnderwaterSize - t, 0, t, UnderwaterSize, wall);      // right

    // drifting bubbles for ambience
    float time = (float)Raylib.GetTime();
    for (int i = 0; i < 30; i++)
    {
        float bx = (i * 670) % UnderwaterSize;
        float by = UnderwaterSize - ((time * 50 + i * 400) % UnderwaterSize);
        Raylib.DrawCircle((int)bx, (int)by, 4, new Color((byte)120,(byte)180,(byte)220,(byte)60));
    }

    // the player — simple swimmer facing 4 ways
    int px = (int)underwaterPos.X, py = (int)underwaterPos.Y;
    Raylib.DrawCircle(px, py - 6, 10, player.SkinColor);              // head
    Raylib.DrawRectangle(px - 8, py + 2, 16, 22, player.ShirtColor);  // body
    Raylib.DrawRectangle(px - 6, py + 24, 12, 8, player.PantsColor);  // legs
    // facing indicator
    Vector2 look = underwaterFacing switch
    {
        Player.FacingDirection.Up    => new Vector2(0, -14),
        Player.FacingDirection.Down  => new Vector2(0, 14),
        Player.FacingDirection.Left  => new Vector2(-14, 0),
        _                            => new Vector2(14, 0)
    };
    Raylib.DrawCircle(px + (int)look.X, py + (int)look.Y, 3, Color.White);

    Raylib.EndMode2D();

    // HUD
    Raylib.DrawText("UNDERWATER — WASD to swim  |  J = surface to world", 10, 10, 20, Color.White);
    Raylib.DrawText($"Pos: {(int)underwaterPos.X}, {(int)underwaterPos.Y}", 10, 36, 16, Color.LightGray);
}

static void DrawSpace()
{
    Raylib.ClearBackground(new Color((byte)5,(byte)5,(byte)20,(byte)255));

    Raylib.BeginMode2D(spaceCamera);

    // starfield — deterministic scatter so stars stay put
    var rng = new Random(1234);
    for (int i = 0; i < 600; i++)
    {
        int sx = rng.Next(0, SpaceSize);
        int sy = rng.Next(0, SpaceSize);
        int size = rng.Next(1, 3);
        byte b = (byte)rng.Next(120, 255);
        Raylib.DrawRectangle(sx, sy, size, size, new Color(b, b, (byte)255, (byte)255));
    }

    // boundary walls (nebula edge)
    int t = 40;
    Color edge = new Color((byte)60,(byte)20,(byte)80,(byte)255);
    Raylib.DrawRectangle(0, 0, SpaceSize, t, edge);
    Raylib.DrawRectangle(0, SpaceSize - t, SpaceSize, t, edge);
    Raylib.DrawRectangle(0, 0, t, SpaceSize, edge);
    Raylib.DrawRectangle(SpaceSize - t, 0, t, SpaceSize, edge);

    // the ship — triangle pointing along spaceAngle
    float px = spacePos.X, py = spacePos.Y;
    Vector2 forward = new Vector2(MathF.Cos(spaceAngle), MathF.Sin(spaceAngle));
    Vector2 right   = new Vector2(-forward.Y, forward.X);
    Vector2 nose  = new Vector2(px, py) + forward * 18f;
    Vector2 tailL = new Vector2(px, py) - forward * 12f + right * 10f;
    Vector2 tailR = new Vector2(px, py) - forward * 12f - right * 10f;

    // thrust flame when accelerating
    if (Raylib.IsKeyDown(KeyboardKey.W) || Raylib.IsKeyDown(KeyboardKey.Up))
    {
        Vector2 flame = new Vector2(px, py) - forward * (20f + (float)(Raylib.GetTime() * 60 % 12));
        Raylib.DrawTriangle(tailR, tailL, flame, new Color((byte)255,(byte)160,(byte)40,(byte)255));
    }

    Raylib.DrawTriangle(nose, tailL, tailR, new Color((byte)200,(byte)210,(byte)230,(byte)255));
    Raylib.DrawTriangleLines(nose, tailL, tailR, Color.White);

    Raylib.EndMode2D();

    // HUD
    Raylib.DrawText("SPACE — W thrust, A/D rotate, S brake  |  J = return", 10, 10, 20, Color.White);
    Raylib.DrawText($"Speed: {(int)spaceVel.Length()}", 10, 36, 16, Color.LightGray);
    Raylib.DrawText($"Pos: {(int)spacePos.X}, {(int)spacePos.Y}", 10, 56, 16, Color.LightGray);
}

static void DrawDrivingTest()
{
    Raylib.BeginMode2D(testCamera);

    // ── STAGE BACKGROUNDS ─────────────────────────────────────────────────
    switch (testStage)
    {
        case 0: // SLALOM — straight road
            Raylib.ClearBackground(new Color((byte)80,(byte)120,(byte)50,(byte)255));
            Raylib.DrawRectangle(-200, 430, 2000, 140, new Color((byte)55,(byte)55,(byte)60,(byte)255));
            // lane markings
            for (int i = 0; i < 16; i++)
                Raylib.DrawRectangle(-100 + i * 120, 495, 60, 8,
                    new Color((byte)255,(byte)255,(byte)255,(byte)140));
            // road edges
            Raylib.DrawRectangle(-200, 428, 2000, 4, Color.White);
            Raylib.DrawRectangle(-200, 568, 2000, 4, Color.White);
            // end gate
            Raylib.DrawRectangle(1440, 420, 20, 40, new Color((byte)220,(byte)50,(byte)50,(byte)255));
            Raylib.DrawRectangle(1440, 540, 20, 40, new Color((byte)220,(byte)50,(byte)50,(byte)255));
            Raylib.DrawText("FINISH", 1420, 400, 18, Color.White);
            break;

        case 1: // PARKING — car park
            Raylib.ClearBackground(new Color((byte)70,(byte)70,(byte)75,(byte)255));
            Raylib.DrawRectangle(200, 200, 900, 400, new Color((byte)55,(byte)55,(byte)60,(byte)255));
            // bay lines
            for (int i = 0; i < 6; i++)
                Raylib.DrawRectangle(560 + i * 80, 490, 3, 100, Color.White);
            Raylib.DrawRectangle(560, 588, 400, 3, Color.White);
            // highlight target bay
            Raylib.DrawRectangle((int)parkingBay.X, (int)parkingBay.Y,
                (int)parkingBay.Width, (int)parkingBay.Height,
                new Color((byte)255,(byte)215,(byte)0,(byte)40));
            Raylib.DrawRectangleLines((int)parkingBay.X, (int)parkingBay.Y,
                (int)parkingBay.Width, (int)parkingBay.Height,
                new Color((byte)255,(byte)215,(byte)0,(byte)200));
            Raylib.DrawText("PARK HERE", (int)parkingBay.X + 8, (int)parkingBay.Y + 12, 14, Color.Gold);
            // parked cars
            foreach (Rectangle car in parkingCars)
            {
                Raylib.DrawRectangle((int)car.X, (int)car.Y, (int)car.Width, (int)car.Height,
                    new Color((byte)80,(byte)100,(byte)160,(byte)255));
                Raylib.DrawRectangleLines((int)car.X, (int)car.Y, (int)car.Width, (int)car.Height,
                    new Color((byte)120,(byte)140,(byte)200,(byte)255));
            }
            break;

        case 2: // INTERSECTION
            Raylib.ClearBackground(new Color((byte)80,(byte)120,(byte)50,(byte)255));
            // horizontal road
            Raylib.DrawRectangle(-200, 460, 1800, 100, new Color((byte)55,(byte)55,(byte)60,(byte)255));
            // vertical road
            Raylib.DrawRectangle(620, -200, 100, 1400, new Color((byte)55,(byte)55,(byte)60,(byte)255));
            // centre lines
            for (int i = 0; i < 10; i++)
                Raylib.DrawRectangle(-100 + i * 120, 507, 60, 6,
                    new Color((byte)255,(byte)255,(byte)0,(byte)140));
            for (int i = 0; i < 10; i++)
                Raylib.DrawRectangle(667, -100 + i * 120, 6, 60,
                    new Color((byte)255,(byte)255,(byte)0,(byte)140));
            // road edges
            Raylib.DrawRectangle(-200, 458, 1800, 4, Color.White);
            Raylib.DrawRectangle(-200, 558, 1800, 4, Color.White);
            Raylib.DrawRectangle(618, -200, 4, 1400, Color.White);
            Raylib.DrawRectangle(718, -200, 4, 1400, Color.White);
            // goal marker
            Raylib.DrawCircle(1200, 500, 30, new Color((byte)0,(byte)200,(byte)100,(byte)100));
            Raylib.DrawCircleLines(1200, 500, 30, Color.Green);
            Raylib.DrawText("GOAL", 1175, 490, 16, Color.Green);
            // traffic cars
            for (int i = 0; i < trafficCars.Count; i++)
            {
                Color tc = i % 2 == 0 ?
                    new Color((byte)200,(byte)50,(byte)50,(byte)255) :
                    new Color((byte)50,(byte)160,(byte)80,(byte)255);
                Raylib.DrawRectangle((int)trafficCars[i].X, (int)trafficCars[i].Y, 50, 30, tc);
                Raylib.DrawRectangleLines((int)trafficCars[i].X, (int)trafficCars[i].Y,
                    50, 30, Color.White);
            }
            break;

        case 3: // LANE KEEPING
            Raylib.ClearBackground(new Color((byte)80,(byte)120,(byte)50,(byte)255));
            // road
            Raylib.DrawRectangle(-200, 420, 2000, 160, new Color((byte)55,(byte)55,(byte)60,(byte)255));
            // lane boundary lines — these are the fail zones
            Raylib.DrawRectangle(-200, 420, 2000, 20,
                new Color((byte)220,(byte)50,(byte)50,(byte)255)); // top boundary
            Raylib.DrawRectangle(-200, 560, 2000, 20,
                new Color((byte)220,(byte)50,(byte)50,(byte)255)); // bottom boundary
            // centre dashes
            for (int i = 0; i < 16; i++)
                Raylib.DrawRectangle(-100 + i * 120, 495, 60, 8,
                    new Color((byte)255,(byte)255,(byte)0,(byte)140));
            // checkpoints
            for (int i = 0; i < laneCheckpoints.Length; i++)
            {
                bool done = i < testCurrentCheckpoint;
                bool next = i == testCurrentCheckpoint;
                Color cpCol = done ? Color.Green : next ? Color.Gold :
                    new Color((byte)60,(byte)80,(byte)160,(byte)255);
                Raylib.DrawCircle((int)laneCheckpoints[i].X, (int)laneCheckpoints[i].Y,
                    next ? 22 : 16, cpCol);
                Raylib.DrawCircleLines((int)laneCheckpoints[i].X, (int)laneCheckpoints[i].Y,
                    next ? 22 : 16, Color.White);
                Raylib.DrawText($"{i + 1}",
                    (int)laneCheckpoints[i].X - 5, (int)laneCheckpoints[i].Y - 9, 18, Color.White);
            }
            break;

        case 4: // TEST COURSE
            Raylib.ClearBackground(new Color((byte)80,(byte)120,(byte)50,(byte)255));
            // outer track
            Raylib.DrawRectangle(300, 200, 1000, 800, new Color((byte)55,(byte)55,(byte)60,(byte)255));
            // inner grass
            Raylib.DrawRectangle(500, 380, 600, 440, new Color((byte)60,(byte)100,(byte)40,(byte)255));
            Raylib.DrawRectangleLines(500, 380, 600, 440,
                new Color((byte)200,(byte)200,(byte)60,(byte)255));
            // track markings
            for (int i = 0; i < 16; i++)
            {
                float a = i * (MathF.PI * 2f / 16f);
                int mx = (int)(800 + MathF.Cos(a) * 380f);
                int my = (int)(600 + MathF.Sin(a) * 300f);
                Raylib.DrawRectangle(mx - 4, my - 10, 8, 20,
                    new Color((byte)255,(byte)255,(byte)255,(byte)140));
            }
            // start finish line
            for (int i = 0; i < 6; i++)
            {
                Color chk = i % 2 == 0 ? Color.White : Color.Black;
                Raylib.DrawRectangle(300 + i * 14, 740, 14, 80, chk);
            }
            Raylib.DrawText("START/FINISH", 290, 720, 16, Color.White);
            // checkpoints
            for (int i = 0; i < testCheckpoints.Length; i++)
            {
                bool done = i < testCurrentCheckpoint;
                bool next = i == testCurrentCheckpoint;
                Color cpCol = done ? Color.Green : next ? Color.Gold :
                    new Color((byte)60,(byte)80,(byte)160,(byte)255);
                Raylib.DrawCircle((int)testCheckpoints[i].X, (int)testCheckpoints[i].Y,
                    next ? 24 : 18, cpCol);
                Raylib.DrawCircleLines((int)testCheckpoints[i].X, (int)testCheckpoints[i].Y,
                    next ? 24 : 18, Color.White);
                Raylib.DrawText($"{i + 1}",
                    (int)testCheckpoints[i].X - 5, (int)testCheckpoints[i].Y - 9, 18, Color.White);
                if (next && i + 1 < testCheckpoints.Length)
                    Raylib.DrawLineEx(testCheckpoints[i], testCheckpoints[i + 1], 2f,
                        new Color((byte)255,(byte)200,(byte)0,(byte)80));
            }
            break;
    }

    // ── CONES (stage 0) ───────────────────────────────────────────────────
    foreach (Vector2 cone in testCones)
    {
        Raylib.DrawRectangle((int)cone.X - 8, (int)cone.Y - 18, 16, 20,
            new Color((byte)240,(byte)100,(byte)20,(byte)255));
        Raylib.DrawRectangle((int)cone.X - 8, (int)cone.Y - 8, 16, 5,
            new Color((byte)255,(byte)255,(byte)255,(byte)220));
        Raylib.DrawRectangle((int)cone.X - 12, (int)cone.Y + 2, 24, 6,
            new Color((byte)200,(byte)80,(byte)10,(byte)255));
    }

    if (testVehicle != null) testVehicle.Draw();

    Raylib.EndMode2D();

    // ── HUD ───────────────────────────────────────────────────────────────
    Raylib.DrawRectangle(0, 0, ScreenWidth, 54,
        new Color((byte)5,(byte)15,(byte)30,(byte)220));

    // stage progress dots
    for (int i = 0; i < testStageCount; i++)
    {
        Color dot = i < testStage ? Color.Green : i == testStage ? Color.Gold : Color.DarkGray;
        Raylib.DrawCircle(ScreenWidth / 2 - 80 + i * 40, 42, 8, dot);
        Raylib.DrawCircleLines(ScreenWidth / 2 - 80 + i * 40, 42, 8, Color.White);
        Raylib.DrawText($"{i + 1}",
            ScreenWidth / 2 - 83 + i * 40, 36, 12, i == testStage ? Color.Black : Color.White);
    }

    // timer bar
    float timerPct = stageTimer / stageTimeLimit;
    Color timerCol = timerPct > 0.5f ? Color.Green : timerPct > 0.25f ? Color.Orange : Color.Red;
    Raylib.DrawRectangle(200, 8, 700, 18, new Color((byte)30,(byte)30,(byte)40,(byte)255));
    Raylib.DrawRectangle(200, 8, (int)(700 * timerPct), 18, timerCol);
    Raylib.DrawRectangleLines(200, 8, 700, 18, Color.White);
    Raylib.DrawText($"{(int)stageTimer}s", 910, 6, 20, timerCol);

    Raylib.DrawText(testStageName, 10, 8, 20,
        new Color((byte)0,(byte)200,(byte)255,(byte)255));
    Raylib.DrawText("Arrow keys = Drive", 10, 32, 14, Color.DarkGray);

    // cone penalty flash
    if (testConePenaltyTimer > 0)
        Raylib.DrawRectangle(0, 0, ScreenWidth, ScreenHeight,
            new Color((byte)255,(byte)80,(byte)0,(byte)40));

    // message
    if (testMessageTimer > 0)
    {
        byte alpha = (byte)(255 * Math.Min(1f, testMessageTimer));
        int mw = Raylib.MeasureText(testMessage, 28);
        Raylib.DrawRectangle(ScreenWidth / 2 - mw / 2 - 16, 280, mw + 32, 48,
            new Color((byte)0,(byte)0,(byte)0,(byte)180));
        Raylib.DrawText(testMessage, ScreenWidth / 2 - mw / 2, 288, 28,
            new Color((byte)255,(byte)215,(byte)0, alpha));
    }

    // pass/fail
    if (testComplete || testFailed)
    {
        Raylib.DrawRectangle(ScreenWidth / 2 - 280, 380, 560, 90,
            new Color((byte)0,(byte)0,(byte)0,(byte)220));
        Raylib.DrawRectangleLines(ScreenWidth / 2 - 280, 380, 560, 90,
            testComplete ? Color.Green : Color.Red);
        Raylib.DrawText(
            testComplete ? "ALL STAGES PASSED!  SPACE = Continue" :
                          "FAILED.  SPACE = Try Again",
            ScreenWidth / 2 - 260, 410, 22,
            testComplete ? Color.Green : Color.Red);
    }
}
static void DrawInventoryUI()
{

    if (player.InventoryOpen)
    {
        int invX = ScreenWidth - 380;
        int invY = 100;
        int slotSize = 80;
        int padding = 10;
        int cols = 4;

        List<(string name, int count)> items = new();
        if (player.Logs > 0) items.Add(("Logs", player.Logs));
        if (player.BirchLogs > 0) items.Add(("Birch Logs", player.BirchLogs));
        if (player.OakLogs > 0) items.Add(("Oak Logs", player.OakLogs));
        if (player.PineLogs > 0) items.Add(("Pine Logs", player.PineLogs));
        if (player.ArcticLogs > 0) items.Add(("Arctic Logs", player.ArcticLogs));
        if (player.DeadWood > 0) items.Add(("Dead Wood", player.DeadWood));
        if (player.Fish > 0) items.Add(("Fish", player.Fish));
        if (player.Bones > 0) items.Add(("Bones", player.Bones));
        if (player.Fur > 0) items.Add(("Fur", player.Fur));
        if (player.Stingers > 0) items.Add(("Stingers", player.Stingers));
        if (player.BearPelts > 0) items.Add(("Pelts", player.BearPelts));
        if (player.DogFangs > 0) items.Add(("Dog Fangs", player.DogFangs));
        if (player.Money > 0) items.Add(("Money", player.Money));
        if (player.HasAxe && !ToolInToolbar("Axe")) items.Add(("Axe", 1));
        if (pickaxePickedUp && !ToolInToolbar("Pickaxe")) items.Add(("Pickaxe", 1));
        if (fishingRodPickedUp && !ToolInToolbar("Rod")) items.Add(("Rod", 1));
        if (fishingNetPickedUp && !ToolInToolbar("Net")) items.Add(("Net", 1));
        if (torchPickedUp && !ToolInToolbar("Torch")) items.Add(("Torch", 1));
        if (stickPickedUp && !ToolInToolbar("Stick") && !WeaponEquipped("Stick")) items.Add(("Stick", 1));
        if (swordPickedUp && !ToolInToolbar("Sword") && !WeaponEquipped("Sword")) items.Add(("Sword", 1));
        if (player.HasBow && !ToolInToolbar("Bow") && !WeaponEquipped("Bow")) items.Add(("Bow", 1));
        if (player.HasCrossbow && !ToolInToolbar("Crossbow") && !WeaponEquipped("Crossbow")) items.Add(("Crossbow", 1));
        if (player.Arrows > 0 && equippedAmmo != "Arrows") items.Add(("Arrows", player.Arrows));
        if (player.Bolts > 0 && equippedAmmo != "Bolts") items.Add(("Bolts", player.Bolts));
        if (player.ArcaneEssence > 0 && equippedAmmo != "Arcane Essence") items.Add(("Arcane Essence", player.ArcaneEssence));
        // owned staffs not currently equipped as weapon
        foreach (var g in player.OwnedGear)
            if (g.EndsWith("Staff") && g != equipped1H && g != equipped2H) items.Add((g, 1));
        foreach (var kv in backpack)
            if (kv.Value > 0) items.Add((kv.Key, kv.Value));
      

        Raylib.DrawRectangle(invX - 20, invY - 20, cols * (slotSize + padding) + 30, 5 * (slotSize + padding) + 60, new Color((byte)0,(byte)0,(byte)0,(byte)220));
        Raylib.DrawText("INVENTORY", invX, invY - 10, 24, Color.Gold);

        Vector2 mouse = Raylib.GetMousePosition();

        for (int i = 0; i < 20; i++)
        {
            int col = i % cols;
            int row = i / cols;
            int x = invX + col * (slotSize + padding);
            int y = invY + 20 + row * (slotSize + padding);

            Raylib.DrawRectangle(x, y, slotSize, slotSize, new Color((byte)40,(byte)40,(byte)40,(byte)255));
            Raylib.DrawRectangleLines(x, y, slotSize, slotSize, new Color((byte)100,(byte)100,(byte)100,(byte)255));

            if (i >= items.Count) continue;

            DrawInventoryIcon(items[i].name, x, y, slotSize);
            Raylib.DrawText($"{items[i].count}", x + 6, y + 6, 16, Color.White);
            Raylib.DrawText(items[i].name, x + 4, y + slotSize - 20, 13, Color.LightGray);

            // hover + click to select
            Rectangle slotRect = new Rectangle(x, y, slotSize, slotSize);
            if (Raylib.CheckCollisionPointRec(mouse, slotRect))
            {
                Raylib.DrawRectangleLines(x, y, slotSize, slotSize, Color.Gold);
                if (Raylib.IsMouseButtonPressed(MouseButton.Left))
                {
                    invSelectedIndex = i;
                    invSelectedName = items[i].name;
                    invSelectedCount = items[i].count;
                }
            }

            // selected highlight
            if (invSelectedIndex == i)
                Raylib.DrawRectangleLinesEx(slotRect, 3, Color.Gold);
        }

        // ── CONTEXT MENU ──
        if (invSelectedIndex >= 0 && invSelectedName != "" && invSelectedIndex < items.Count)
        {
            // keep selected name synced to whatever's in that slot now
            invSelectedName = items[invSelectedIndex].name;

            List<string> actions = new();
            if (IsUsable(invSelectedName))     actions.Add("Use");
            if (IsEquippable(invSelectedName)) actions.Add("Equip");
            actions.Add("Move to Toolbar");
            actions.Add("Drop");

            int menuX = invX - 200;
            int menuY = invY + 40;
            int menuW = 170;
            int rowH = 38;
            int menuH = actions.Count * rowH + 46;

            Raylib.DrawRectangle(menuX, menuY, menuW, menuH, new Color((byte)20,(byte)20,(byte)28,(byte)250));
            Raylib.DrawRectangleLines(menuX, menuY, menuW, menuH, Color.Gold);
            Raylib.DrawText(invSelectedName.Length > 13 ? invSelectedName.Substring(0,13) : invSelectedName,
                menuX + 10, menuY + 8, 16, Color.Gold);

            for (int a = 0; a < actions.Count; a++)
            {
                int ry = menuY + 36 + a * rowH;
                Rectangle rowRect = new Rectangle(menuX + 8, ry, menuW - 16, rowH - 6);
                bool hover = Raylib.CheckCollisionPointRec(mouse, rowRect);
                Raylib.DrawRectangleRec(rowRect, hover ? new Color((byte)60,(byte)50,(byte)20,(byte)255) : new Color((byte)40,(byte)40,(byte)50,(byte)255));
                Raylib.DrawRectangleLinesEx(rowRect, 1, hover ? Color.Gold : new Color((byte)90,(byte)90,(byte)110,(byte)255));
                Raylib.DrawText(actions[a], menuX + 16, ry + 8, 16, hover ? Color.Gold : Color.White);

                if (hover && Raylib.IsMouseButtonPressed(MouseButton.Left))
                {
                    DoInventoryAction(actions[a], invSelectedName);
                    invSelectedIndex = -1;
                    invSelectedName = "";
                }
            }
        }

        // close menu with right-click anywhere
        if (Raylib.IsMouseButtonPressed(MouseButton.Right))
        {
            invSelectedIndex = -1;
            invSelectedName = "";
        }

        Raylib.DrawText("Click item to select  |  Right-click to cancel", invX - 10, invY + 5 * (slotSize + padding) + 25, 14, Color.LightGray);
    }
    else
    {
        // clear selection when inventory closes
        invSelectedIndex = -1;
        invSelectedName = "";
    }
}

static void DrawSleepScreen()
{
    // black fade overlay
    Raylib.DrawRectangle(0, 0, ScreenWidth, ScreenHeight,
        new Color((byte)0,(byte)0,(byte)0,(byte)(int)sleepFadeAlpha));

    if (sleepFadeAlpha < 200f) return;

    // zzz cloud bubble
    int cx = ScreenWidth / 2;
    int cy = ScreenHeight / 2;

    // cloud body
    Raylib.DrawEllipse(cx, cy, 90, 50, new Color((byte)40,(byte)40,(byte)60,(byte)220));
    Raylib.DrawEllipse(cx - 50, cy + 10, 50, 36, new Color((byte)40,(byte)40,(byte)60,(byte)220));
    Raylib.DrawEllipse(cx + 50, cy + 10, 50, 36, new Color((byte)40,(byte)40,(byte)60,(byte)220));
    Raylib.DrawEllipse(cx - 20, cy - 30, 44, 30, new Color((byte)40,(byte)40,(byte)60,(byte)220));
    Raylib.DrawEllipse(cx + 28, cy - 28, 44, 30, new Color((byte)40,(byte)40,(byte)60,(byte)220));

    // cloud outline
    Raylib.DrawEllipseLines(cx, cy, 90, 50, new Color((byte)160,(byte)160,(byte)220,(byte)180));

    // bouncing zzz letters — each offset by time so they drift up
    float t = zzzTimer;
    byte[] alphas = {
        (byte)(180 + 75 * MathF.Sin(t * 2f)),
        (byte)(180 + 75 * MathF.Sin(t * 2f - 1f)),
        (byte)(180 + 75 * MathF.Sin(t * 2f - 2f)),
    };
    float[] yOffsets = {
        MathF.Sin(t * 1.8f) * 8f,
        MathF.Sin(t * 1.8f - 0.8f) * 8f,
        MathF.Sin(t * 1.8f - 1.6f) * 8f,
    };

    Raylib.DrawText("Z", cx - 36, (int)(cy - 12 + yOffsets[0]), 28, new Color((byte)200,(byte)200,(byte)255, alphas[0]));
    Raylib.DrawText("Z", cx - 8,  (int)(cy - 22 + yOffsets[1]), 24, new Color((byte)200,(byte)200,(byte)255, alphas[1]));
    Raylib.DrawText("Z", cx + 16, (int)(cy - 30 + yOffsets[2]), 20, new Color((byte)200,(byte)200,(byte)255, alphas[2]));
}
static void UpdateDungeon(float dt)
{
    var d = activeDungeon;
    if (!d.IsOpen) return;
    if (d.MessageTimer > 0) d.MessageTimer -= dt;

    // Pause menu
    if (Raylib.IsKeyPressed(KeyboardKey.Escape))
    {
        if (pauseMenuOpen)
        {
            pauseMenuOpen = false;
            Raylib.PlaySound(soundPauseClose);
        }
        else
        {
            pauseMenuOpen = true;
            Raylib.PlaySound(soundPauseOpen);
            Raylib.PauseMusicStream(currentMusic);
        }
    }

    if (Raylib.IsKeyPressed(KeyboardKey.T))
    {
        currentPhase = currentPhase == HandPhase.Tools ? HandPhase.Combat : HandPhase.Tools;
    }
    
    if (Raylib.IsKeyPressed(KeyboardKey.Q))
        dungeonQuitConfirm = !dungeonQuitConfirm;

    
    if (dungeonQuitConfirm)
    {
        if (Raylib.IsKeyPressed(KeyboardKey.Y))
        {
            dungeonQuitConfirm = false;
            activeDungeon.Close();
            player.Position = activeDungeon.WorldReturnPos;
            currentScene = SceneState.World;
            return;
        }
        if (Raylib.IsKeyPressed(KeyboardKey.N) || Raylib.IsKeyPressed(KeyboardKey.Escape))
            dungeonQuitConfirm = false;
        return;
    }

    // Armor/gear menu
    if (Raylib.IsKeyPressed(KeyboardKey.G))
         if (!pauseMenuOpen && !player.InventoryOpen && !skillsOpen && !questsOpen)
            armorMenuOpen = !armorMenuOpen;


    // Toolbar slot selection
    for (int k = 0; k < 8; k++)
        if (Raylib.IsKeyPressed(KeyboardKey.One + k))
            toolbarSelectedSlot = k;

    if (Raylib.IsKeyPressed(KeyboardKey.Space) && !chatInputOpen)
{
    string held = toolbarSlots[toolbarSelectedSlot];
    if (held != null && IsUsable(held))
        UseToolbarItem(toolbarSelectedSlot);
   
}

    float scroll = Raylib.GetMouseWheelMove();
    if (scroll != 0 && !pauseMenuOpen && !armorMenuOpen)
    {
        toolbarSelectedSlot = (int)Math.Clamp(toolbarSelectedSlot - scroll, 0, 7);
    }

    if (pauseMenuOpen || armorMenuOpen || player.InventoryOpen || dungeonQuitConfirm) return;

    if (d.Complete)
    {
        if (Raylib.IsKeyPressed(KeyboardKey.E) && !chatInputOpen)
        {
            d.Close();
            player.Position = d.WorldReturnPos;
            currentScene = SceneState.World;
        }
        return;
    }

    var room = d.Rooms[d.CurrentRoom];

    Vector2 move = Vector2.Zero;
if (Raylib.IsKeyDown(KeyboardKey.W) || Raylib.IsKeyDown(KeyboardKey.Up))    move.Y -= 1;
if (Raylib.IsKeyDown(KeyboardKey.S) || Raylib.IsKeyDown(KeyboardKey.Down))  move.Y += 1;
if (Raylib.IsKeyDown(KeyboardKey.A) || Raylib.IsKeyDown(KeyboardKey.Left))  move.X -= 1;
if (Raylib.IsKeyDown(KeyboardKey.D) || Raylib.IsKeyDown(KeyboardKey.Right)) move.X += 1;

if (move != Vector2.Zero)
{
    move = Vector2.Normalize(move);

    if (MathF.Abs(move.X) >= MathF.Abs(move.Y))
        player.Facing = move.X < 0 ? Player.FacingDirection.Left : Player.FacingDirection.Right;
    else
        player.Facing = move.Y < 0 ? Player.FacingDirection.Up : Player.FacingDirection.Down;
}

float dungeonSpeed = player.BaseSpeed * 0.8f;
Vector2 newPos = d.PlayerPos + move * dungeonSpeed * dt;

// clamp to room walls
newPos.X = Math.Clamp(newPos.X, Dungeon.InnerX + 22, Dungeon.InnerX + Dungeon.InnerW - 22);
newPos.Y = Math.Clamp(newPos.Y, Dungeon.InnerY + 22, Dungeon.InnerY + Dungeon.InnerH - 22);

// try full movement — if blocked, try sliding on each axis separately
if (!d.CollidesWithEnemy(newPos, 20f))
{
    d.PlayerPos = newPos;
}
else
{
    // try sliding on X axis only
    Vector2 slideX = new Vector2(newPos.X, d.PlayerPos.Y);
    slideX.X = Math.Clamp(slideX.X, Dungeon.InnerX + 22, Dungeon.InnerX + Dungeon.InnerW - 22);
    if (!d.CollidesWithEnemy(slideX, 20f))
        d.PlayerPos = slideX;
    else
    {
        // try sliding on Y axis only
        Vector2 slideY = new Vector2(d.PlayerPos.X, newPos.Y);
        slideY.Y = Math.Clamp(slideY.Y, Dungeon.InnerY + 22, Dungeon.InnerY + Dungeon.InnerH - 22);
        if (!d.CollidesWithEnemy(slideY, 20f))
            d.PlayerPos = slideY;
        // if both blocked, stay in place
    }
}

player.Position = d.PlayerPos;

    // Update enemies + combat
   foreach (var enemy in room.Enemies)
{
    if (enemy.Dead) continue;
    
    // always update movement regardless of attack state
    enemy.Update(dt, d.PlayerPos);

    // push enemies apart
    foreach (var other in room.Enemies)
    {
        if (other == enemy || other.Dead) continue;
        float sepDist = Vector2.Distance(enemy.Position, other.Position);
        float minDist = 46f;
        if (sepDist < minDist && sepDist > 0.001f)
        {
            Vector2 push = Vector2.Normalize(enemy.Position - other.Position);
            float overlap = (minDist - sepDist) / 2f;
            enemy.Position += push * overlap;
            other.Position -= push * overlap;

            enemy.Position.X = Math.Clamp(enemy.Position.X, Dungeon.InnerX + 24, Dungeon.InnerX + Dungeon.InnerW - 24);
            enemy.Position.Y = Math.Clamp(enemy.Position.Y, Dungeon.InnerY + 24, Dungeon.InnerY + Dungeon.InnerH - 24);
            other.Position.X = Math.Clamp(other.Position.X, Dungeon.InnerX + 24, Dungeon.InnerX + Dungeon.InnerW - 24);
            other.Position.Y = Math.Clamp(other.Position.Y, Dungeon.InnerY + 24, Dungeon.InnerY + Dungeon.InnerH - 24);
        }
    }

    float dist = Vector2.Distance(d.PlayerPos, enemy.Position);

    if (dist < 42f && enemy.AttackCooldown <= 0)
    {
        int def = GetTotalDefense();
        int dmg = Math.Max(1, enemy.Damage - def);
        player.Health -= dmg;
        enemy.AttackCooldown = 1.2f;
        floatingTexts.Add(new FloatingText {
            Position = new Vector2(d.PlayerPos.X, d.PlayerPos.Y - 30),
            Text = $"-{dmg}", Timer = 1f, TextColor = Color.Red
        });
    }

    // player attacks enemy
    if (dist < 65f && (Raylib.IsKeyPressed(KeyboardKey.Space) || Raylib.IsMouseButtonPressed(MouseButton.Left)))
{
    string equipped = GetActiveWeapon();
    bool hasWeapon  = equipped == "Stick" || equipped == "Sword" || equipped == "Ruby Sword" || equipped == " Sapphire SwordSword";
    if (!hasWeapon)
    {
        d.Message = "Equip a weapon to fight!";
        d.MessageTimer = 1.5f;
    }
    else
    {
        int weaponBonus = equipped == "Sword" ? 5 : 0;
        int slotBonus   = GetWeaponDamage(armorWeapon);
        int atk         = 1 + (player.CombatLevel / 10) + weaponBonus + slotBonus;
        enemy.Health   -= atk;
        AwardMeleeXP(equipped, Math.Max(1, atk));

        // knock enemy away from player
        if (Vector2.Distance(d.PlayerPos, enemy.Position) > 0.01f)
        {
            Vector2 knockDir = Vector2.Normalize(enemy.Position - d.PlayerPos);
            enemy.Knockback = knockDir * 600f;
        }

        floatingTexts.Add(new FloatingText {
            Position = new Vector2(enemy.Position.X, enemy.Position.Y - 30),
            Text = $"-{atk}", Timer = 1f,
            TextColor = equipped == "Sword" ? Color.Orange : Color.Red
        });

        if (enemy.Health <= 0)
        {
            enemy.Dead = true;
            SpawnDeathFx(enemy.Position, enemy.EnemyColor, enemy.Type);
            player.AddCombatXP(enemy.XPReward);
            player.Money += enemy.MoneyDrop;

            room.Loot.Add(new DungeonLoot(
                new Vector2(enemy.Position.X + Raylib.GetRandomValue(-15, 15),
                            enemy.Position.Y + Raylib.GetRandomValue(-15, 15)),
                enemy.LootType));

            d.Message = $"{enemy.Type} defeated!  +{enemy.XPReward} XP  +${enemy.MoneyDrop}";
            d.MessageTimer = 1.8f;
        }
    }
}
}
UpdateSplats(dt);
UpdateDeathFx(dt);

    // Collect loot
    foreach (var loot in room.Loot)
    {
        if (loot.Collected) continue;
        if (Vector2.Distance(d.PlayerPos, loot.Position) < 30f)
        {
            loot.Collected = true;
            switch (loot.ItemType)
            {
                case "Bone":      player.Bones++;      break;
                case "Fur":       player.Fur++;        break;
                case "Stinger":   player.Stingers++;   break;
                case "Bear Pelt": player.BearPelts++;  break;
            }
            d.Message = $"+1 {loot.ItemType}";
            d.MessageTimer = 1f;
        }
    }

    // Boss chest
    if (room.IsBoss && room.AllEnemiesDead && !room.ChestOpened)
    {
        Vector2 chestPos = new Vector2(Dungeon.InnerX + Dungeon.InnerW - 80, Dungeon.InnerY + Dungeon.InnerH / 2f);
        if (Vector2.Distance(d.PlayerPos, chestPos) < 65f && Raylib.IsKeyPressed(KeyboardKey.E))
        {
            room.ChestOpened = true;
            int reward = 80 + d.CurrentRoom * 25;
            player.Money += reward;
            player.AddCombatXP(250);
            d.Message = $"Dungeon Complete!  +${reward}  +250 Combat XP!";
            d.MessageTimer = 4f;
            d.Complete = true;
            dungeonsCleared++;
        }
    }

    // Advance to next room through right door
    if (room.AllEnemiesDead && !d.IsLastRoom)
    {
        if (d.PlayerPos.X > Dungeon.InnerX + Dungeon.InnerW - 28)
        {
            d.CurrentRoom++;
            d.PlayerPos = new Vector2(Dungeon.InnerX + 70, Dungeon.InnerY + Dungeon.InnerH / 2f);
            player.Position = d.PlayerPos;
            d.Message = d.Rooms[d.CurrentRoom].IsBoss
                ? "BOSS ROOM!  Defeat the boss!"
                : $"Room {d.CurrentRoom + 1} of {d.TotalRooms} — Fight!";
            d.MessageTimer = 2f;
        }
    }

    // Player death — boot out
    if (player.Health <= 0)
    {
        player.Health = Math.Max(1, player.MaxHealth / 3);
        player.Money  = Math.Max(0, player.Money - 30);
        d.Close();
        player.Position = d.WorldReturnPos;
        currentScene = SceneState.World;
        ShowNotification("Defeated! Lost $30 and fled the dungeon.");
    }

    // floating texts
    for (int i = floatingTexts.Count - 1; i >= 0; i--)
    {
        var ft = floatingTexts[i];
        ft.Timer -= dt;
        ft.Position.Y -= 40f * dt;
        floatingTexts[i] = ft;
        if (ft.Timer <= 0) floatingTexts.RemoveAt(i);
    }
}
static void DrawDungeon()
{
    var d    = activeDungeon;
    var room = d.Rooms[d.CurrentRoom];

    // Background color per dungeon type
    Color bgColor = d.Type switch {
        "Forest"  => new Color((byte)12,(byte)28,(byte)12,(byte)255),
        "Snow"    => new Color((byte)18,(byte)22,(byte)38,(byte)255),
        "Desert"  => new Color((byte)38,(byte)22,(byte)8, (byte)255),
        "Volcano" => new Color((byte)28,(byte)8, (byte)4, (byte)255),
        _         => new Color((byte)12,(byte)12,(byte)18,(byte)255)
    };
    Color wallColor = d.Type switch {
        "Forest"  => new Color((byte)30,(byte)65,(byte)30,(byte)255),
        "Snow"    => new Color((byte)55,(byte)65,(byte)95,(byte)255),
        "Desert"  => new Color((byte)105,(byte)78,(byte)42,(byte)255),
        "Volcano" => new Color((byte)85,(byte)28,(byte)10,(byte)255),
        _         => new Color((byte)50,(byte)45,(byte)58,(byte)255)
    };
    Color floorA = d.Type switch {
        "Forest"  => new Color((byte)22,(byte)48,(byte)22,(byte)255),
        "Snow"    => new Color((byte)38,(byte)48,(byte)68,(byte)255),
        "Desert"  => new Color((byte)75,(byte)58,(byte)28,(byte)255),
        "Volcano" => new Color((byte)45,(byte)18,(byte)6, (byte)255),
        _         => new Color((byte)32,(byte)28,(byte)38,(byte)255)
    };
    Color floorB = new Color(
        (byte)Math.Min(255, floorA.R + 10),
        (byte)Math.Min(255, floorA.G + 10),
        (byte)Math.Min(255, floorA.B + 10), (byte)255);

    Raylib.ClearBackground(bgColor);

    // ── FLOOR TILES ──────────────────────────────────────────────────────────
    for (int tx = Dungeon.InnerX; tx < Dungeon.InnerX + Dungeon.InnerW; tx += 55)
        for (int ty = Dungeon.InnerY; ty < Dungeon.InnerY + Dungeon.InnerH; ty += 55)
            Raylib.DrawRectangle(tx, ty, 55, 55,
                ((tx / 55 + ty / 55) % 2 == 0) ? floorA : floorB);

    // ── WALLS ────────────────────────────────────────────────────────────────
    Raylib.DrawRectangle(Dungeon.RoomX, Dungeon.RoomY, Dungeon.RoomW, Dungeon.WallThick, wallColor);
    Raylib.DrawRectangle(Dungeon.RoomX, Dungeon.RoomY + Dungeon.RoomH - Dungeon.WallThick, Dungeon.RoomW, Dungeon.WallThick, wallColor);
    Raylib.DrawRectangle(Dungeon.RoomX, Dungeon.RoomY, Dungeon.WallThick, Dungeon.RoomH, wallColor);
    Raylib.DrawRectangle(Dungeon.RoomX + Dungeon.RoomW - Dungeon.WallThick, Dungeon.RoomY, Dungeon.WallThick, Dungeon.RoomH, wallColor);

    // ── WALL TORCHES ─────────────────────────────────────────────────────────
    int[] torchXs = { Dungeon.RoomX + 70, Dungeon.RoomX + Dungeon.RoomW / 2 - 6, Dungeon.RoomX + Dungeon.RoomW - 90 };
    foreach (int tx2 in torchXs)
    {
        Raylib.DrawRectangle(tx2, Dungeon.RoomY + 2, 12, 18, new Color((byte)80,(byte)50,(byte)20,(byte)255));
        Raylib.DrawCircle(tx2 + 6, Dungeon.RoomY + 2, 9,  new Color((byte)255,(byte)180,(byte)0,(byte)255));
        Raylib.DrawCircle(tx2 + 6, Dungeon.RoomY + 2, 14, new Color((byte)255,(byte)100,(byte)0,(byte)50));
    }

    // ── DOORS ────────────────────────────────────────────────────────────────
    bool doorOpen = room.AllEnemiesDead && !d.IsLastRoom;
    int doorY = Dungeon.InnerY + Dungeon.InnerH / 2 - 45;

    // Right door (advance)
    Color doorCol = doorOpen
        ? new Color((byte)0,(byte)180,(byte)60,(byte)255)
        : new Color((byte)140,(byte)30,(byte)30,(byte)255);
    Raylib.DrawRectangle(Dungeon.RoomX + Dungeon.RoomW - Dungeon.WallThick, doorY, Dungeon.WallThick, 90, doorCol);
    Raylib.DrawText(doorOpen ? ">>" : "X",
        Dungeon.RoomX + Dungeon.RoomW - Dungeon.WallThick + (doorOpen ? 2 : 6),
        doorY + 36, doorOpen ? 14 : 16, Color.White);

    // Left exit door (room 0 only)
    if (d.CurrentRoom == 0)
    {
        Raylib.DrawRectangle(Dungeon.RoomX, doorY, Dungeon.WallThick, 90, new Color((byte)0,(byte)140,(byte)220,(byte)255));
        Raylib.DrawText("<<", Dungeon.RoomX + 2, doorY + 36, 14, Color.White);
    }

    // ── BOSS CHEST ───────────────────────────────────────────────────────────
    if (room.IsBoss && room.AllEnemiesDead)
    {
        int cX = Dungeon.InnerX + Dungeon.InnerW - 100;
        int cY = Dungeon.InnerY + Dungeon.InnerH / 2 - 30;
        if (!room.ChestOpened)
        {
            Raylib.DrawRectangle(cX, cY, 65, 52, new Color((byte)140,(byte)100,(byte)30,(byte)255));
            Raylib.DrawRectangle(cX, cY, 65, 20, new Color((byte)180,(byte)140,(byte)50,(byte)255));
            Raylib.DrawRectangle(cX + 24, cY + 5, 18, 12, new Color((byte)200,(byte)160,(byte)40,(byte)255));
            if (Vector2.Distance(d.PlayerPos, new Vector2(cX + 32, cY + 26)) < 70f)
            {
                int hw = Raylib.MeasureText("E = Open Chest", 18);
                Raylib.DrawText("E = Open Chest", cX + 32 - hw / 2, cY - 30, 18, Color.Gold);
            }
        }
        else
        {
            Raylib.DrawRectangle(cX, cY + 20, 65, 32, new Color((byte)140,(byte)100,(byte)30,(byte)255));
            Raylib.DrawRectangle(cX, cY,      65, 22, new Color((byte)180,(byte)140,(byte)50,(byte)255));
        }
    }

    // ── LOOT DROPS ───────────────────────────────────────────────────────────
    foreach (var loot in room.Loot)
    {
        if (loot.Collected) continue;
        Raylib.DrawCircle((int)loot.Position.X, (int)loot.Position.Y, 10, Color.Gold);
        Raylib.DrawCircleLines((int)loot.Position.X, (int)loot.Position.Y, 10, Color.Yellow);
        int lw = Raylib.MeasureText(loot.ItemType, 11);
        Raylib.DrawText(loot.ItemType, (int)loot.Position.X - lw / 2, (int)loot.Position.Y + 14, 11, Color.Gold);
    }

    // ── ENEMIES ──────────────────────────────────────────────────────────────
    foreach (var enemy in room.Enemies)
        enemy.Draw();
    DrawSplats();
    DrawDeathFx();

    // ── FLOATING TEXTS ───────────────────────────────────────────────────────
    foreach (var ft in floatingTexts)
    {
        byte alpha = (byte)(255 * Math.Max(0, ft.Timer / 1.2f));
        Raylib.DrawText(ft.Text, (int)ft.Position.X, (int)ft.Position.Y, 22,
            new Color(ft.TextColor.R, ft.TextColor.G, ft.TextColor.B, alpha));
    }

    // ── PLAYER — full directional sprite via player.Draw() ───────────────────
    // player.Position is already synced to d.PlayerPos in UpdateDungeon
    // We draw without BeginMode2D so it renders at screen coords directly
    player.Hidden = false;
    player.Draw();

    // ── HUD ──────────────────────────────────────────────────────────────────

    // Dungeon name + room label
    int dnW = Raylib.MeasureText(d.Name, 30);
    Raylib.DrawText(d.Name, 640 - dnW / 2, 20, 30, Color.Gold);
    string roomLabel = room.IsBoss ? "★  BOSS ROOM  ★" : $"Room  {d.CurrentRoom + 1}  /  {d.TotalRooms}";
    int rlW = Raylib.MeasureText(roomLabel, 20);
    Raylib.DrawText(roomLabel, 640 - rlW / 2, 56, 20, room.IsBoss ? Color.Red : Color.LightGray);

    // Enemies remaining
    int alive = room.Enemies.Count(e => !e.Dead);
    Raylib.DrawText(alive > 0 ? $"Enemies: {alive}" : "Room cleared!",
        20, 20, 20, alive > 0 ? Color.Red : Color.Green);

    // Wallet
    Raylib.DrawText($"${player.Money}", ScreenWidth - 20 - Raylib.MeasureText($"${player.Money}", 20), 20, 20, Color.Gold);

    // Player HP bar
    int hbW = 220, hbX = 640 - hbW / 2;
    Raylib.DrawRectangle(hbX, ScreenHeight - 100, hbW, 20, new Color((byte)40,(byte)40,(byte)40,(byte)220));
    float hpPct = (float)player.Health / player.MaxHealth;
    Color hpCol = hpPct > 0.5f ? Color.Green : hpPct > 0.25f ? Color.Orange : Color.Red;
    Raylib.DrawRectangle(hbX, ScreenHeight - 100, (int)(hbW * hpPct), 20, hpCol);
    Raylib.DrawRectangleLines(hbX, ScreenHeight - 100, hbW, 20, Color.White);
    Raylib.DrawText($"HP  {player.Health} / {player.MaxHealth}", hbX + hbW / 2 - 50, ScreenHeight - 98, 16, Color.White);

    // Toolbar
    DrawToolbar();
    DrawCombatColumn();

    // Message banner
    if (d.MessageTimer > 0)
    {
        int mw = Raylib.MeasureText(d.Message, 24);
        Raylib.DrawRectangle(640 - mw / 2 - 12, ScreenHeight - 160, mw + 24, 34,
            new Color((byte)0,(byte)0,(byte)0,(byte)190));
        Raylib.DrawText(d.Message, 640 - mw / 2, ScreenHeight - 155, 24, Color.Yellow);
    }

    // Door advance hint
    if (room.AllEnemiesDead && !d.IsLastRoom)
    {
        int hw = Raylib.MeasureText("Move right to advance!", 18);
        Raylib.DrawText("Move right to advance!",
            Dungeon.RoomX + Dungeon.RoomW - hw - 30,
            Dungeon.RoomY + Dungeon.RoomH + 5, 18, Color.Green);
    }

    // Controls prompt
   if (showControlsHud)
{ 
    string prompt = d.Complete
        ? "E = Exit Dungeon"
        : d.CurrentRoom == 0
            ? "WASD / Arrow Keys = Move  |  SPACE or Click = Attack  |  G = Gear  |  Q = Exit"
            : "WASD / Arrow Keys = Move  |  SPACE or Click = Attack  |  G = Gear  |  ESC = Pause";

    int pw = Raylib.MeasureText(prompt, 14);
    Raylib.DrawText(prompt, 640 - pw / 2, ScreenHeight - 28, 14, Color.Gray);
}
    // Quit confirmation popup
if (dungeonQuitConfirm)
{
    // Darken screen
    Raylib.DrawRectangle(0, 0, ScreenWidth, ScreenHeight, new Color((byte)0,(byte)0,(byte)0,(byte)160));

    // Popup box
    int popW = 420, popH = 200;
    int popX = ScreenWidth / 2 - popW / 2;
    int popY = ScreenHeight / 2 - popH / 2;
    Raylib.DrawRectangle(popX, popY, popW, popH, new Color((byte)20,(byte)20,(byte)30,(byte)255));
    Raylib.DrawRectangleLines(popX, popY, popW, popH, Color.Red);

    // Title
    string title = "Quit Dungeon?";
    int tw = Raylib.MeasureText(title, 28);
    Raylib.DrawText(title, ScreenWidth / 2 - tw / 2, popY + 20, 28, Color.Red);

    // Warning text
    string warn = "All progress in this run will be lost.";
    int ww = Raylib.MeasureText(warn, 18);
    Raylib.DrawText(warn, ScreenWidth / 2 - ww / 2, popY + 62, 18, Color.LightGray);

    // Yes button
    Vector2 mouse = Raylib.GetMousePosition();
    Rectangle yesBtn = new Rectangle(ScreenWidth / 2 - 160, popY + 120, 140, 44);
    Rectangle noBtn  = new Rectangle(ScreenWidth / 2 + 20,  popY + 120, 140, 44);
    bool hYes = Raylib.CheckCollisionPointRec(mouse, yesBtn);
    bool hNo  = Raylib.CheckCollisionPointRec(mouse, noBtn);

    Raylib.DrawRectangleRec(yesBtn, hYes ? new Color((byte)160,(byte)30,(byte)30,(byte)255) : new Color((byte)80,(byte)20,(byte)20,(byte)255));
    Raylib.DrawRectangleLinesEx(yesBtn, 2, hYes ? Color.Red : Color.DarkGray);
    int yw = Raylib.MeasureText("Yes (Y)", 20);
    Raylib.DrawText("Yes (Y)", (int)(yesBtn.X + yesBtn.Width / 2 - yw / 2), (int)(yesBtn.Y + 12), 20, Color.White);

    Raylib.DrawRectangleRec(noBtn, hNo ? new Color((byte)30,(byte)100,(byte)30,(byte)255) : new Color((byte)20,(byte)60,(byte)20,(byte)255));
    Raylib.DrawRectangleLinesEx(noBtn, 2, hNo ? Color.Green : Color.DarkGray);
    int nw2 = Raylib.MeasureText("No (N)", 20);
    Raylib.DrawText("No (N)", (int)(noBtn.X + noBtn.Width / 2 - nw2 / 2), (int)(noBtn.Y + 12), 20, Color.White);

    // Mouse clicks
    if (Raylib.IsMouseButtonPressed(MouseButton.Left))
    {
        if (hYes)
        {
            dungeonQuitConfirm = false;
            activeDungeon.Close();
            player.Position = activeDungeon.WorldReturnPos;
            currentScene = SceneState.World;
        }
        else if (hNo)
            dungeonQuitConfirm = false;
    }
}

    // Pause and gear menus drawn on top of everything
    DrawArmorUI();
    DrawPauseMenu();
    DrawInventoryUI();
    DrawCalendarHUD();
}
public static bool IsTwoHandedWeapon(string weapon)
{
    if (weapon == null) return false;
    return weapon.Contains("Great Sword") || weapon.Contains("War Axe") || weapon.Contains("Battle Staff");
    // add any future 2H weapons here
}
static int GetTotalDefense()
{
    int def = 0;
    if (armorHelmet != null) def += GetArmorDefense(armorHelmet);
    if (armorBody   != null) def += GetArmorDefense(armorBody);
    if (armorLegs   != null) def += GetArmorDefense(armorLegs);
    if (armorBoots  != null) def += GetArmorDefense(armorBoots);
    if (armorGloves != null) def += GetArmorDefense(armorGloves);
    if (armorCape   != null) def += GetArmorDefense(armorCape);
    if (armorShield != null) def += GetArmorDefense(armorShield);
    return def;
}

