}
static bool AddToToolbar(string item)
{
    bool isTool = IsToolItem(item);
    int qty = isTool ? 1 : GetItemCount(item);
    if (qty <= 0) { ShowNotification($"No {item} to move"); return false; }

    // already on toolbar? stack onto it
    for (int i = 0; i < toolbarSlots.Length; i++)
    {
        if (toolbarSlots[i] == item)
        {
            if (!isTool)
            {
                toolbarCounts[i] += qty;
                ZeroOutInventory(item);
            }
            ShowNotification($"Moved {item} to toolbar");
            return true;
        }
    }

    // empty slot
    for (int i = 0; i < toolbarSlots.Length; i++)
    {
        if (toolbarSlots[i] == null)
        {
            toolbarSlots[i] = item;
            toolbarCounts[i] = qty;
            if (!isTool) ZeroOutInventory(item);
            ShowNotification($"Moved {qty}x {item} to toolbar");
            return true;
        }
    }

    ShowNotification("Toolbar is full!");
    return false;
}
// Adds one item directly to toolbar (for grocery/cooked items not tracked in player stats)
static bool AddOneItemToToolbar(string item)
{
    for (int i = 0; i < toolbarSlots.Length; i++)
        if (toolbarSlots[i] == item) { toolbarCounts[i]++; return true; }
    for (int i = 0; i < toolbarSlots.Length; i++)
        if (toolbarSlots[i] == null) { toolbarSlots[i] = item; toolbarCounts[i] = 1; return true; }
    return false;
}
// True if every toolbar slot is occupied.
static bool ToolbarFull() => toolbarSlots.All(s => s != null);

// Routes an item: toolbar first, then player inventory (stat counter), else fail.
static bool GiveItemToPlayer(string item)
{
    if (AddOneItemToToolbar(item)) return true;
    // fall back to the stat-based inventory if this item is tracked there
    switch (item)
    {
        case "Cooked Fish": case "Fish":      player.Fish++;       return true;
        case "Logs":        player.Logs++;    return true;
        // add any other stat-backed items you want to accept here
        default:
            // not stat-backed and toolbar full → can't store it
            return false;
    }
}

static void ZeroOutInventory(string item)
{
    switch (item)
    {
        case "Logs": player.Logs = 0; break;
        case "Birch Logs": player.BirchLogs = 0; break;
        case "Oak Logs": player.OakLogs = 0; break;
        case "Pine Logs": player.PineLogs = 0; break;
        case "Arctic Logs": player.ArcticLogs = 0; break;
        case "Dead Wood": player.DeadWood = 0; break;
        case "Fish": player.Fish = 0; break;
        case "Bones": player.Bones = 0; break;
        case "Fur": player.Fur = 0; break;
        case "Stingers": player.Stingers = 0; break;
        case "Pelts": player.BearPelts = 0; break;
        case "Arrows": player.Arrows = 0; break;
        case "Bolts": player.Bolts = 0; break;
        case "Money": player.Money = 0; break;
        case "Dog Fangs": player.DogFangs = 0; break;
        case "Wolf Claw": player.WolfClaws = 0; break;
        case "Venom Sac": player.VenomSacs = 0; break;
        case "Crab Claw": player.CrabClaws = 0; break;
        case "Bear Claw": player.BearClaws = 0; break;
        case "Crab Shell": player.CrabShells = 0; break;
        case "Shark Fin": player.SharkFins = 0; break;
        case "Shark Tooth": player.SharkTeeth = 0; break;
        case "Snake Skin": player.SnakeSkins = 0; break;
        case "Snake Fang": player.SnakeFangs = 0; break;
        case "Croc Scale": player.CrocScales = 0; break;
        case "Croc Tooth": player.CrocTeeth = 0; break;
        case "Lizard Scale": player.LizardScales = 0; break;
        case "Ember Stone": player.EmberStones = 0; break;
        case "Magma Shard": player.MagmaShards = 0; break;
        case "Lava Core": player.LavaCores = 0; break;
        case "Feather": player.Feathers = 0; break;
        case "Eagle Talon": player.EagleTalons = 0; break;
        case "Horn": player.Horns = 0; break;
        case "Goat Hoof": player.GoatHooves = 0; break;
        default: backpack.Remove(item); break;
    }
}

static void DrawToolbar()
{
    

    int slotSize = 56;
    int padding = 6;
    int totalW = 8 * (slotSize + padding) - padding;
    int startX = 20;
    int startY = ScreenHeight - slotSize - 20;

    Vector2 mouse = Raylib.GetMousePosition();

    byte tbAlpha = currentPhase == HandPhase.Tools ? (byte)210 : (byte)90;

    for (int i = 0; i < 8; i++)
    {
        int sx = startX + i * (slotSize + padding);
        bool selected = i == toolbarSelectedSlot;

        // slot background
        Raylib.DrawRectangle(sx, startY, slotSize, slotSize, new Color((byte)20,(byte)20,(byte)30, tbAlpha));
        Raylib.DrawRectangleLines(sx, startY, slotSize, slotSize,
            selected ? Color.Gold : new Color((byte)80,(byte)80,(byte)100,(byte)255));

        // selected glow
        if (selected)
            Raylib.DrawRectangle(sx, startY, slotSize, 3, Color.Gold);

        // slot number
        Raylib.DrawText($"{i + 1}", sx + 4, startY + 3, 13,
            new Color((byte)120,(byte)120,(byte)140,(byte)255));

        // draw item icon if occupied
        if (toolbarSlots[i] != null)
        {
            DrawToolbarIcon(toolbarSlots[i], sx, startY, slotSize);
            if (!IsToolItem(toolbarSlots[i]))
            DrawInventoryIcon(toolbarSlots[i], sx + 12, startY + 10, slotSize - 24);

             if (!IsToolItem(toolbarSlots[i]) && toolbarCounts[i] > 1)
        Raylib.DrawText($"{toolbarCounts[i]}", sx + 4, startY + 3, 14, Color.White);

            int nameW = Raylib.MeasureText(toolbarSlots[i], 11);
            Raylib.DrawText(toolbarSlots[i],
                sx + slotSize / 2 - nameW / 2,
                startY + slotSize - 14, 11,
                selected ? Color.Gold : Color.LightGray);
            
            // ── click to remove while inventory is open ──
            if (player.InventoryOpen)
            {
                Rectangle slotRect = new Rectangle(sx, startY, slotSize, slotSize);
                if (Raylib.CheckCollisionPointRec(mouse, slotRect))
                {
                    Raylib.DrawRectangleLines(sx, startY, slotSize, slotSize, Color.Red);
                    Raylib.DrawText("Remove", sx - 4, startY - 16, 12, Color.Red);
                    if (Raylib.IsMouseButtonPressed(MouseButton.Left))
                    {
                        ShowNotification($"Removed {toolbarSlots[i]} from toolbar");
                         RemoveFromToolbar(i);
                    }
                }
            }
        }
    }
    // highlight the toolbar when in Tools phase
    if (currentPhase == HandPhase.Tools)
    {
        Raylib.DrawRectangleLinesEx(
            new Rectangle(startX - 4, startY - 4, totalW + 8, slotSize + 8),
            3, Color.Gold);
    }

    // tooltip — show equipped tool name above toolbar
    if (toolbarSlots[toolbarSelectedSlot] != null)
    {
        string equipped = toolbarSlots[toolbarSelectedSlot];
        int tw = Raylib.MeasureText($"Equipped: {equipped}", 18);
        Raylib.DrawRectangle(startX, startY - 28, tw + 12, 24,
            new Color((byte)0,(byte)0,(byte)0,(byte)180));
        Raylib.DrawText($"Equipped: {equipped}", startX + 6, startY - 24, 18, Color.Gold);
    }
}

static void DrawToolbarIcon(string tool, int x, int y, int size)
{
    int cx = x + size / 2;
    int cy = y + size / 2 - 6;

    switch (tool)
    {
        case "Axe":
            Raylib.DrawRectangle(cx - 2, cy - 14, 5, 28,
                new Color((byte)120,(byte)80,(byte)30,(byte)255));
            Raylib.DrawRectangle(cx - 15, cy - 12, 16, 10,
                new Color((byte)160,(byte)160,(byte)170,(byte)255));
            break;

        case "Pickaxe":
            Raylib.DrawRectangle(cx - 2, cy - 12, 5, 26,
                new Color((byte)120,(byte)80,(byte)30,(byte)255));
            Raylib.DrawLine(cx - 12, cy - 14, cx + 12, cy - 14,
                new Color((byte)160,(byte)160,(byte)170,(byte)255));
            Raylib.DrawTriangle(
                new Vector2(cx - 12, cy - 14),
                new Vector2(cx - 16, cy - 6),
                new Vector2(cx - 4,  cy - 14),
                new Color((byte)160,(byte)160,(byte)170,(byte)255));
            Raylib.DrawTriangle(
                new Vector2(cx + 12, cy - 14),
                new Vector2(cx + 16, cy - 6),
                new Vector2(cx + 4,  cy - 14),
                new Color((byte)140,(byte)140,(byte)150,(byte)255));
            break;

        case "Rod":
            Raylib.DrawRectangle(cx - 2, cy - 16, 4, 30,
                new Color((byte)120,(byte)80,(byte)30,(byte)255));
            Raylib.DrawLine(cx + 2, cy - 16, cx + 16, cy,
                new Color((byte)200,(byte)200,(byte)200,(byte)255));
            Raylib.DrawCircle(cx + 16, cy, 3,
                new Color((byte)100,(byte)180,(byte)220,(byte)255));
            break;

        case "Net":
            for (int i = 0; i < 3; i++)
                Raylib.DrawLine(cx, cy - 14, cx - 14 + i * 14, cy + 8,
                    new Color((byte)180,(byte)160,(byte)80,(byte)255));
            for (int i = 0; i < 2; i++)
                Raylib.DrawLine(cx - 14, cy - 6 + i * 10, cx + 14, cy - 6 + i * 10,
                    new Color((byte)180,(byte)160,(byte)80,(byte)255));
            break;

        case "Torch":
            Raylib.DrawRectangle(cx - 3, cy - 8, 6, 22,
                new Color((byte)120,(byte)80,(byte)30,(byte)255));
            Raylib.DrawCircle(cx, cy - 10, 5,
                new Color((byte)255,(byte)180,(byte)0,(byte)255));
            Raylib.DrawCircle(cx, cy - 10, 8,
                new Color((byte)255,(byte)100,(byte)0,(byte)80));
            break;

        case "Stick":
            Raylib.DrawRectangle(cx - 2, cy - 16, 5, 32,
                new Color((byte)120,(byte)80,(byte)30,(byte)255));
            Raylib.DrawRectangle(cx - 1, cy - 18, 3, 5,
                new Color((byte)100,(byte)60,(byte)20,(byte)255));
            break;

        case "Sword":
            // blade
            Raylib.DrawRectangle(cx - 2, cy - 18, 5, 26,
                new Color((byte)180,(byte)190,(byte)200,(byte)255));
            // tip
            Raylib.DrawTriangle(
                new Vector2(cx - 2, cy - 18),
                new Vector2(cx + 3, cy - 18),
                new Vector2(cx,     cy - 26),
                new Color((byte)200,(byte)210,(byte)220,(byte)255));
            // crossguard
            Raylib.DrawRectangle(cx - 10, cy + 7, 21, 5,
                new Color((byte)180,(byte)140,(byte)40,(byte)255));
            // handle
            Raylib.DrawRectangle(cx - 2, cy + 12, 5, 14,
                new Color((byte)120,(byte)80,(byte)30,(byte)255));
            // pommel
            Raylib.DrawCircle(cx, cy + 26, 4,
                new Color((byte)180,(byte)140,(byte)40,(byte)255));
            break;
    }
}

static void DrawArmorUI()
{
    if (!armorMenuOpen) return;

    int panelW = 700;
    int panelH = 620;
    int panelX = ScreenWidth / 2 - panelW / 2;
    int panelY = ScreenHeight / 2 - panelH / 2;

    Raylib.DrawRectangle(panelX, panelY, panelW, panelH, new Color((byte)18,(byte)18,(byte)24,(byte)245));
    Raylib.DrawRectangleLines(panelX, panelY, panelW, panelH, Color.Gold);
    Raylib.DrawText("EQUIPMENT", panelX + 270, panelY + 12, 28, Color.Gold);
    Raylib.DrawText($"Defence: {GetTotalDefense()}", panelX + 20, panelY + 14, 20, Color.LightGray);

    // ── offensive stats from the equipped weapon ──
    string eqWeapon = GetActiveWeapon();
    int meleeDmg = 0, rangedDmg = 0, elementalDmg = 0;
    if (eqWeapon != null)
    {
        if (IsRangedWeapon(eqWeapon))
            rangedDmg = GetWeaponDamage(eqWeapon) + player.RangedLevel / 5;
        else if (eqWeapon.EndsWith("Staff"))
            elementalDmg = GetWeaponDamage(eqWeapon) + player.ElementalLevel / 3;
        else
            meleeDmg = 1 + (player.CombatLevel / 10) + GetWeaponDamage(eqWeapon);
    }

    Raylib.DrawText($"Melee: {meleeDmg}",      panelX + 20, panelY + 40, 18, new Color((byte)255,(byte)150,(byte)80,(byte)255));
    Raylib.DrawText($"Ranged: {rangedDmg}",    panelX + 20, panelY + 62, 18, new Color((byte)140,(byte)220,(byte)120,(byte)255));
    Raylib.DrawText($"Elemental: {elementalDmg}", panelX + 20, panelY + 84, 18, new Color((byte)150,(byte)180,(byte)255,(byte)255));

    Vector2 mouse = Raylib.GetMousePosition();

    // ── EQUIPPED SLOTS (unchanged) ──
    (string label, string value, int sx, int sy)[] slots =
    {
        ("HELMET",  armorHelmet, panelX + 280, panelY + 60),
        ("BODY",    armorBody,   panelX + 280, panelY + 130),
        ("LEGS",    armorLegs,   panelX + 280, panelY + 200),
        ("BOOTS",   armorBoots,  panelX + 280, panelY + 270),
        ("GLOVES",  armorGloves, panelX + 60,  panelY + 200),
        ("CAPE",    armorCape,   panelX + 60,  panelY + 130),
        ("WEAPON",  armorWeapon, panelX + 500, panelY + 130),
        ("SHIELD",  armorShield, panelX + 500, panelY + 200),
        ("AMMO",    equippedAmmo, panelX + 500, panelY + 270),
    };

    foreach (var (label, value, sx, sy) in slots)
    {
        bool isShieldSlot  = label == "SHIELD";
        bool shieldBlocked = isShieldSlot && IsTwoHandedWeapon(armorWeapon);

        Color borderColor = shieldBlocked ? Color.DarkGray : value != null ? Color.Gold : Color.Gray;

        Raylib.DrawRectangle(sx, sy, 140, 60, new Color((byte)35,(byte)35,(byte)45,(byte)255));
        Raylib.DrawRectangleLines(sx, sy, 140, 60, borderColor);
        Raylib.DrawText(label, sx + 6, sy + 6, 14, new Color((byte)120,(byte)120,(byte)140,(byte)255));

        if (shieldBlocked)
        {
            Raylib.DrawText("2H WEAPON", sx + 16, sy + 32, 14, Color.DarkGray);
        }
        else if (value != null)
        {
            DrawArmorIcon(value, sx + 6, sy + 22, 28);
            Raylib.DrawText(value, sx + 38, sy + 32, 13, Color.Gold);

               if (label == "AMMO")
                {
                     int ammoCount = value == "Arrows" ? player.Arrows
                                  : value == "Bolts" ? player.Bolts
                                  : value == "Arcane Essence" ? player.ArcaneEssence : 0;
                    Raylib.DrawText($"x{ammoCount}", sx + 38, sy + 16, 14, Color.White);
                }

            if (Raylib.CheckCollisionPointRec(mouse, new Rectangle(sx, sy, 140, 60)) && Raylib.IsMouseButtonPressed(MouseButton.Left))
            {
                UnequipArmorSlot(label);
                ShowNotification($"Unequipped {value}");
            }
        }
        else
        {
            Raylib.DrawText("Empty", sx + 40, sy + 32, 14, Color.DarkGray);
        }
    }

    DrawMannequin(panelX + 280 + 70, panelY + 380);

    // ── TABS: OWNED vs TEST ──
    Rectangle ownedTab = new Rectangle(panelX + 20, panelY + 432, 150, 32);
    Rectangle testTab  = new Rectangle(panelX + 180, panelY + 432, 150, 32);
    bool hoverOwned = Raylib.CheckCollisionPointRec(mouse, ownedTab);
    bool hoverTest  = Raylib.CheckCollisionPointRec(mouse, testTab);

    Raylib.DrawRectangleRec(ownedTab, !gearTestMode ? new Color((byte)70,(byte)55,(byte)20,(byte)255) : new Color((byte)40,(byte)40,(byte)40,(byte)255));
    Raylib.DrawRectangleLinesEx(ownedTab, 2, !gearTestMode ? Color.Gold : (hoverOwned ? Color.Gold : Color.White));
    Raylib.DrawText("MY GEAR", panelX + 50, panelY + 440, 18, !gearTestMode ? Color.Gold : Color.White);

    Raylib.DrawRectangleRec(testTab, gearTestMode ? new Color((byte)70,(byte)55,(byte)20,(byte)255) : new Color((byte)40,(byte)40,(byte)40,(byte)255));
    Raylib.DrawRectangleLinesEx(testTab, 2, gearTestMode ? Color.Gold : (hoverTest ? Color.Gold : Color.White));
    Raylib.DrawText("TEST (ALL)", panelX + 205, panelY + 440, 18, gearTestMode ? Color.Gold : Color.White);

    if (hoverOwned && Raylib.IsMouseButtonPressed(MouseButton.Left)) gearTestMode = false;
    if (hoverTest  && Raylib.IsMouseButtonPressed(MouseButton.Left)) gearTestMode = true;

    Raylib.DrawRectangle(panelX + 10, panelY + 470, panelW - 20, 2, new Color((byte)80,(byte)80,(byte)80,(byte)255));

    // ── ITEM LIST ──
    string[] testCatalog = {
        "Leather Cap","Iron Helmet","Steel Helmet",
        "Leather Vest","Iron Chestplate","Steel Chestplate",
        "Leather Pants","Iron Leggings","Steel Leggings",
        "Leather Boots","Iron Boots","Steel Boots",
        "Leather Gloves","Iron Gauntlets","Steel Gauntlets",
        "Wool Cape","Magic Cape",
        "Wooden Shield","Iron Shield","Steel Shield",
        "Sword","Great Sword","War Axe","Battle Staff",
        "Bow","Crossbow"
    };

    List<string> shown = gearTestMode
        ? testCatalog.ToList()
        : player.OwnedGear;

if (gearTestMode)
{
    int rowY = panelY + 478;
    for (int s = 0; s < 7; s++)
    {
        int ry = rowY + s * 22;
        string mat = armorMaterials[slotMaterialIndex[s]];
        string piece = slotPieceNames[s];

        // slot label
        Raylib.DrawText(piece, panelX + 14, ry, 14, Color.LightGray);

        // left arrow
        Rectangle lb = new Rectangle(panelX + 120, ry - 2, 20, 18);
        bool hL = Raylib.CheckCollisionPointRec(mouse, lb);
        Raylib.DrawRectangleRec(lb, new Color((byte)40,(byte)40,(byte)50,(byte)255));
        Raylib.DrawText("<", panelX + 125, ry, 14, hL ? Color.Gold : Color.White);

        // material name (colored swatch)
        Raylib.DrawText(mat, panelX + 148, ry, 14, Program.MaterialColor(mat));

        // right arrow
        Rectangle rb = new Rectangle(panelX + 250, ry - 2, 20, 18);
        bool hR = Raylib.CheckCollisionPointRec(mouse, rb);
        Raylib.DrawRectangleRec(rb, new Color((byte)40,(byte)40,(byte)50,(byte)255));
        Raylib.DrawText(">", panelX + 255, ry, 14, hR ? Color.Gold : Color.White);

        // equip button
        Rectangle eb = new Rectangle(panelX + 285, ry - 2, 70, 18);
        bool hE = Raylib.CheckCollisionPointRec(mouse, eb);
        Raylib.DrawRectangleRec(eb, new Color((byte)60,(byte)50,(byte)20,(byte)255));
        Raylib.DrawText("Equip", panelX + 292, ry, 14, hE ? Color.Gold : Color.White);

        if (hL && Raylib.IsMouseButtonPressed(MouseButton.Left))
            slotMaterialIndex[s] = (slotMaterialIndex[s] + armorMaterials.Length - 1) % armorMaterials.Length;
        if (hR && Raylib.IsMouseButtonPressed(MouseButton.Left))
            slotMaterialIndex[s] = (slotMaterialIndex[s] + 1) % armorMaterials.Length;
        if (hE && Raylib.IsMouseButtonPressed(MouseButton.Left))
        {
            string itemName = $"{mat} {piece}";
            switch (s)
            {
                case 0: armorHelmet = itemName; break;
                case 1: armorBody   = itemName; break;
                case 2: armorLegs   = itemName; break;
                case 3: armorBoots  = itemName; break;
                case 4: armorGloves = itemName; break;
                case 5: armorCape   = itemName; break;
                case 6: armorShield = itemName; break;
            }
            ShowNotification($"Equipped {itemName}");
        }
    }
    // ── WEAPON cyclers (right side) ──
    int wRowY = panelY + 478;
    int wx = panelX + 400;   // start to the right of armor
    Raylib.DrawText("WEAPONS", wx, wRowY - 20, 16, Color.Gold);

    for (int s = 0; s < weaponPieceNames.Length; s++)
    {
        int ry = wRowY + s * 22;
        string mat = armorMaterials[weaponMaterialIndex[s]];
        string piece = weaponPieceNames[s];

        // label
        Raylib.DrawText(piece, wx, ry, 13, Color.LightGray);

        // left arrow
        Rectangle lb = new Rectangle(wx + 90, ry - 2, 20, 18);
        bool hL = Raylib.CheckCollisionPointRec(mouse, lb);
        Raylib.DrawRectangleRec(lb, new Color((byte)40,(byte)40,(byte)50,(byte)255));
        Raylib.DrawText("<", wx + 95, ry, 14, hL ? Color.Gold : Color.White);

        // material name
        Raylib.DrawText(mat, wx + 116, ry, 12, Program.MaterialColor(mat));

        // right arrow
        Rectangle rb = new Rectangle(wx + 200, ry - 2, 20, 18);
        bool hR = Raylib.CheckCollisionPointRec(mouse, rb);
        Raylib.DrawRectangleRec(rb, new Color((byte)40,(byte)40,(byte)50,(byte)255));
        Raylib.DrawText(">", wx + 205, ry, 14, hR ? Color.Gold : Color.White);

        // equip button
        Rectangle eb = new Rectangle(wx + 230, ry - 2, 60, 18);
        bool hE = Raylib.CheckCollisionPointRec(mouse, eb);
        Raylib.DrawRectangleRec(eb, new Color((byte)60,(byte)50,(byte)20,(byte)255));
        Raylib.DrawText("Equip", wx + 235, ry, 13, hE ? Color.Gold : Color.White);

        if (hL && Raylib.IsMouseButtonPressed(MouseButton.Left))
            weaponMaterialIndex[s] = (weaponMaterialIndex[s] + armorMaterials.Length - 1) % armorMaterials.Length;
        if (hR && Raylib.IsMouseButtonPressed(MouseButton.Left))
            weaponMaterialIndex[s] = (weaponMaterialIndex[s] + 1) % armorMaterials.Length;
        if (hE && Raylib.IsMouseButtonPressed(MouseButton.Left))
        {
            string itemName = $"{mat} {piece}";
            // route to 1H or 2H slot
            if (piece == "Sword")
            {
                equipped1H = itemName;
                equipped2H = null;
            }
            else
            {
                equipped2H = itemName;
                equipped1H = null;
                armorShield = null;
            }
            armorWeapon = itemName;
            ShowNotification($"Equipped {itemName}");
        }
    }
}


   else if (!gearTestMode && shown.Count == 0)
    {
        Raylib.DrawText("No gear yet — craft, loot, or buy some!", panelX + 20, panelY + 485, 18, Color.Gray);
    }
    else
    {
        int itemSlot = 60, itemPad = 8;
        int perRow = 10;
        for (int i = 0; i < shown.Count && i < perRow * 2; i++)   // up to 2 rows of 10
        {
            int col = i % perRow;
            int row = i / perRow;
            int ix = panelX + 14 + col * (itemSlot + itemPad);
            int iy = panelY + 478 + row * (itemSlot + 6);

            string item = shown[i];
            bool hover = Raylib.CheckCollisionPointRec(mouse, new Rectangle(ix, iy, itemSlot, itemSlot));
            bool equipped = item == armorHelmet || item == armorBody || item == armorLegs
                         || item == armorBoots || item == armorGloves || item == armorCape
                         || item == armorWeapon || item == armorShield;

            Raylib.DrawRectangle(ix, iy, itemSlot, itemSlot, new Color((byte)40,(byte)40,(byte)50,(byte)255));
            Raylib.DrawRectangleLines(ix, iy, itemSlot, itemSlot,
                equipped ? Color.Green : (hover ? Color.Gold : new Color((byte)80,(byte)80,(byte)100,(byte)255)));

            DrawArmorIcon(item, ix + 4, iy + 6, 24);
            int nameW = Raylib.MeasureText(item.Length > 8 ? item.Substring(0,8) : item, 11);
            Raylib.DrawText(item.Length > 8 ? item.Substring(0,8) : item, ix + itemSlot/2 - nameW/2, iy + itemSlot - 16, 11, Color.LightGray);

            if (hover && Raylib.IsMouseButtonPressed(MouseButton.Left))
            {
                if (gearTestMode)
                    TryEquipItem(item);              // test mode equips anything
            }
        }
    }

    string hint = gearTestMode
        ? "TEST MODE — equip anything  |  Click slot to unequip  |  G = Close"
        : "Click item to equip  |  Click slot to unequip  |  G = Close";
    Raylib.DrawText(hint, panelX + 30, panelY + panelH - 26, 15, Color.LightGray);
}

static void TryEquipItem(string item)
{
    // figure out which slot this item belongs to
    string slot = GetItemSlot(item);
    if (slot == null) return;

    // block shield if 2H weapon equipped
    if (slot == "SHIELD" && IsTwoHandedWeapon(armorWeapon))
    {
        ShowNotification("Can't use a shield with a two-handed weapon!");
        return;
    }

    // block 2H weapon if shield equipped
    if (slot == "WEAPON" && IsTwoHandedWeapon(item) && armorShield != null)
    {
        ShowNotification("Unequip your shield first for a two-handed weapon!");
        return;
    }

    switch (slot)
    {
        case "HELMET": armorHelmet = item; break;
        case "BODY":   armorBody   = item; break;
        case "LEGS":   armorLegs   = item; break;
        case "BOOTS":  armorBoots  = item; break;
        case "GLOVES": armorGloves = item; break;
        case "CAPE":   armorCape   = item; break;
        case "WEAPON": armorWeapon = item; break;
        case "SHIELD": armorShield = item; break;
        
    }
    // sync the combat column with the gear-menu weapon slot
if (slot == "WEAPON")
{
    if (IsTwoHandedWeapon(item) || IsRangedWeapon(item))
    {
        equipped2H = item; equipped1H = null;
        if (item.Contains("Crossbow")) player.HasCrossbow = true;
        else if (item.Contains("Bow")) player.HasBow = true;
    }
    else
    {
        equipped1H = item; equipped2H = null;
    }
}
    ShowNotification($"Equipped {item}!");
}

static void UnequipArmorSlot(string slot)
{
    switch (slot)
    {
        case "HELMET": armorHelmet = null; break;
        case "BODY":   armorBody   = null; break;
        case "LEGS":   armorLegs   = null; break;
        case "BOOTS":  armorBoots  = null; break;
        case "GLOVES": armorGloves = null; break;
        case "CAPE":   armorCape   = null; break;
        case "WEAPON":
        if (armorWeapon == "Sword") swordPickedUp = true;
        else if (armorWeapon == "Stick") stickPickedUp = true;
        else if (armorWeapon == "Bow") player.HasBow = true;
        else if (armorWeapon == "Crossbow") player.HasCrossbow = true;
        else if (armorWeapon != null) player.AddGear(armorWeapon);  // other weapons go back to owned gear
        armorWeapon = null;
        equipped1H = null;
        equipped2H = null;
        break;
        case "SHIELD": armorShield = null; break;
        case "AMMO": equippedAmmo = null; break;
    }
}

static string GetItemSlot(string item)
{
    if (item == null) return null;

    // weapons (check specific before general)
    if (item.Contains("Great Sword") || item.Contains("War Axe")
        || item.Contains("Sword") || item.Contains("Stick")
        || item.Contains("Bow") || item.Contains("Crossbow")
        || item.EndsWith("Staff"))  
        return "WEAPON";

    // armor by piece suffix
    if (item.Contains("Helmet") || item.Contains("Cap"))        return "HELMET";
    if (item.Contains("Chestplate") || item.Contains("Vest") || item.Contains("Body"))  return "BODY";
    if (item.Contains("Leggings") || item.Contains("Pants") || item.Contains("Legs"))   return "LEGS";
    if (item.Contains("Boots"))                                  return "BOOTS";
    if (item.Contains("Gauntlets") || item.Contains("Gloves"))   return "GLOVES";
    if (item.Contains("Cape"))                                   return "CAPE";
    if (item.Contains("Shield"))                                 return "SHIELD";

    return null;
}

static void DrawArmorIcon(string item, int x, int y, int size)
{
    int cx = x + size / 2;
    int cy = y + size / 2;

    // inside DrawArmorIcon, add before or after the WEAPON case
    if (item == "Arrows")
    {
        Raylib.DrawLineEx(new Vector2(cx - 8, cy + 8), new Vector2(cx + 8, cy - 8), 2, new Color((byte)160,(byte)120,(byte)70,(byte)255));
        Raylib.DrawTriangle(new Vector2(cx + 8, cy - 8), new Vector2(cx + 3, cy - 7), new Vector2(cx + 7, cy - 3), Color.Gray);
        return;
    }
    if (item == "Bolts")
    {
        Raylib.DrawLineEx(new Vector2(cx - 8, cy + 8), new Vector2(cx + 8, cy - 8), 3, new Color((byte)120,(byte)90,(byte)50,(byte)255));
        return;
    }
    if (item == "Arcane Essence")
    {
        Raylib.DrawCircle(cx, cy, 12, new Color((byte)100,(byte)40,(byte)160,(byte)120));
        Raylib.DrawCircle(cx, cy, 8, new Color((byte)160,(byte)80,(byte)255,(byte)255));
        Raylib.DrawCircle(cx - 2, cy - 2, 3, Color.White);
        return;
    }
    switch (GetItemSlot(item))
    {
        case "HELMET":
{
    Color c = IconWeaponColor(item, new Color((byte)160,(byte)160,(byte)170,(byte)255));
    Raylib.DrawRectangle(cx - 8, cy - 2, 16, 10, c);
    Raylib.DrawRectangle(cx - 10, cy - 8, 20, 8, c);
    Raylib.DrawRectangle(cx - 6, cy + 8, 12, 4, new Color((byte)Math.Max(0,c.R-20),(byte)Math.Max(0,c.G-20),(byte)Math.Max(0,c.B-20),(byte)255));
    break;
}
case "BODY":
{
    Color c = IconWeaponColor(item, new Color((byte)160,(byte)160,(byte)170,(byte)255));
    Raylib.DrawRectangle(cx - 10, cy - 8, 20, 18, c);
    Raylib.DrawRectangle(cx - 14, cy - 6, 6, 12, new Color((byte)Math.Max(0,c.R-20),(byte)Math.Max(0,c.G-20),(byte)Math.Max(0,c.B-20),(byte)255));
    Raylib.DrawRectangle(cx + 8, cy - 6, 6, 12, new Color((byte)Math.Max(0,c.R-20),(byte)Math.Max(0,c.G-20),(byte)Math.Max(0,c.B-20),(byte)255));
    break;
}
case "LEGS":
{
    Color c = IconWeaponColor(item, new Color((byte)160,(byte)160,(byte)170,(byte)255));
    Raylib.DrawRectangle(cx - 9, cy - 8, 8, 18, c);
    Raylib.DrawRectangle(cx + 1, cy - 8, 8, 18, c);
    break;
}
case "BOOTS":
{
    Color c = IconWeaponColor(item, new Color((byte)120,(byte)80,(byte)30,(byte)255));
    Raylib.DrawRectangle(cx - 8, cy - 6, 7, 14, c);
    Raylib.DrawRectangle(cx + 1, cy - 6, 7, 14, c);
    Raylib.DrawRectangle(cx - 10, cy + 6, 9, 4, new Color((byte)Math.Max(0,c.R-20),(byte)Math.Max(0,c.G-20),(byte)Math.Max(0,c.B-20),(byte)255));
    Raylib.DrawRectangle(cx + 1, cy + 6, 9, 4, new Color((byte)Math.Max(0,c.R-20),(byte)Math.Max(0,c.G-20),(byte)Math.Max(0,c.B-20),(byte)255));
    break;
}
case "GLOVES":
{
    Color c = IconWeaponColor(item, new Color((byte)120,(byte)80,(byte)30,(byte)255));
    Raylib.DrawRectangle(cx - 8, cy - 4, 6, 10, c);
    Raylib.DrawRectangle(cx + 2, cy - 4, 6, 10, c);
    for (int f = 0; f < 4; f++)
        Raylib.DrawRectangle(cx - 8 + f * 4, cy - 8, 3, 6, c);
    break;
}
case "CAPE":
{
    Color c = IconWeaponColor(item, new Color((byte)140,(byte)60,(byte)60,(byte)255));
    Raylib.DrawTriangle(
        new Vector2(cx - 10, cy - 8),
        new Vector2(cx + 10, cy - 8),
        new Vector2(cx, cy + 12),
        c);
    break;
}
case "SHIELD":
{
    Color c = IconWeaponColor(item, new Color((byte)100,(byte)80,(byte)40,(byte)255));
    Raylib.DrawRectangle(cx - 8, cy - 10, 16, 20, c);
    Raylib.DrawTriangle(
        new Vector2(cx - 8, cy + 10),
        new Vector2(cx + 8, cy + 10),
        new Vector2(cx, cy + 18),
        c);
    Raylib.DrawCircle(cx, cy, 4, new Color((byte)180,(byte)140,(byte)40,(byte)255));
    break;
}
        case "WEAPON":
            // WEAPON icons (detect by name, tint by material)
if (item.Contains("Great Sword"))
{
    Color blade = IconWeaponColor(item, new Color((byte)180,(byte)190,(byte)200,(byte)255));
    Raylib.DrawRectangle(cx - 2, cy - 16, 4, 24, blade);                       // long blade
    Raylib.DrawTriangle(new Vector2(cx - 2, cy - 16), new Vector2(cx + 2, cy - 16), new Vector2(cx, cy - 22), blade);
    Raylib.DrawRectangle(cx - 10, cy + 6, 20, 4, new Color((byte)180,(byte)140,(byte)40,(byte)255)); // wide guard
    Raylib.DrawRectangle(cx - 2, cy + 10, 4, 8, new Color((byte)120,(byte)80,(byte)30,(byte)255));   // grip
    return;
}
if (item.Contains("War Axe"))
{
    Color metal = IconWeaponColor(item, new Color((byte)160,(byte)160,(byte)170,(byte)255));
    Raylib.DrawRectangle(cx - 2, cy - 14, 4, 30, new Color((byte)120,(byte)80,(byte)30,(byte)255));   // handle
    Raylib.DrawTriangle(new Vector2(cx, cy - 12), new Vector2(cx, cy + 2), new Vector2(cx + 14, cy - 5), metal); // axe head
    Raylib.DrawTriangle(new Vector2(cx, cy - 9), new Vector2(cx - 8, cy - 5), new Vector2(cx, cy - 1), metal);   // back spike
    return;
}
if (item.Contains("Sword"))
{
    Color blade = IconWeaponColor(item, new Color((byte)180,(byte)190,(byte)200,(byte)255));
    Raylib.DrawRectangle(cx - 2, cy - 12, 4, 18, blade);
    Raylib.DrawTriangle(new Vector2(cx - 2, cy - 12), new Vector2(cx + 2, cy - 12), new Vector2(cx, cy - 18), blade);
    Raylib.DrawRectangle(cx - 8, cy + 4, 16, 4, new Color((byte)180,(byte)140,(byte)40,(byte)255));
    Raylib.DrawRectangle(cx - 2, cy + 8, 4, 8, new Color((byte)120,(byte)80,(byte)30,(byte)255));
    return;
}

if (item.Contains("Great") && item.Contains("Staff"))
{
    Color orb = GetStaffColor(item);
    // long shaft (2H)
    Raylib.DrawRectangle(cx - 2, cy - 16, 4, 32, new Color((byte)100,(byte)70,(byte)40,(byte)255));
    // large glowing orb at top
    Raylib.DrawCircle(cx, cy - 18, 10, new Color(orb.R, orb.G, orb.B, (byte)110));
    Raylib.DrawCircle(cx, cy - 18, 7, orb);
    Raylib.DrawCircle(cx - 2, cy - 20, 2, Color.White);
    // second orb at base to mark it as the greater 2H version
    Raylib.DrawCircle(cx, cy + 12, 4, orb);
    return;
}
if (item.Contains("Staff"))
{
    Color orb = GetStaffColor(item);
    // shorter shaft (1H)
    Raylib.DrawRectangle(cx - 2, cy - 10, 4, 22, new Color((byte)110,(byte)80,(byte)45,(byte)255));
    // glowing orb at top
    Raylib.DrawCircle(cx, cy - 14, 7, new Color(orb.R, orb.G, orb.B, (byte)120));
    Raylib.DrawCircle(cx, cy - 14, 5, orb);
    Raylib.DrawCircle(cx - 1, cy - 15, 2, Color.White);
    return;
}
if (item.Contains("Stick"))
{
    Raylib.DrawRectangle(cx - 2, cy - 14, 4, 28, new Color((byte)120,(byte)80,(byte)30,(byte)255));
    return;
}
if (item.Contains("Bow"))
{
    Color limb = IconWeaponColor(item, new Color((byte)140,(byte)90,(byte)40,(byte)255));
    Raylib.DrawLineEx(new Vector2(cx, cy - 16), new Vector2(cx, cy + 16), 3, limb);
    Raylib.DrawLineEx(new Vector2(cx, cy - 16), new Vector2(cx - 5, cy - 9), 2, limb);
    Raylib.DrawLineEx(new Vector2(cx, cy + 16), new Vector2(cx - 5, cy + 9), 2, limb);
    Raylib.DrawLineEx(new Vector2(cx + 4, cy - 14), new Vector2(cx + 4, cy + 14), 1, new Color((byte)220,(byte)220,(byte)220,(byte)255));
    return;
}
if (item.Contains("Crossbow"))
{
    Color limb = IconWeaponColor(item, new Color((byte)90,(byte)60,(byte)30,(byte)255));
    Raylib.DrawLineEx(new Vector2(cx - 12, cy - 4), new Vector2(cx + 12, cy - 4), 3, limb);
    Raylib.DrawLineEx(new Vector2(cx, cy - 8), new Vector2(cx, cy + 12), 4, limb);
    Raylib.DrawTriangle(new Vector2(cx, cy - 14), new Vector2(cx - 3, cy - 8), new Vector2(cx + 3, cy - 8), Color.Gray);
    return;
}         
                // generic fallback
                Raylib.DrawLineEx(new Vector2(cx - 6, cy + 10), new Vector2(cx + 6, cy - 10), 3,
                    new Color((byte)180,(byte)190,(byte)200,(byte)255));
                Raylib.DrawLineEx(new Vector2(cx - 6, cy), new Vector2(cx + 6, cy), 4,
                    new Color((byte)180,(byte)140,(byte)40,(byte)255));
            break;
    }
}

static void DrawMannequin(int cx, int cy)
{
    // simple mannequin silhouette showing equipped gear
    Color helmetCol  = armorHelmet != null ? Color.Gold    : new Color((byte)60,(byte)60,(byte)70,(byte)255);
    Color bodyCol    = armorBody   != null ? Color.Gold    : new Color((byte)60,(byte)60,(byte)70,(byte)255);
    Color legsCol    = armorLegs   != null ? Color.Gold    : new Color((byte)60,(byte)60,(byte)70,(byte)255);
    Color bootsCol   = armorBoots  != null ? Color.Gold    : new Color((byte)60,(byte)60,(byte)70,(byte)255);
    Color glovesCol  = armorGloves != null ? Color.Gold    : new Color((byte)60,(byte)60,(byte)70,(byte)255);
    Color capeCol    = armorCape   != null ? Color.Purple  : new Color((byte)60,(byte)60,(byte)70,(byte)255);
    Color shieldCol  = armorShield != null ? Color.SkyBlue : new Color((byte)60,(byte)60,(byte)70,(byte)255);

    // cape (behind body)
    Raylib.DrawTriangle(
        new Vector2(cx - 14, cy - 30),
        new Vector2(cx + 14, cy - 30),
        new Vector2(cx,      cy + 40),
        capeCol);

    // helmet
    Raylib.DrawCircle(cx, cy - 42, 14, helmetCol);
    // body
    Raylib.DrawRectangle(cx - 14, cy - 28, 28, 38, bodyCol);
    // legs
    Raylib.DrawRectangle(cx - 12, cy + 10, 10, 26, legsCol);
    Raylib.DrawRectangle(cx + 2,  cy + 10, 10, 26, legsCol);
    // boots
    Raylib.DrawRectangle(cx - 14, cy + 34, 12, 8, bootsCol);
    Raylib.DrawRectangle(cx + 2,  cy + 34, 12, 8, bootsCol);
    // gloves / arms
    Raylib.DrawRectangle(cx - 24, cy - 26, 10, 24, glovesCol);
    Raylib.DrawRectangle(cx + 14, cy - 26, 10, 24, glovesCol);
    // shield (left arm)
    if (armorShield != null && !IsTwoHandedWeapon(armorWeapon))
    {
        Raylib.DrawRectangle(cx - 38, cy - 22, 12, 20, shieldCol);
        Raylib.DrawTriangle(
            new Vector2(cx - 38, cy - 2),
            new Vector2(cx - 26, cy - 2),
            new Vector2(cx - 32, cy + 8),
            shieldCol);
    }
}
static string GetActiveWeapon()
{
    if (equipped2H != null) return equipped2H;
    if (equipped1H != null) return equipped1H;
    return GetEquippedTool();   // fall back to toolbar sword/stick
}
public static string GetEquippedTool() => toolbarSlots[toolbarSelectedSlot];

static void DrawFishingUI()
{
    if (!isFishing) return;

    int barW = 500;
    int barX = ScreenWidth / 2 - barW / 2;
    int panelY = ScreenHeight - 150;

    Raylib.DrawRectangle(0, panelY - 10, ScreenWidth, 110, new Color((byte)0,(byte)0,(byte)0,(byte)170));

    // status text
    if (fishingResultTimer > 0 || fishingPhase < 2)
    {
        int tw = Raylib.MeasureText(fishingResult, 26);
        Color c = fishingResult.Contains("BITE") ? Color.Yellow
                : fishingResult.Contains("PERFECT") ? Color.Gold
                : fishingResult.Contains("away") || fishingResult.Contains("Missed") || fishingResult.Contains("snapped") ? Color.Red
                : Color.SkyBlue;
        Raylib.DrawText(fishingResult, ScreenWidth / 2 - tw / 2, panelY, 26, c);
    }

    // phase 0 — waiting indicator (a little bobbing dot)
    if (fishingPhase == 0)
    {
        float bob = MathF.Sin((float)Raylib.GetTime() * 4f) * 4f;
        Raylib.DrawCircle(ScreenWidth / 2, panelY + 55 + (int)bob, 8, Color.White);
        Raylib.DrawText("Waiting for a bite...", ScreenWidth / 2 - 90, panelY + 75, 16, Color.LightGray);
    }

    // phase 1 — react prompt flashing
    if (fishingPhase == 1)
    {
        if ((int)(Raylib.GetTime() * 6) % 2 == 0)
            Raylib.DrawText("! SPACE !", ScreenWidth / 2 - 60, panelY + 45, 34, Color.Yellow);
    }

    // phase 2 — reeling bar
    if (fishingPhase == 2)
    {
        int by = panelY + 50;
        Raylib.DrawRectangle(barX, by, barW, 28, new Color((byte)30,(byte)40,(byte)60,(byte)255));
        // green target zone
        int zoneX = barX + (int)(reelTargetMin * barW);
        int zoneW = (int)((reelTargetMax - reelTargetMin) * barW);
        Raylib.DrawRectangle(zoneX, by, zoneW, 28, new Color((byte)0,(byte)200,(byte)0,(byte)200));
        // perfect centre line
        int cx = barX + (int)((reelTargetMin + reelTargetMax) / 2f * barW);
        Raylib.DrawRectangle(cx - 1, by, 2, 28, new Color((byte)255,(byte)255,(byte)150,(byte)255));
        // moving cursor
        int curX = barX + (int)(reelBarPos * barW);
        Raylib.DrawRectangle(curX - 4, by - 6, 8, 40, Color.White);
        Raylib.DrawRectangleLines(barX, by, barW, 28, Color.White);
        Raylib.DrawText("SPACE in the green!  Q = Stop", ScreenWidth / 2 - 130, by + 36, 16, Color.LightGray);
    }
}

static readonly (PlayerMenuTab tab, string label)[] playerMenuTabs =
{
    (PlayerMenuTab.Identity,      "Identity"),
    (PlayerMenuTab.Stats,         "Stats"),
    (PlayerMenuTab.Crafting,      "Crafting"),
    (PlayerMenuTab.Achievements,  "Achievements"),
    (PlayerMenuTab.Unlocks,       "Unlocks"),
    (PlayerMenuTab.Relationships, "Relationships"),
    (PlayerMenuTab.Collectables,  "Collectables"),
};

static void DrawPlayerMenu()
{
    if (!playerMenuOpen) return;
    Vector2 mouse = Raylib.GetMousePosition();

    // full-screen dark backdrop
     Raylib.DrawRectangle(0, 0, ScreenWidth, ScreenHeight, new Color((byte)10,(byte)12,(byte)18,(byte)255));

    // ── left tab rail ──
    int railW = 220;
    Raylib.DrawRectangle(0, 0, railW, ScreenHeight, new Color((byte)18,(byte)20,(byte)30,(byte)255));
    Raylib.DrawRectangle(railW - 2, 0, 2, ScreenHeight, Color.Gold);
    Raylib.DrawText("PLAYER", 24, 24, 30, Color.Gold);
    Raylib.DrawText("[J] or ESC to close", 24, 60, 14, Color.Gray);

    for (int i = 0; i < playerMenuTabs.Length; i++)
    {
        var (tab, label) = playerMenuTabs[i];
        int ty = 110 + i * 54;
        Rectangle r = new Rectangle(12, ty, railW - 24, 46);
        bool hov = Raylib.CheckCollisionPointRec(mouse, r);
        bool active = playerMenuTab == tab;
        Raylib.DrawRectangleRec(r, active ? new Color((byte)50,(byte)55,(byte)80,(byte)255)
                                          : hov ? new Color((byte)30,(byte)33,(byte)48,(byte)255)
                                                : new Color((byte)22,(byte)24,(byte)36,(byte)255));
        if (active) Raylib.DrawRectangle(12, ty, 4, 46, Color.Gold);
        Raylib.DrawText(label, 30, ty + 13, 20, active ? Color.Gold : Color.White);
        if (hov && Raylib.IsMouseButtonPressed(MouseButton.Left)) playerMenuTab = tab;
    }

    // ── content panel ──
    int cx = railW + 30, cy = 30, cw = ScreenWidth - railW - 60;
    switch (playerMenuTab)
    {
        case PlayerMenuTab.Identity:      DrawPMIdentity(cx, cy, cw); break;
        case PlayerMenuTab.Stats:         DrawPMStats(cx, cy, cw); break;
        case PlayerMenuTab.Crafting:      DrawPMPlaceholder(cx, cy, "Crafting"); break;
        case PlayerMenuTab.Achievements:  DrawPMPlaceholder(cx, cy, "Achievements"); break;
        case PlayerMenuTab.Unlocks:       DrawPMUnlocks(cx, cy, cw); break;
        case PlayerMenuTab.Relationships: DrawPMPlaceholder(cx, cy, "Relationships"); break;
        case PlayerMenuTab.Collectables:  DrawPMPlaceholder(cx, cy, "Collectables"); break;
    }

    
}

static void DrawPMIdentity(int x, int y, int w)
{
    Raylib.DrawText("IDENTITY", x, y, 34, Color.Gold);

    // ── ID CARD ──
    int cardX = x, cardY = y + 52, cardW = 440, cardH = 150;
    // card body + border
    Raylib.DrawRectangle(cardX, cardY, cardW, cardH, new Color((byte)28,(byte)34,(byte)52,(byte)255));
    Raylib.DrawRectangleLinesEx(new Rectangle(cardX, cardY, cardW, cardH), 2, Color.Gold);
    // header strip
    Raylib.DrawRectangle(cardX, cardY, cardW, 30, new Color((byte)40,(byte)48,(byte)72,(byte)255));
    Raylib.DrawText("CITIZEN ID", cardX + 12, cardY + 7, 18, Color.Gold);
    Raylib.DrawText("MAORI SIDE", cardX + cardW - 150, cardY + 9, 14, Color.LightGray);

    // photo box
    int photoX = cardX + 14, photoY = cardY + 42, photoW = 96, photoH = 96;
    Raylib.DrawRectangle(photoX, photoY, photoW, photoH, new Color((byte)18,(byte)20,(byte)30,(byte)255));
    Raylib.DrawRectangleLinesEx(new Rectangle(photoX, photoY, photoW, photoH), 1, Color.Gray);
    
    Raylib.BeginScissorMode(photoX, photoY, photoW, photoH);
    
    float sc = 2.6f;
    int ax = photoX + photoW/2 - (int)(20 * sc);
    int ay = photoY + (int)(photoH * 0.20f);   // was 0.14f — nudges the head down

    int HX(int off) => ax + (int)(off * sc);
    int HY(int off) => ay + (int)(off * sc);
    int SZ(int v)   => (int)(v * sc);

    // shoulders/shirt first (behind head), only the top sliver visible at box bottom
    Raylib.DrawRectangle(HX(8), HY(20), SZ(24), SZ(20), player.ShirtColor);
    // head
    Raylib.DrawRectangle(HX(9), HY(0), SZ(22), SZ(20), player.SkinColor);
    // eyes
    Raylib.DrawRectangle(HX(13), HY(7), SZ(3), SZ(3), Color.Black);
    Raylib.DrawRectangle(HX(24), HY(7), SZ(3), SZ(3), Color.Black);
    

    // facial hair
    Color fc = playerFacialHairColor;
    switch (playerFacialHair)
    {
        case "Stubble":
            Raylib.DrawRectangle(HX(13), HY(17), SZ(14), SZ(4), new Color(fc.R, fc.G, fc.B, (byte)140));
            break;
        case "Moustache":
            Raylib.DrawRectangle(HX(13), HY(16), SZ(14), SZ(3), fc);
            break;
        case "Goatee":
            Raylib.DrawRectangle(HX(13), HY(16), SZ(14), SZ(3), fc);
            Raylib.DrawRectangle(HX(16), HY(19), SZ(8),  SZ(5), fc);
            break;
        case "Full Beard":
            Raylib.DrawRectangle(HX(11), HY(16), SZ(18), SZ(3), fc);
            Raylib.DrawRectangle(HX(10), HY(19), SZ(20), SZ(6), fc);
            break;
    }
    // mouth
    Raylib.DrawRectangle(HX(15), HY(17), SZ(10), SZ(2), new Color((byte)150,(byte)80,(byte)80,(byte)255));

    // hair
    Color hc = playerHairColor;
    switch (playerHairStyle)
    {
        case "Buzz Cut":
            Raylib.DrawRectangle(HX(9), HY(-2), SZ(22), SZ(6), hc);
            break;
        case "Flow":
            Raylib.DrawRectangle(HX(8), HY(2), SZ(24), SZ(8), hc);
            Raylib.DrawRectangle(HX(6), HY(8), SZ(6), SZ(14), hc);
            Raylib.DrawRectangle(HX(28), HY(8), SZ(6), SZ(14), hc);
            break;
        case "Curtains":
            Raylib.DrawRectangle(HX(8), HY(-2), SZ(24), SZ(7), hc);
            Raylib.DrawRectangle(HX(8), HY(4), SZ(8), SZ(10), hc);
            Raylib.DrawRectangle(HX(24), HY(4), SZ(8), SZ(10), hc);
            break;
        case "Mohawk":
            Raylib.DrawRectangle(HX(17), HY(-8), SZ(6), SZ(14), hc);
            break;
        case "Bald":
            break;
    }
    Raylib.EndScissorMode();

    // card text fields
    int fldX = photoX + photoW + 20, fld = cardY + 44;
    void CardLine(string k, string v)
    {
        Raylib.DrawText(k, fldX, fld, 14, Color.Gray);
        Raylib.DrawText(v, fldX + 90, fld, 16, Color.White);
        fld += 24;
    }
    CardLine("NAME", playerName ?? "—");
    CardLine("HEALTH", $"{player.Health}/{player.MaxHealth}");
    CardLine("FUNDS", $"${player.Money}");
    CardLine("ISSUED", $"{GetMonthString()} {dayOfMonth}");

    // ── STATS BELOW THE CARD ──
    int ly = cardY + cardH + 24;
    void Line(string k, string v)
    {
        Raylib.DrawText(k, x, ly, 20, Color.LightGray);
        Raylib.DrawText(v, x + 300, ly, 20, Color.White);
        ly += 30;
    }

    int hrs = (int)(totalPlayTime / 3600), mins = (int)((totalPlayTime % 3600) / 60);

    string topName = "—"; int topLv = 0;
    foreach (var s in cheatSkills)
        if (s.get() > topLv) { topLv = s.get(); topName = s.name; }

    string MostPlayed(Dictionary<string,int> d)
    {
        string best = "None yet"; int bestC = 0;
        foreach (var kv in d) if (kv.Value > bestC) { bestC = kv.Value; best = kv.Key; }
        return bestC > 0 ? $"{best} ({bestC})" : best;
    }

    Line("Time Played:", $"{hrs}h {mins}m");
    Line("Date:", $"{dayNames[dayOfWeek]}, {GetMonthString()} {dayOfMonth}");
    Line("Highest Skill:", $"{topName} (Lv {topLv})");
    Line("Most Played Sport:", MostPlayed(sportPlayCounts));
    Line("Most Played Minigame:", MostPlayed(minigamePlayCounts));
    Line("Dropzone Tickets:", player.Tickets.ToString());
    Line("Land Plots Owned:", ownedHousePlots.Count.ToString());
    Line("Dungeons Cleared:", dungeonsCleared.ToString());
    if (timesCheated > 0)
        Line("Times Cheated:", timesCheated.ToString());
}

static void DrawPMStats(int x, int y, int w)
{
    Raylib.DrawText("SKILLS", x, y, 34, Color.Gold);
    int col0 = x, col1 = x + w/2;
    int ry = y + 60, half = (cheatSkills.Length + 1) / 2;
    for (int i = 0; i < cheatSkills.Length; i++)
    {
        var s = cheatSkills[i];
        int colX = i < half ? col0 : col1;
        int rowY = y + 60 + (i % half) * 40;
        int lv = s.get();
        Raylib.DrawText(s.name, colX, rowY, 20, Color.White);
        Raylib.DrawText($"Lv {lv}", colX + 200, rowY, 20, Color.Gold);
        // mini level bar
        Raylib.DrawRectangle(colX, rowY + 24, 260, 6, new Color((byte)40,(byte)40,(byte)40,(byte)255));
        Raylib.DrawRectangle(colX, rowY + 24, (int)(260 * Math.Min(1f, lv / 100f)), 6, Color.Gold);
    }
}

static void DrawPMUnlocks(int x, int y, int w)
{
    Raylib.DrawText("LICENCES & THEORIES", x, y, 34, Color.Gold);
    int ly = y + 60;
    void L(string label, bool have)
    {
        Raylib.DrawText(label, x, ly, 20, Color.White);
        Raylib.DrawText(have ? "OWNED" : "—", x + 300, ly, 20, have ? Color.Green : Color.Gray);
        ly += 30;
    }
    L("Theory D", hasTheoryD); L("Theory C", hasTheoryC); L("Theory B", hasTheoryB);
    L("Theory A", hasTheoryA); L("Theory S", hasTheoryS);
    ly += 10;
    L("Practical D", hasPracticalD); L("Practical C", hasPracticalC); L("Practical B", hasPracticalB);
    L("Practical A", hasPracticalA); L("Practical S", hasPracticalS);
}

static void DrawPMPlaceholder(int x, int y, string title)
{
    Raylib.DrawText(title.ToUpper(), x, y, 34, Color.Gold);
    Raylib.DrawText("Coming soon.", x, y + 60, 22, Color.Gray);
}
static void DrawDroppedItems()
{
    foreach (var d in droppedItems)
    {
        bool flashing = d.Lifetime < 5f && (int)(d.Lifetime * 6) % 2 == 0;
        if (!flashing)
        {
            Raylib.DrawCircle((int)d.Position.X, (int)d.Position.Y + 6, 14, new Color((byte)0,(byte)0,(byte)0,(byte)80));
            DrawInventoryIcon(d.Name, (int)d.Position.X - 16, (int)d.Position.Y - 16, 32);
        }

        if (Vector2.Distance(player.Center, d.Position) < 50)
        {
            Raylib.DrawText($"F = Pick up {d.Name}", (int)d.Position.X - 50, (int)d.Position.Y - 36, 14, Color.White);
            Raylib.DrawText($"{(int)d.Lifetime}s", (int)d.Position.X - 8, (int)d.Position.Y + 18, 12, Color.Gray);
        }
    }
}
static void DrawDropQuantity()
{
    if (!dropQtyOpen) return;

    Raylib.DrawRectangle(0, 0, ScreenWidth, ScreenHeight, new Color((byte)0,(byte)0,(byte)0,(byte)150));

    int w = 440, h = 200;
    int px = ScreenWidth / 2 - w / 2;
    int py = ScreenHeight / 2 - h / 2;
    Raylib.DrawRectangle(px, py, w, h, new Color((byte)20,(byte)20,(byte)30,(byte)255));
    Raylib.DrawRectangleLines(px, py, w, h, Color.Gold);

    string title = $"Drop how many {dropQtyItem}?";
    int tw = Raylib.MeasureText(title, 24);
    Raylib.DrawText(title, ScreenWidth / 2 - tw / 2, py + 20, 24, Color.Gold);
    Raylib.DrawText($"You have: {dropQtyAvailable}", ScreenWidth / 2 - 60, py + 56, 18, Color.LightGray);

    Vector2 mouse = Raylib.GetMousePosition();

    // three buttons: 1, 5, All
    (string label, int amount)[] opts =
    {
        ("1", 1),
        ("5", Math.Min(5, dropQtyAvailable)),
        ("All", dropQtyAvailable),
    };

    int btnW = 110, btnH = 50, gap = 20;
    int totalW = btnW * 3 + gap * 2;
    int startX = ScreenWidth / 2 - totalW / 2;
    int btnY = py + 100;

    for (int i = 0; i < opts.Length; i++)
    {
        int bx = startX + i * (btnW + gap);
        Rectangle btn = new Rectangle(bx, btnY, btnW, btnH);
        bool hover = Raylib.CheckCollisionPointRec(mouse, btn);

        Raylib.DrawRectangleRec(btn, hover ? new Color((byte)60,(byte)50,(byte)20,(byte)255) : new Color((byte)40,(byte)40,(byte)50,(byte)255));
        Raylib.DrawRectangleLinesEx(btn, 2, hover ? Color.Gold : Color.White);
        int lw = Raylib.MeasureText(opts[i].label, 22);
        Raylib.DrawText(opts[i].label, bx + btnW / 2 - lw / 2, btnY + 14, 22, hover ? Color.Gold : Color.White);

        if (hover && Raylib.IsMouseButtonPressed(MouseButton.Left) && opts[i].amount > 0)
        {
            DropAmountToGround(dropQtyItem, opts[i].amount);
            dropQtyOpen = false;
            dropQtyItem = "";
            invSelectedIndex = -1;
            invSelectedName = "";
        }
    }

    // cancel
    Rectangle cancelBtn = new Rectangle(ScreenWidth / 2 - 50, py + h - 30, 100, 24);
    bool hCancel = Raylib.CheckCollisionPointRec(mouse, cancelBtn);
    Raylib.DrawText("Cancel", ScreenWidth / 2 - 28, py + h - 28, 18, hCancel ? Color.Gold : Color.Gray);
    if (hCancel && Raylib.IsMouseButtonPressed(MouseButton.Left))
    {
        dropQtyOpen = false;
        dropQtyItem = "";
    }
}
static void DropAmountToGround(string item, int amount)
{
    if (amount <= 0) return;

    if (item == "Money")
    {
        amount = Math.Min(amount, player.Money);
        player.Money -= amount;
    }
    else
    {
        amount = Math.Min(amount, GetItemCount(item));
        for (int i = 0; i < amount; i++)
            RemoveOneItem(item);
    }

    droppedItems.Add(new DroppedItem(item, amount, player.Position + new Vector2(0, 20)));
    ShowNotification($"Dropped {amount}x {item}");
}

static void DrawRocket(int x, int y)
{
