        static void DrawSpeechBubble(Vector2 npcPos, string text, Color bubbleColor)
{
    int padding = 8;
    int fontSize = 14;
    int textWidth = Raylib.MeasureText(text, fontSize);
    int bubbleW = textWidth + padding * 2;
    int bubbleH = fontSize + padding * 2;

    // position bubble above the NPC head
    int bx = (int)npcPos.X + 20 - bubbleW / 2;
    int by = (int)npcPos.Y - bubbleH - 18;

    // background
    Raylib.DrawRectangle(bx, by, bubbleW, bubbleH,
        new Color((byte)255,(byte)255,(byte)255,(byte)230));
    Raylib.DrawRectangleLines(bx, by, bubbleW, bubbleH, bubbleColor);

    // tail pointing down to NPC
    Raylib.DrawTriangle(
        new Vector2(bx + bubbleW / 2 - 6, by + bubbleH),
        new Vector2(bx + bubbleW / 2 + 6, by + bubbleH),
        new Vector2(bx + bubbleW / 2,     by + bubbleH + 10),
        new Color((byte)255,(byte)255,(byte)255,(byte)230)
    );
    Raylib.DrawLine(
        bx + bubbleW / 2 - 6, by + bubbleH,
        bx + bubbleW / 2,     by + bubbleH + 10,
        bubbleColor
    );
    Raylib.DrawLine(
        bx + bubbleW / 2 + 6, by + bubbleH,
        bx + bubbleW / 2,     by + bubbleH + 10,
        bubbleColor
    );

    // text
    Raylib.DrawText(text, bx + padding, by + padding, fontSize,
        new Color((byte)20,(byte)20,(byte)20,(byte)255));
}
static void DrawEggIcon(string egg, int cx, int cy, int size, bool rareGlow = false, float glowPhase = 0f)
{
    Color shell = EggColor(egg);
    Color light = new Color(
        (byte)Math.Min(255, shell.R + 50),
        (byte)Math.Min(255, shell.G + 50),
        (byte)Math.Min(255, shell.B + 50), (byte)255);

    // pulsing yellow rare-drop glow (drawn behind the egg)
    if (rareGlow)
    {
        float pulse = (MathF.Sin(glowPhase * 4f) + 1f) * 0.5f;   // 0→1
        for (int g = 3; g >= 1; g--)
        {
            byte ga = (byte)((22 + 30 * pulse) * g / 3f);
            Raylib.DrawCircle(cx, cy, size * (0.7f + 0.12f * g),
                new Color((byte)255,(byte)220,(byte)60, ga));
        }
    }

    // egg body (taller than wide)
    Raylib.DrawEllipse(cx, cy, size / 2, (int)(size * 0.62f), shell);
    Raylib.DrawEllipse(cx - size / 8, cy - size / 6, size / 8, size / 5, light); // highlight
    // speckles
    Raylib.DrawCircle(cx + size / 6, cy + size / 8, 2, light);
    Raylib.DrawCircle(cx - size / 5, cy + size / 4, 2, light);

    // bright golden outline when rare
    Color outline = rareGlow
        ? new Color((byte)255,(byte)215,(byte)40,(byte)255)
        : new Color((byte)0,(byte)0,(byte)0,(byte)70);
    Raylib.DrawEllipseLines(cx, cy, size / 2, (int)(size * 0.62f), outline);
}

static void DrawSpeechBubbleScreen(int sx, int sy, string text, float alphaPct = 1f)
{
    int padding  = 8;
    int fontSize = 15;
    int textWidth = Raylib.MeasureText(text, fontSize);
    int bubbleW  = Math.Min(textWidth + padding * 2, 400);
    int bubbleH  = fontSize + padding * 2;
    int bx = sx - bubbleW / 2;
    int by = sy - bubbleH - 18;
    byte alpha = (byte)(230 * Math.Clamp(alphaPct, 0f, 1f));

    Raylib.DrawRectangle(bx, by, bubbleW, bubbleH,
        new Color((byte)255,(byte)255,(byte)255,(byte)alpha));
    Raylib.DrawRectangleLines(bx, by, bubbleW, bubbleH,
        new Color((byte)80,(byte)80,(byte)80,(byte)alpha));
    // tail
    Raylib.DrawTriangle(
        new Vector2(bx + bubbleW / 2 - 6, by + bubbleH),
        new Vector2(bx + bubbleW / 2 + 6, by + bubbleH),
        new Vector2(bx + bubbleW / 2,     by + bubbleH + 10),
        new Color((byte)255,(byte)255,(byte)255,(byte)alpha));
    // text — truncate if too long
    string display = textWidth > 380 ? text[..Math.Min(text.Length, 28)] + "..." : text;
    Raylib.DrawText(display, bx + padding, by + padding, fontSize,
        new Color((byte)20,(byte)20,(byte)20,(byte)alpha));
}

        static bool IsNearRoad(Vector2 pos, int buffer = 80)
        {
            // main horizontal road
            if (pos.Y >= 540 - buffer && pos.Y <= 743 + buffer) return true;

            // north/south highway
            if (pos.X >= 188 - buffer && pos.X <= 333 + buffer) return true;

            // desert side road
            if (pos.Y >= 188 - buffer && pos.Y <= 333 + buffer && pos.X >= 4000 - buffer) return true;

            // snow side road
            if (pos.Y >= 188 - buffer && pos.Y <= 333 + buffer && pos.X <= -3000 + buffer) return true;

            // ring road top
            if (pos.Y >= -38020 - buffer && pos.Y <= -37820 + buffer) return true;

            // ring road bottom
            if (pos.Y >= 38000 - buffer && pos.Y <= 38200 + buffer) return true;

            // ring road left
            if (pos.X >= -40000 - buffer && pos.X <= -39820 + buffer) return true;

            // ring road right
            if (pos.X >= 39820 - buffer && pos.X <= 40000 + buffer) return true;

            // snow vertical connectors
            if (pos.X >= -20015 - buffer && pos.X <= -19865 + buffer) return true;
            if (pos.X >= -10015 - buffer && pos.X <= -9865 + buffer) return true;

            // desert vertical connectors
            if (pos.X >= 14985 - buffer && pos.X <= 15135 + buffer) return true;
            if (pos.X >= 24985 - buffer && pos.X <= 25135 + buffer) return true;

            // vertical roads to buildings
            if (pos.X >= 1020 - buffer && pos.X <= 1140 + buffer) return true;
            if (pos.X >= -1260 - buffer && pos.X <= -1140 + buffer) return true;
            if (pos.X >= 200 - buffer && pos.X <= 320 + buffer && pos.Y <= 550 + buffer) return true;
            if (pos.X >= 500 - buffer && pos.X <= 620 + buffer && pos.Y <= 550 + buffer) return true;

            return false;
        }

        static bool IsOnRoadOrSafeZone(Vector2 pos)
        {
            // gas station forecourt
            if (pos.X >= 300 && pos.X <= 1000 && pos.Y >= -1000 && pos.Y <= -420) return true;

            // main horizontal road
            if (pos.Y >= 540 && pos.Y <= 743) return true;

            // north/south highway
            if (pos.X >= 188 && pos.X <= 333) return true;

            // desert side road
            if (pos.Y >= 188 && pos.Y <= 333 && pos.X >= 4000) return true;

            // snow side road
            if (pos.Y >= 188 && pos.Y <= 333 && pos.X <= -3000) return true;

            // ring road top
            if (pos.Y >= -38020 && pos.Y <= -37820) return true;

            // ring road bottom
            if (pos.Y >= 38000 && pos.Y <= 38200) return true;

            // ring road left
            if (pos.X >= -40000 && pos.X <= -39820) return true;

            // ring road right
            if (pos.X >= 39820 && pos.X <= 40000) return true;

            // snow vertical connectors - scoped to Y range between side road and ring road
            if (pos.X >= -20015 && pos.X <= -19865 && (pos.Y <= 188 || pos.Y >= 333)) return true;
            if (pos.X >= -10015 && pos.X <= -9865 && (pos.Y <= 188 || pos.Y >= 333)) return true;

            // desert vertical connectors - scoped to Y range
            if (pos.X >= 14985 && pos.X <= 15135 && (pos.Y <= 188 || pos.Y >= 333)) return true;
            if (pos.X >= 24985 && pos.X <= 25135 && (pos.Y <= 188 || pos.Y >= 333)) return true;

            return false;
        }

        static void GenerateSafeZoneTexture()
        {
            for (int x = -2900; x < 3900; x += 320)
            {
                for (int y = -1400; y < 2400; y += 320)
                {
                    Vector2 pos = new Vector2(x + 60, y + 60);
                    if (IsOnRoadOrSafeZone(pos)) continue;
                    float radius = 18 + (Math.Abs(x * y) % 28);
                    byte green = (byte)(110 + (Math.Abs(x + y) % 30));
                    grassPatches.Add((pos, radius, new Color((byte)55, green, (byte)55, (byte)70)));
                }
            }

            Color[] flowerColors = { Color.Red, Color.Yellow, Color.White, Color.Pink, Color.Orange, Color.Purple };
            for (int x = -2900; x < 3900; x += 260)
            {
                for (int y = -1400; y < 2400; y += 260)
                {
                    Vector2 pos = new Vector2(x + 30, y + 30);
                    if (IsOnRoadOrSafeZone(pos)) continue;
                    Color fc = flowerColors[Math.Abs(x + y) % flowerColors.Length];
                    flowers.Add((pos, fc));
                }
            }
        }

        static void GenerateBiomeTextures()
{
    // DESERT patches
    for (int x = 4000; x < 39000; x += 500)
    {
        for (int y = -39000; y < 39000; y += 500)
        {
            Vector2 pos = new Vector2(x + 80, y + 80);
            if (IsNearRoad(pos)) continue;
            float radius = 14 + (Math.Abs(x * y) % 24);
            byte r = (byte)(175 + Math.Abs(x + y) % 35);
            byte g = (byte)(135 + Math.Abs(x - y) % 25);
            byte b = (byte)(55  + Math.Abs(x)     % 25);
            desertPatches.Add((pos, radius, new Color(r, g, b, (byte)90)));
        }
    }

    // DESERT rocks
    for (int x = 4000; x < 39000; x += 900)
    {
        for (int y = -39000; y < 39000; y += 900)
        {
            Vector2 pos = new Vector2(x + 150, y + 150);
            if (IsNearRoad(pos)) continue;
            byte shade = (byte)(155 + Math.Abs(x + y) % 35);
            desertRocks.Add((pos, new Color(shade, shade, (byte)Math.Max(0, shade - 25), (byte)255)));
        }
    }

    // SNOW patches
    for (int x = -39000; x < -3000; x += 500)
    {
        for (int y = -39000; y < 39000; y += 500)
        {
            Vector2 pos = new Vector2(x + 80, y + 80);
            if (IsNearRoad(pos)) continue;
            float radius = 18 + (Math.Abs(x * y) % 38);
            snowPatches.Add((pos, radius));
        }
    }

    // SNOW rocks
    for (int x = -39000; x < -3000; x += 1000)
    {
        for (int y = -39000; y < 39000; y += 1000)
        {
            Vector2 pos = new Vector2(x + 200, y + 200);
            if (IsNearRoad(pos)) continue;
            byte shade = (byte)(135 + Math.Abs(x + y) % 35);
            snowRocks.Add((pos, new Color(shade, shade, (byte)Math.Min(255, shade + 12), (byte)255)));
        }
    }

    // FOREST TOP patches
    for (int x = -39000; x < 39000; x += 550)
    {
        for (int y = -39000; y < -400; y += 550)
        {
            Vector2 pos = new Vector2(x + 100, y + 100);
            if (IsNearRoad(pos)) continue;
            float radius = 22 + (Math.Abs(x * y) % 40);
            byte green = (byte)(55 + Math.Abs(x + y) % 50);
            forestPatches.Add((pos, radius, new Color((byte)18, green, (byte)18, (byte)110)));
        }
    }

    // FOREST BOTTOM patches
    for (int x = -39000; x < 39000; x += 550)
    {
        for (int y = 1000; y < 39000; y += 550)
        {
            Vector2 pos = new Vector2(x + 100, y + 100);
            if (IsNearRoad(pos)) continue;
            float radius = 22 + (Math.Abs(x * y) % 40);
            byte green = (byte)(55 + Math.Abs(x + y) % 50);
            forestPatches.Add((pos, radius, new Color((byte)18, green, (byte)18, (byte)110)));
        }
    }

    // FOREST mushrooms
    Color[] mushroomColors = { Color.Red, Color.Orange, Color.Purple, Color.White };
    for (int x = -39000; x < 39000; x += 1200)
    {
        for (int y = -39000; y < -400; y += 1200)
        {
            Vector2 pos = new Vector2(x + 300, y + 300);
            if (IsNearRoad(pos)) continue;
            forestMushrooms.Add((pos, mushroomColors[Math.Abs(x + y) % mushroomColors.Length]));
        }
        for (int y = 1000; y < 39000; y += 1200)
        {
            Vector2 pos = new Vector2(x + 300, y + 300);
            if (IsNearRoad(pos)) continue;
            forestMushrooms.Add((pos, mushroomColors[Math.Abs(x + y) % mushroomColors.Length]));
        }
    }

    // GRASSLANDS patches
    for (int x = 4000; x < 14000; x += 400)
    {
        for (int y = -400; y < 1000; y += 400)
        {
            Vector2 pos = new Vector2(x + 80, y + 80);
            if (IsNearRoad(pos)) continue;
            float radius = 12 + (Math.Abs(x * y) % 24);
            byte green = (byte)(125 + Math.Abs(x + y) % 40);
            grasslandPatches.Add((pos, radius, new Color((byte)75, green, (byte)55, (byte)95)));
        }
    }

    // GRASSLANDS flowers
    Color[] flowerColors = { Color.Red, Color.Yellow, Color.White, Color.Pink, Color.Orange, Color.Purple };
    for (int x = 4000; x < 14000; x += 340)
    {
        for (int y = -400; y < 1000; y += 340)
        {
            Vector2 pos = new Vector2(x + 50, y + 50);
            if (IsNearRoad(pos)) continue;
            grasslandFlowers.Add((pos, flowerColors[Math.Abs(x + y) % flowerColors.Length]));
        }
    }

    // OCEAN/BEACH sand ripples
    for (int x = 26000; x < 30000; x += 400)
    {
        for (int y = -39000; y < 39000; y += 400)
        {
            Vector2 pos = new Vector2(x + 80, y + 80);
            float radius = 20 + (Math.Abs(x * y) % 30);
            byte r = (byte)(200 + Math.Abs(x + y) % 40);
            byte g = (byte)(180 + Math.Abs(x - y) % 30);
            oceanPatches.Add((pos, radius, new Color(r, g, (byte)110, (byte)100)));
        }
    }

    // OCEAN shells
    Color[] shellColors = {
        new Color((byte)240,(byte)220,(byte)200,(byte)255),
        new Color((byte)220,(byte)180,(byte)160,(byte)255),
        new Color((byte)200,(byte)150,(byte)130,(byte)255)
    };
    for (int x = 26200; x < 30000; x += 350)
    {
        for (int y = -39000; y < 39000; y += 300)
        {
            Vector2 pos = new Vector2(x + 60, y + 60);
            oceanShells.Add((pos, shellColors[Math.Abs(x + y) % shellColors.Length]));
        }
    }

    // OCEAN coral
    Color[] coralColors = {
        new Color((byte)220,(byte)90,(byte)90,(byte)200),
        new Color((byte)255,(byte)160,(byte)60,(byte)200),
        new Color((byte)180,(byte)80,(byte)180,(byte)200)
    };
    for (int x = 30000; x < 60000; x += 600)
    {
        for (int y = -39000; y < 39000; y += 550)
        {
            Vector2 pos = new Vector2(x + 100, y + 100);
            oceanCoral.Add((pos, coralColors[Math.Abs(x + y) % coralColors.Length]));
        }
    }

    // SWAMP murky patches
    for (int x = -55000; x < -30000; x += 450)
    {
        for (int y = -39000; y < 39000; y += 450)
        {
            Vector2 pos = new Vector2(x + 80, y + 80);
            float radius = 25 + (Math.Abs(x * y) % 35);
            byte g = (byte)(55 + Math.Abs(x + y) % 35);
            swampPatches.Add((pos, radius, new Color((byte)30, g, (byte)25, (byte)160)));
        }
    }

    // SWAMP reeds
    for (int x = -55000; x < -30000; x += 280)
    {
        for (int y = -39000; y < 39000; y += 260)
        {
            Vector2 pos = new Vector2(x + 50, y + 50);
            Color reedColor = new Color((byte)50, (byte)90, (byte)30, (byte)220);
            swampReeds.Add((pos, reedColor));
        }
    }

    // SWAMP lily pads
    for (int x = -54000; x < -30000; x += 600)
    {
        for (int y = -39000; y < 39000; y += 550)
        {
            Vector2 pos = new Vector2(x + 120, y + 120);
            bool hasFlower = (Math.Abs(x + y) % 3 == 0);
            Color lilyColor = hasFlower
                ? new Color((byte)240,(byte)220,(byte)80,(byte)220)
                : new Color((byte)40,(byte)110,(byte)40,(byte)200);
            swampLilies.Add((pos, lilyColor));
        }
    }

    // VOLCANO lava patches
    for (int x = 26000; x < 60000; x += 500)
    {
        for (int y = -20000; y < -2000; y += 500)
        {
            Vector2 pos = new Vector2(x + 80, y + 80);
            float radius = 15 + (Math.Abs(x * y) % 25);
            bool bright = (Math.Abs(x + y) % 3 == 0);
            Color lavaColor = bright
                ? new Color((byte)255,(byte)180,(byte)0,(byte)200)
                : new Color((byte)200,(byte)60,(byte)0,(byte)200);
            volcanoPatches.Add((pos, radius, lavaColor));
        }
    }

    // VOLCANO steam vents
    for (int x = 27000; x < 60000; x += 1000)
    {
        for (int y = -20000; y < -2000; y += 900)
        {
            Vector2 pos = new Vector2(x + 200, y + 200);
            lavaVents.Add((pos, new Color((byte)80,(byte)70,(byte)65,(byte)180)));
        }
    }

    // MOUNTAIN rocky patches
    for (int x = -60000; x < -26000; x += 420)
    {
        for (int y = -20000; y < -2000; y += 400)
        {
            Vector2 pos = new Vector2(x + 80, y + 80);
            float radius = 10 + (Math.Abs(x * y) % 20);
            byte shade = (byte)(75 + Math.Abs(x + y) % 30);
            mountainPatches.Add((pos, radius, new Color(shade, (byte)(shade - 5), (byte)(shade - 10), (byte)255)));
        }
    }

    // MOUNTAIN pine trees
    for (int x = -59500; x < -26000; x += 550)
    {
        for (int y = -20000; y < -2000; y += 500)
        {
            if (Math.Abs(x + y) % 3 != 0) continue; // keep sparse
            Vector2 pos = new Vector2(x + 100, y + 100);
            mountainTrees.Add((pos, new Color((byte)25,(byte)55,(byte)30,(byte)255)));
        }
    }
}
        static void ShowNotification(string message)
        {
            levelUpMessage = message;
            levelUpTimer = 2.5f;
        }

        public static bool IsOnRoad(Vector2 pos)
{

    // gas station forecourt
    if (pos.X >= 300 && pos.X <= 1000 && pos.Y >= -1000 && pos.Y <= -420) return true;

    // main horizontal road + sidewalks
    if (pos.Y >= 540 && pos.Y <= 743) return true;

    // north/south highway + sidewalks
    if (pos.X >= 188 && pos.X <= 333) return true;

    // desert side road + sidewalks
    if (pos.Y >= 188 && pos.Y <= 333 && pos.X >= 4000) return true;

    // snow side road + sidewalks
    if (pos.Y >= 188 && pos.Y <= 333 && pos.X <= -3000) return true;

    // ring road top
    if (pos.Y >= -38020 && pos.Y <= -37820) return true;

    // ring road bottom
    if (pos.Y >= 38000 && pos.Y <= 38200) return true;

    // ring road left
    if (pos.X >= -40000 && pos.X <= -39800) return true;

    // ring road right
    if (pos.X >= 39800 && pos.X <= 40000) return true;

    // snow vertical connectors
    if (pos.X >= -20015 && pos.X <= -19865) return true;
    if (pos.X >= -10015 && pos.X <= -9865) return true;

    // desert vertical connectors
    if (pos.X >= 14985 && pos.X <= 15135) return true;
    if (pos.X >= 24985 && pos.X <= 25135) return true;

    // ── City of Hamiltron ─────────────────────────────────────────────────────
    if (pos.Y >= 5500 && pos.Y <= 5660 && pos.X >= 11800 && pos.X <= 18200) return true; // boulevard
    if (pos.X >= 14800 && pos.X <= 14960 && pos.Y >= 3000 && pos.Y <= 8200) return true; // north ave
    if (pos.Y >= 3900 && pos.Y <= 4020 && pos.X >= 11800 && pos.X <= 18200) return true; // cross N
    if (pos.Y >= 7200 && pos.Y <= 7320 && pos.X >= 11800 && pos.X <= 18200) return true; // cross S
    if (pos.X >= 12800 && pos.X <= 12920 && pos.Y >= 3000 && pos.Y <= 8200) return true; // cross W
    if (pos.X >= 16600 && pos.X <= 16720 && pos.Y >= 3000 && pos.Y <= 8200) return true; // cross E
    if (pos.Y >= 3000 && pos.Y <= 3120 && pos.X >= 11800 && pos.X <= 18000) return true; // ring N
    if (pos.Y >= 8100 && pos.Y <= 8220 && pos.X >= 11800 && pos.X <= 18000) return true; // ring S
    if (pos.X >= 11800 && pos.X <= 11920 && pos.Y >= 3000 && pos.Y <= 8220) return true; // ring W
    if (pos.X >= 17880 && pos.X <= 18000 && pos.Y >= 3000 && pos.Y <= 8220) return true; // ring E
    if (pos.X >= 14800 && pos.X <= 14960 && pos.Y >= 200  && pos.Y <= 3000) return true; // connector

    // ── Country Town Rotoaira ─────────────────────────────────────────────────
    if (pos.Y >= 4400 && pos.Y <= 4540 && pos.X >= -18000 && pos.X <= -13800) return true; // main st
    if (pos.X >= -17200 && pos.X <= -17080 && pos.Y >= 3200 && pos.Y <= 6200) return true; // side L
    if (pos.X >= -15400 && pos.X <= -15280 && pos.Y >= 3200 && pos.Y <= 6200) return true; // side R
    if (pos.Y >= 3200 && pos.Y <= 3320 && pos.X >= -18000 && pos.X <= -13800) return true; // loop N
    if (pos.Y >= 6100 && pos.Y <= 6220 && pos.X >= -18000 && pos.X <= -13800) return true; // loop S
    if (pos.X >= -18000 && pos.X <= -17880 && pos.Y >= 3200 && pos.Y <= 6220) return true; // loop W
    if (pos.X >= -13920 && pos.X <= -13800 && pos.Y >= 3200 && pos.Y <= 6220) return true; // loop E
    if (pos.X >= -16200 && pos.X <= -16080 && pos.Y >= 260  && pos.Y <= 3320) return true; // connector

    return false;
}

        static void DrawSafeZoneTexture()
{
    float viewLeft = camera.Target.X - ScreenWidth;
    float viewRight = camera.Target.X + ScreenWidth;
    float viewTop = camera.Target.Y - ScreenHeight;
    float viewBottom = camera.Target.Y + ScreenHeight;

    foreach (var patch in grassPatches)
   {
       if (patch.pos.X < viewLeft || patch.pos.X > viewRight ||
            patch.pos.Y < viewTop || patch.pos.Y > viewBottom) continue;
        Raylib.DrawCircle((int)patch.pos.X, (int)patch.pos.Y, patch.radius, patch.color);
    }

    foreach (var flower in flowers)
    {
        if (flower.pos.X < viewLeft || flower.pos.X > viewRight ||
            flower.pos.Y < viewTop || flower.pos.Y > viewBottom) continue;
        Raylib.DrawCircle((int)flower.pos.X, (int)flower.pos.Y, 5, flower.color);
        Raylib.DrawCircle((int)flower.pos.X + 10, (int)flower.pos.Y + 7, 4, flower.color);
        Raylib.DrawCircle((int)flower.pos.X - 9, (int)flower.pos.Y + 5, 4, flower.color);
        Raylib.DrawCircle((int)flower.pos.X + 5, (int)flower.pos.Y - 10, 4, flower.color);
    }

    // footpaths and fence stay the same - they are always near origin so no culling needed
    Raylib.DrawRectangle(1255, 530, 50, 80, new Color((byte)160,(byte)160,(byte)140,(byte)200));
    Raylib.DrawRectangle(-945, 530, 50, 80, new Color((byte)160,(byte)160,(byte)140,(byte)200));
    Raylib.DrawRectangle(395, 530, 50, 80, new Color((byte)160,(byte)160,(byte)140,(byte)200));
    Raylib.DrawRectangle(715, 530, 50, 80, new Color((byte)160,(byte)160,(byte)140,(byte)200));
    Raylib.DrawRectangle(-345, 530, 50, 80, new Color((byte)160,(byte)160,(byte)140,(byte)200));
    Raylib.DrawRectangle(1755, 530, 50, 80, new Color((byte)160,(byte)160,(byte)140,(byte)200));

}

static void DrawBiomeTextures()
{
    float viewLeft = camera.Target.X - ScreenWidth;
    float viewRight = camera.Target.X + ScreenWidth;
    float viewTop = camera.Target.Y - ScreenHeight;
    float viewBottom = camera.Target.Y + ScreenHeight;

    Color[] mushroomColors = { Color.Red, Color.Orange, Color.Purple, Color.White };
    Color[] flowerColors = { Color.Red, Color.Yellow, Color.White, Color.Pink, Color.Orange, Color.Purple };

    // draw manually placed items from static lists with camera culling
    foreach (var patch in grassPatches)
        if (patch.pos.X > viewLeft && patch.pos.X < viewRight &&
            patch.pos.Y > viewTop && patch.pos.Y < viewBottom)
            Raylib.DrawCircle((int)patch.pos.X, (int)patch.pos.Y, patch.radius, patch.color);

    foreach (var flower in flowers)
        if (flower.pos.X > viewLeft && flower.pos.X < viewRight &&
            flower.pos.Y > viewTop && flower.pos.Y < viewBottom)
        {
            Raylib.DrawCircle((int)flower.pos.X, (int)flower.pos.Y, 5, flower.color);
            Raylib.DrawCircle((int)flower.pos.X + 10, (int)flower.pos.Y + 7, 4, flower.color);
            Raylib.DrawCircle((int)flower.pos.X - 9, (int)flower.pos.Y + 5, 4, flower.color);
            Raylib.DrawCircle((int)flower.pos.X + 5, (int)flower.pos.Y - 10, 4, flower.color);
        }

    foreach (var patch in desertPatches)
        if (patch.pos.X > viewLeft && patch.pos.X < viewRight &&
            patch.pos.Y > viewTop && patch.pos.Y < viewBottom)
            Raylib.DrawCircle((int)patch.pos.X, (int)patch.pos.Y, patch.radius, patch.color);

    foreach (var rock in desertRocks)
        if (rock.pos.X > viewLeft && rock.pos.X < viewRight &&
            rock.pos.Y > viewTop && rock.pos.Y < viewBottom)
        {
            Raylib.DrawCircle((int)rock.pos.X, (int)rock.pos.Y, 8, rock.color);
            Raylib.DrawCircle((int)rock.pos.X + 10, (int)rock.pos.Y + 4, 6, rock.color);
            Raylib.DrawCircle((int)rock.pos.X - 6, (int)rock.pos.Y + 6, 5, rock.color);
        }

    foreach (var patch in snowPatches)
        if (patch.pos.X > viewLeft && patch.pos.X < viewRight &&
            patch.pos.Y > viewTop && patch.pos.Y < viewBottom)
            Raylib.DrawCircle((int)patch.pos.X, (int)patch.pos.Y, patch.radius,
                new Color((byte)240, (byte)248, (byte)255, (byte)180));

    foreach (var rock in snowRocks)
        if (rock.pos.X > viewLeft && rock.pos.X < viewRight &&
            rock.pos.Y > viewTop && rock.pos.Y < viewBottom)
        {
            Raylib.DrawCircle((int)rock.pos.X, (int)rock.pos.Y, 9, rock.color);
            Raylib.DrawCircle((int)rock.pos.X + 12, (int)rock.pos.Y + 5, 7, rock.color);
            Raylib.DrawCircle((int)rock.pos.X - 7, (int)rock.pos.Y + 7, 6, rock.color);
            Raylib.DrawCircle((int)rock.pos.X, (int)rock.pos.Y - 4, 5,
                new Color((byte)240, (byte)248, (byte)255, (byte)200));
        }

    foreach (var patch in forestPatches)
        if (patch.pos.X > viewLeft && patch.pos.X < viewRight &&
            patch.pos.Y > viewTop && patch.pos.Y < viewBottom)
            Raylib.DrawCircle((int)patch.pos.X, (int)patch.pos.Y, patch.radius, patch.color);

    foreach (var mushroom in forestMushrooms)
        if (mushroom.pos.X > viewLeft && mushroom.pos.X < viewRight &&
            mushroom.pos.Y > viewTop && mushroom.pos.Y < viewBottom)
        {
            Raylib.DrawRectangle((int)mushroom.pos.X - 3, (int)mushroom.pos.Y, 6, 10, Color.White);
            Raylib.DrawCircle((int)mushroom.pos.X, (int)mushroom.pos.Y, 8, mushroom.color);
            Raylib.DrawCircle((int)mushroom.pos.X - 3, (int)mushroom.pos.Y - 2, 2, Color.White);
            Raylib.DrawCircle((int)mushroom.pos.X + 3, (int)mushroom.pos.Y - 3, 2, Color.White);
        }

    foreach (var patch in grasslandPatches)
        if (patch.pos.X > viewLeft && patch.pos.X < viewRight &&
           patch.pos.Y > viewTop && patch.pos.Y < viewBottom)
        Raylib.DrawCircle((int)patch.pos.X, (int)patch.pos.Y, patch.radius, patch.color);

    foreach (var flower in grasslandFlowers)
        if (flower.pos.X > viewLeft && flower.pos.X < viewRight &&
            flower.pos.Y > viewTop && flower.pos.Y < viewBottom)
        {
            Raylib.DrawCircle((int)flower.pos.X, (int)flower.pos.Y, 5, flower.color);
            Raylib.DrawCircle((int)flower.pos.X + 10, (int)flower.pos.Y + 7, 4, flower.color);
            Raylib.DrawCircle((int)flower.pos.X - 9, (int)flower.pos.Y + 5, 4, flower.color);
            Raylib.DrawCircle((int)flower.pos.X + 5, (int)flower.pos.Y - 10, 4, flower.color);
        }

// OCEAN sand patches
    foreach (var patch in oceanPatches)
        if (patch.pos.X > viewLeft && patch.pos.X < viewRight &&
            patch.pos.Y > viewTop && patch.pos.Y < viewBottom)
            Raylib.DrawCircle((int)patch.pos.X, (int)patch.pos.Y, patch.radius, patch.color);

    // OCEAN shells
    foreach (var shell in oceanShells)
        if (shell.pos.X > viewLeft && shell.pos.X < viewRight &&
            shell.pos.Y > viewTop && shell.pos.Y < viewBottom)
        {
            int sx = (int)shell.pos.X;
            int sy = (int)shell.pos.Y;
            Raylib.DrawCircle(sx,     sy,     6, shell.color);
            Raylib.DrawCircle(sx + 3, sy - 2, 3, shell.color);
            Raylib.DrawCircle(sx + 5, sy - 4, 2, shell.color);
        }

    // OCEAN coral
    foreach (var coral in oceanCoral)
        if (coral.pos.X > viewLeft && coral.pos.X < viewRight &&
            coral.pos.Y > viewTop && coral.pos.Y < viewBottom)
        {
            int cx2 = (int)coral.pos.X;
            int cy2 = (int)coral.pos.Y;
            Raylib.DrawLineEx(new Vector2(cx2, cy2),      new Vector2(cx2,      cy2 - 18), 4, coral.color);
            Raylib.DrawLineEx(new Vector2(cx2, cy2 - 10), new Vector2(cx2 - 10, cy2 - 20), 3, coral.color);
            Raylib.DrawLineEx(new Vector2(cx2, cy2 - 10), new Vector2(cx2 + 10, cy2 - 20), 3, coral.color);
            Raylib.DrawCircle(cx2,      cy2 - 18, 4, coral.color);
            Raylib.DrawCircle(cx2 - 10, cy2 - 20, 3, coral.color);
            Raylib.DrawCircle(cx2 + 10, cy2 - 20, 3, coral.color);
        }

    // SWAMP murky patches
    foreach (var patch in swampPatches)
        if (patch.pos.X > viewLeft && patch.pos.X < viewRight &&
            patch.pos.Y > viewTop && patch.pos.Y < viewBottom)
            Raylib.DrawCircle((int)patch.pos.X, (int)patch.pos.Y, patch.radius, patch.color);

    // SWAMP reeds
    foreach (var reed in swampReeds)
        if (reed.pos.X > viewLeft && reed.pos.X < viewRight &&
            reed.pos.Y > viewTop && reed.pos.Y < viewBottom)
        {
            int gx = (int)reed.pos.X;
            int gy = (int)reed.pos.Y;
            Raylib.DrawLineEx(new Vector2(gx,     gy), new Vector2(gx - 3, gy - 22), 2, reed.color);
            Raylib.DrawLineEx(new Vector2(gx + 6, gy), new Vector2(gx + 4, gy - 18), 2, reed.color);
            Raylib.DrawLineEx(new Vector2(gx - 5, gy), new Vector2(gx - 8, gy - 20), 2, reed.color);
            Raylib.DrawEllipse(gx - 3, gy - 22, 3, 6, new Color((byte)80, (byte)50, (byte)20, (byte)255));
            Raylib.DrawEllipse(gx + 4, gy - 18, 3, 6, new Color((byte)80, (byte)50, (byte)20, (byte)255));
            Raylib.DrawEllipse(gx - 8, gy - 20, 3, 6, new Color((byte)80, (byte)50, (byte)20, (byte)255));
        }

    // SWAMP lily pads
    foreach (var lily in swampLilies)
        if (lily.pos.X > viewLeft && lily.pos.X < viewRight &&
            lily.pos.Y > viewTop && lily.pos.Y < viewBottom)
        {
            int lx = (int)lily.pos.X;
            int ly = (int)lily.pos.Y;
            Raylib.DrawCircle(lx, ly, 12, new Color((byte)40, (byte)110, (byte)40, (byte)200));
            Raylib.DrawTriangle(
                new Vector2(lx,     ly),
                new Vector2(lx + 6, ly - 12),
                new Vector2(lx - 6, ly - 12),
                new Color((byte)30, (byte)55, (byte)25, (byte)180));
            if (lily.color.R > 200)
                Raylib.DrawCircle(lx, ly - 4, 4, lily.color);
        }

    // VOLCANO lava patches
    foreach (var patch in volcanoPatches)
        if (patch.pos.X > viewLeft && patch.pos.X < viewRight &&
            patch.pos.Y > viewTop && patch.pos.Y < viewBottom)
            Raylib.DrawCircle((int)patch.pos.X, (int)patch.pos.Y, patch.radius, patch.color);

    // VOLCANO rocks (sparse, offset from patch positions)
    foreach (var patch in volcanoPatches)
        if (patch.pos.X > viewLeft && patch.pos.X < viewRight &&
            patch.pos.Y > viewTop && patch.pos.Y < viewBottom)
            if ((int)(patch.pos.X + patch.pos.Y) % 3 == 0)
            {
                int rx = (int)patch.pos.X + 20;
                int ry = (int)patch.pos.Y + 15;
                Color rockCol = new Color((byte)35, (byte)18, (byte)8, (byte)255);
                Raylib.DrawCircle(rx,      ry,     10, rockCol);
                Raylib.DrawCircle(rx + 10, ry + 5,  7, rockCol);
                Raylib.DrawCircle(rx - 6,  ry + 7,  6, rockCol);
            }

    // VOLCANO steam vents
    foreach (var vent in lavaVents)
        if (vent.pos.X > viewLeft && vent.pos.X < viewRight &&
            vent.pos.Y > viewTop && vent.pos.Y < viewBottom)
        {
            int vx = (int)vent.pos.X;
            int vy = (int)vent.pos.Y;
            for (int s = 0; s < 4; s++)
                Raylib.DrawEllipse(vx, vy - s * 10, 8 - s, 5 - s,
                    new Color((byte)200, (byte)200, (byte)200, (byte)(80 - s * 18)));
        }

    // MOUNTAIN rocky patches with snow dusting
    foreach (var patch in mountainPatches)
        if (patch.pos.X > viewLeft && patch.pos.X < viewRight &&
            patch.pos.Y > viewTop && patch.pos.Y < viewBottom)
        {
            int rx = (int)patch.pos.X;
            int ry = (int)patch.pos.Y;
            Raylib.DrawCircle(rx,      ry,     patch.radius, patch.color);
            Raylib.DrawCircle(rx + 12, ry + 6, patch.radius * 0.7f, patch.color);
            Raylib.DrawEllipse(rx, ry - 4, (int)(patch.radius * 0.6f), 3,
                new Color((byte)230, (byte)235, (byte)245, (byte)180));
        }

    // MOUNTAIN pine trees
    foreach (var tree in mountainTrees)
        if (tree.pos.X > viewLeft && tree.pos.X < viewRight &&
            tree.pos.Y > viewTop && tree.pos.Y < viewBottom)
        {
            int tx = (int)tree.pos.X;
            int ty = (int)tree.pos.Y;
            Raylib.DrawRectangle(tx - 3, ty, 6, 16, new Color((byte)70, (byte)50, (byte)30, (byte)255));
            Raylib.DrawTriangle(
                new Vector2(tx,      ty - 28), new Vector2(tx - 18, ty),      new Vector2(tx + 18, ty),
                tree.color);
            Raylib.DrawTriangle(
                new Vector2(tx,      ty - 38), new Vector2(tx - 13, ty - 14), new Vector2(tx + 13, ty - 14),
                new Color((byte)30, (byte)65, (byte)35, (byte)255));
            Raylib.DrawTriangle(
                new Vector2(tx,     ty - 46), new Vector2(tx - 8, ty - 28), new Vector2(tx + 8, ty - 28),
                new Color((byte)35, (byte)75, (byte)40, (byte)255));
            Raylib.DrawCircle(tx, ty - 46, 3, new Color((byte)230, (byte)235, (byte)245, (byte)200));
        }
}

        static void DrawStreetLight(float x, float y)
{
    // pole
    Raylib.DrawRectangle((int)x, (int)y, 6, 40, new Color((byte)80,(byte)80,(byte)80,(byte)255));

    // lamp head
    Raylib.DrawRectangle((int)x - 8, (int)y - 8, 22, 10, new Color((byte)60,(byte)60,(byte)60,(byte)255));

    // glow at night
    float night = MathF.Sin(timeOfDay * MathF.PI);
    if (night < 0.4f)
    {
        byte glowAlpha = (byte)(180 * (1f - night / 0.4f));
        Raylib.DrawCircle((int)x + 3, (int)y - 3, 60, new Color((byte)255,(byte)220,(byte)100,(byte)(glowAlpha / 4)));
        Raylib.DrawCircle((int)x + 3, (int)y - 3, 30, new Color((byte)255,(byte)220,(byte)100,(byte)(glowAlpha / 2)));
        Raylib.DrawRectangle((int)x - 8, (int)y - 8, 22, 10, new Color((byte)255,(byte)220,(byte)100,(byte)glowAlpha));
    }
}

        static void DrawStreetLights()
    {
        // main horizontal road - north side
        for (int i = -40000; i < 40000; i += 600)
            DrawStreetLight(i, 520);

        // main horizontal road - south side
        for (int i = -40000; i < 40000; i += 600)
            DrawStreetLight(i, 740);

        // north highway - west side
        for (int i = -40000; i < 550; i += 600)
            DrawStreetLight(180, i);

        // north highway - east side
        for (int i = -40000; i < 550; i += 600)
            DrawStreetLight(326, i);

        // south highway - west side
        for (int i = 730; i < 40000; i += 600)
            DrawStreetLight(180, i);

        // south highway - east side
        for (int i = 730; i < 40000; i += 600)
            DrawStreetLight(326, i);

        // desert side road
        for (int i = 4000; i < 40000; i += 600)
            DrawStreetLight(i, 180);

        // snow side road
        for (int i = -40000; i < -3000; i += 600)
            DrawStreetLight(i, 180);

        // ring road top
        for (int i = -40000; i < 40000; i += 600)
            DrawStreetLight(i, -38020);

        // ring road bottom
        for (int i = -40000; i < 40000; i += 600)
            DrawStreetLight(i, 38020);
        
        // City of Hamiltron street lights
        for (int i = 12000; i < 18000; i += 400)
        {
            DrawStreetLight(i, 5490);
            DrawStreetLight(i, 3890);
            DrawStreetLight(i, 7190);
        }
        for (int i = 3200; i < 8200; i += 400)
        {
            DrawStreetLight(14790, i);
            DrawStreetLight(12790, i);
            DrawStreetLight(16590, i);
        }
        // Country town street lights
        for (int i = -17800; i < -13900; i += 500)
            DrawStreetLight(i, 4390);
        DrawStreetLight(-17210, 3800);
        DrawStreetLight(-15410, 3800);
    }

      static void SaveGame()
{
    var d = new List<string>();
    void S(string k, object v) => d.Add(k + "=" + v.ToString());
    void SF(string k, float v) => d.Add(k + "=" + v.ToString(System.Globalization.CultureInfo.InvariantCulture));
    void SB(string k, bool v) => d.Add(k + "=" + (v ? "1" : "0"));
    string NN(string s) => s ?? "empty";

    S("version", 2);

    // ── Position & core ──
    SF("pos.x", player.Position.X); SF("pos.y", player.Position.Y);
    S("money", player.Money); S("bank", player.BankBalance);

    // ── Resources ──
    S("logs", player.Logs); S("birchLogs", player.BirchLogs); S("oakLogs", player.OakLogs);
    S("pineLogs", player.PineLogs); S("arcticLogs", player.ArcticLogs); S("deadWood", player.DeadWood);
    S("fish", player.Fish); S("bones", player.Bones); S("fur", player.Fur);
    S("stingers", player.Stingers); S("bearPelts", player.BearPelts);

    // ── Skills ──
    S("woodcutLv", player.WoodcuttingLevel); S("woodcutXp", player.WoodcuttingXP);
    S("fishLv", player.FishingLevel); S("fishXp", player.FishingXP);
    S("combatLv", player.CombatLevel); S("combatXp", player.CombatXP);
    S("oneHandLv", player.OneHandMeleeLevel); S("oneHandXp", player.OneHandMeleeXP);
    S("twoHandLv", player.TwoHandMeleeLevel); S("twoHandXp", player.TwoHandMeleeXP);
    S("strengthLv", player.StrengthLevel); S("strengthXp", player.StrengthXP);
    S("drivingLv", player.DrivingLevel); S("drivingXp", player.DrivingXP);
    S("athleticsLv", player.AthleticsLevel); S("athleticsXp", player.AthleticsXP);
    S("gamblingLv", player.GamblingLevel); S("gamblingXp", player.GamblingXP);
    S("ridingLv", player.RidingLevel); S("ridingXp", player.RidingXP);
    S("cyclingLv", player.CyclingLevel); S("cyclingXp", player.CyclingXP);
    S("miningLv", player.MiningLevel); S("miningXp", player.MiningXP);
    S("swimmingLv", player.SwimmingLevel); S("swimmingXp", player.SwimmingXP);
    S("divingLv", player.DivingLevel); S("divingXp", player.DivingXP);
    S("sportsLv", player.SportsLevel); S("sportsXp", player.SportsXP);
    S("rangedLv", player.RangedLevel); S("rangedXp", player.RangedXP);
    S("elementalLv", player.ElementalLevel); S("elementalXp", player.ElementalXP);
    S("cookingLv", player.CookingLevel); S("cookingXp", player.CookingXP);

    // ── Health & identity ──
    S("health", player.Health); S("maxHealth", player.MaxHealth); S("name", playerName);

    // ── Appearance ──
    S("shirtR", player.ShirtColor.R); S("shirtG", player.ShirtColor.G); S("shirtB", player.ShirtColor.B);
    S("skinR", player.SkinColor.R); S("skinG", player.SkinColor.G); S("skinB", player.SkinColor.B);
    S("pantsR", player.PantsColor.R); S("pantsG", player.PantsColor.G); S("pantsB", player.PantsColor.B);
    S("hairStyle", playerHairStyle ?? "None");
    S("hairR", playerHairColor.R); S("hairG", playerHairColor.G); S("hairB", playerHairColor.B);
    S("facialHair", playerFacialHair ?? "None");
    S("facialR", playerFacialHairColor.R); S("facialG", playerFacialHairColor.G); S("facialB", playerFacialHairColor.B);

    // ── Chest storage ──
    S("chestLogs", chestLogs); S("chestFish", chestFish); S("chestBones", chestBones);
    S("chestFur", chestFur); S("chestStingers", chestStingers); S("chestBearPelts", chestBearPelts);
    S("chestDogFangs", chestDogFangs); S("chestWolfClaws", chestWolfClaws); S("chestVenomSacs", chestVenomSacs);
    S("chestCrabClaws", chestCrabClaws); S("chestBearClaws", chestBearClaws); S("chestCrabShells", chestCrabShells);
    S("chestSharkFins", chestSharkFins); S("chestSharkTeeth", chestSharkTeeth); S("chestSnakeSkins", chestSnakeSkins);
    S("chestSnakeFangs", chestSnakeFangs); S("chestCrocScales", chestCrocScales); S("chestCrocTeeth", chestCrocTeeth);
    S("chestLizardScales", chestLizardScales); S("chestEmberStones", chestEmberStones); S("chestMagmaShards", chestMagmaShards);
    S("chestLavaCores", chestLavaCores); S("chestFeathers", chestFeathers); S("chestEagleTalons", chestEagleTalons);
    S("chestHorns", chestHorns); S("chestGoatHooves", chestGoatHooves);

    // ── Player loot materials ──
    S("dogFangs", player.DogFangs); S("wolfClaws", player.WolfClaws); S("venomSacs", player.VenomSacs);
    S("crabClaws", player.CrabClaws); S("bearClaws", player.BearClaws); S("crabShells", player.CrabShells);
    S("sharkFins", player.SharkFins); S("sharkTeeth", player.SharkTeeth); S("snakeSkins", player.SnakeSkins);
    S("snakeFangs", player.SnakeFangs); S("crocScales", player.CrocScales); S("crocTeeth", player.CrocTeeth);
    S("lizardScales", player.LizardScales); S("emberStones", player.EmberStones); S("magmaShards", player.MagmaShards);
    S("lavaCores", player.LavaCores); S("feathers", player.Feathers); S("eagleTalons", player.EagleTalons);
    S("horns", player.Horns); S("goatHooves", player.GoatHooves);

    // ── Quests ──
    S("quest0prog", quests[0].Progress); SB("quest0done", quests[0].Completed);
    S("quest1prog", quests[1].Progress); SB("quest1done", quests[1].Completed);
    S("quest2prog", quests[2].Progress); SB("quest2done", quests[2].Completed);

    // ── World / time ──
    SF("playtime", totalPlayTime);
    S("dayOfMonth", dayOfMonth); S("currentMonth", currentMonth);
    SF("timeOfDay", timeOfDay); S("dayOfWeek", dayOfWeek); S("tickets", player.Tickets);

    // ── Tool pickup flags ──
    SB("axePicked", axePickedUp); SB("pickaxePicked", pickaxePickedUp);
    SB("rodPicked", fishingRodPickedUp); SB("netPicked", fishingNetPickedUp);
    SB("torchPicked", torchPickedUp); SB("hasAxe", player.HasAxe);

    // ── Weapons / ammo ──
    S("arrows", player.Arrows); S("bolts", player.Bolts);
    SB("hasBow", player.HasBow); SB("hasCrossbow", player.HasCrossbow);
    S("equipped1H", NN(equipped1H)); S("equipped2H", NN(equipped2H)); S("equippedAmmo", NN(equippedAmmo));

    // ── Elemental / staff ──
    S("arcaneEssence", player.ArcaneEssence); S("equippedStaff", NN(player.EquippedStaff));

    // ── Armor ──
    S("armorHelmet", NN(armorHelmet)); S("armorBody", NN(armorBody)); S("armorLegs", NN(armorLegs));
    S("armorBoots", NN(armorBoots)); S("armorGloves", NN(armorGloves)); S("armorCape", NN(armorCape));
    S("armorShield", NN(armorShield));

    // ── Licences ──
    SB("theoryD", hasTheoryD); SB("theoryC", hasTheoryC); SB("theoryB", hasTheoryB);
    SB("theoryA", hasTheoryA); SB("theoryS", hasTheoryS);
    SB("pracD", hasPracticalD); SB("pracC", hasPracticalC); SB("pracB", hasPracticalB);
    SB("pracA", hasPracticalA); SB("pracS", hasPracticalS);

    // Stats
    S("dungeonsCleared", dungeonsCleared);
    S("timesCheated", timesCheated);
    S("sportCounts.count", sportPlayCounts.Count);
    int spi = 0;
    foreach (var kv in sportPlayCounts) { S("sportCount." + spi + ".k", kv.Key); S("sportCount." + spi + ".v", kv.Value); spi++; }
    S("miniCounts.count", minigamePlayCounts.Count);
    int mpi = 0;
    foreach (var kv in minigamePlayCounts) { S("miniCount." + mpi + ".k", kv.Key); S("miniCount." + mpi + ".v", kv.Value); mpi++; }

    // ── Tutorial state ──
    SB("tutDone", tutorialCompleted); SB("tutActive", tutorialActive); S("tutStep", tutorialStep);
    S("tutTaskCount", tutorialTasks.Count);
    for (int i = 0; i < tutorialTasks.Count; i++) SB("tutTask." + i, tutorialTasks[i].Done);

    // ── Cards ──
    S("cardsLv", player.PlayingCardsLevel); S("cardsXp", player.PlayingCardsXP);
    S("euchreRating", player.EuchreRating); S("fiveHundredRating", player.FiveHundredRating);
    S("sequenceRating", player.SequenceRating); S("euchreWins", player.EuchreWins);
    S("fiveHundredWins", player.FiveHundredWins); S("sequenceWins", player.SequenceWins);

    // ── Gear ──
    S("gear.count", player.OwnedGear.Count);
    for (int i = 0; i < player.OwnedGear.Count; i++) S("gear." + i, player.OwnedGear[i]);

    // ── Toolbar ──
    for (int i = 0; i < 8; i++) { S("toolbar." + i + ".item", NN(toolbarSlots[i])); S("toolbar." + i + ".count", toolbarCounts[i]); }

    // ── Backpack ──
    S("backpack.count", backpack.Count);
    int bi = 0;
    foreach (var kv in backpack) { S("backpack." + bi + ".key", kv.Key); S("backpack." + bi + ".val", kv.Value); bi++; }

    // ── Houses ──
    S("houses.count", ownedHousePlots.Count);
    for (int i = 0; i < ownedHousePlots.Count; i++)
    {
        S("house." + i + ".x", ownedHousePlots[i].x);
        S("house." + i + ".y", ownedHousePlots[i].y);
        var hd = i < houseDataList.Count ? houseDataList[i] : new HouseData(0, 0);
        S("house." + i + ".wall", hd.WallColor);
        S("house." + i + ".floor", hd.FloorColor);
        S("house." + i + ".furnCount", hd.Furniture.Count);
        for (int j = 0; j < hd.Furniture.Count; j++)
        {
            var f = hd.Furniture[j];
            S("house." + i + ".furn." + j, $"{f.Type}|{f.RoomX}|{f.RoomY}|{f.Cost}");
        }
    }

    // ── Pets ──
    S("eggs.count", ownedEggs.Count);
    for (int i = 0; i < ownedEggs.Count; i++) S("egg." + i, ownedEggs[i]);
    S("incubatingEgg", NN(incubatingEgg));
    SF("incubationProgress", incubationProgress);
    S("activePet.type", activePet != null ? activePet.Type : "empty");
    SF("activePet.x", activePet != null ? activePet.Position.X : 0f);
    SF("activePet.y", activePet != null ? activePet.Position.Y : 0f);
    S("pendingPet.type", pendingPet != null ? pendingPet.Type : "empty");
    SF("pendingPet.x", pendingPet != null ? pendingPet.Position.X : 0f);
    SF("pendingPet.y", pendingPet != null ? pendingPet.Position.Y : 0f);
    S("storedPets.count", storedPets.Count);
    for (int i = 0; i < storedPets.Count; i++) S("storedPet." + i, storedPets[i]);

    System.IO.File.WriteAllLines(savePath, d);
    ShowNotification("Game Saved!");
}

static void LoadGame()
{
    if (!System.IO.File.Exists(savePath)) return;
    string[] lines = System.IO.File.ReadAllLines(savePath);

    var map = new Dictionary<string, string>();
    foreach (var line in lines)
    {
        int eq = line.IndexOf('=');
        if (eq <= 0) continue;
        map[line.Substring(0, eq)] = line.Substring(eq + 1);
    }
    if (map.Count == 0) return;

    string GS(string k, string def = "") => map.TryGetValue(k, out var v) ? v : def;
    int GI(string k, int def = 0) => map.TryGetValue(k, out var v) && int.TryParse(v, out var r) ? r : def;
    float GF(string k, float def = 0f) => map.TryGetValue(k, out var v) && float.TryParse(v, System.Globalization.NumberStyles.Float, System.Globalization.CultureInfo.InvariantCulture, out var r) ? r : def;
    bool GB(string k, bool def = false) => map.TryGetValue(k, out var v) ? v == "1" : def;
    string GN(string k) { var v = GS(k, "empty"); return v == "empty" ? null : v; }

    // ── Position & core ──
    player.Position = new Vector2(GF("pos.x"), GF("pos.y"));
    player.Money = GI("money"); player.BankBalance = GI("bank");

    // ── Resources ──
    player.Logs = GI("logs"); player.BirchLogs = GI("birchLogs"); player.OakLogs = GI("oakLogs");
    player.PineLogs = GI("pineLogs"); player.ArcticLogs = GI("arcticLogs"); player.DeadWood = GI("deadWood");
    player.Fish = GI("fish"); player.Bones = GI("bones"); player.Fur = GI("fur");
    player.Stingers = GI("stingers"); player.BearPelts = GI("bearPelts");

    // ── Skills ──
    player.WoodcuttingLevel = GI("woodcutLv", 1); player.WoodcuttingXP = GI("woodcutXp");
    player.FishingLevel = GI("fishLv", 1); player.FishingXP = GI("fishXp");
    player.CombatLevel = GI("combatLv", 1); player.CombatXP = GI("combatXp");
    player.OneHandMeleeLevel = GI("oneHandLv", 1); player.OneHandMeleeXP = GI("oneHandXp");
    player.TwoHandMeleeLevel = GI("twoHandLv", 1); player.TwoHandMeleeXP = GI("twoHandXp");
    player.StrengthLevel = GI("strengthLv", 1); player.StrengthXP = GI("strengthXp");
    player.DrivingLevel = GI("drivingLv", 1); player.DrivingXP = GI("drivingXp");
    player.AthleticsLevel = GI("athleticsLv", 1); player.AthleticsXP = GI("athleticsXp");
    player.GamblingLevel = GI("gamblingLv", 1); player.GamblingXP = GI("gamblingXp");
    player.RidingLevel = GI("ridingLv", 1); player.RidingXP = GI("ridingXp");
    player.CyclingLevel = GI("cyclingLv", 1); player.CyclingXP = GI("cyclingXp");
    player.MiningLevel = GI("miningLv", 1); player.MiningXP = GI("miningXp");
    player.SwimmingLevel = GI("swimmingLv", 1); player.SwimmingXP = GI("swimmingXp");
    player.DivingLevel = GI("divingLv", 1); player.DivingXP = GI("divingXp");
    player.SportsLevel = GI("sportsLv", 1); player.SportsXP = GI("sportsXp");
    player.RangedLevel = GI("rangedLv", 1); player.RangedXP = GI("rangedXp");
    player.ElementalLevel = GI("elementalLv", 1); player.ElementalXP = GI("elementalXp");
    player.CookingLevel = GI("cookingLv", 1); player.CookingXP = GI("cookingXp");

    // ── Health & identity ──
    player.Health = GI("health", 100); player.MaxHealth = GI("maxHealth", 100);
    playerName = GS("name"); nameEntered = true;

    // ── Appearance ──
    player.ShirtColor = new Color((byte)GI("shirtR"), (byte)GI("shirtG"), (byte)GI("shirtB"), (byte)255);
    player.SkinColor  = new Color((byte)GI("skinR"), (byte)GI("skinG"), (byte)GI("skinB"), (byte)255);
    player.PantsColor = new Color((byte)GI("pantsR"), (byte)GI("pantsG"), (byte)GI("pantsB"), (byte)255);
    playerHairStyle = GS("hairStyle", "None");
    playerHairColor = new Color((byte)GI("hairR"), (byte)GI("hairG"), (byte)GI("hairB"), (byte)255);
    playerFacialHair = GS("facialHair", "None");
    playerFacialHairColor = new Color((byte)GI("facialR"), (byte)GI("facialG"), (byte)GI("facialB"), (byte)255);

    // ── Chest storage ──
    chestLogs = GI("chestLogs"); chestFish = GI("chestFish"); chestBones = GI("chestBones");
    chestFur = GI("chestFur"); chestStingers = GI("chestStingers"); chestBearPelts = GI("chestBearPelts");
    chestDogFangs = GI("chestDogFangs"); chestWolfClaws = GI("chestWolfClaws"); chestVenomSacs = GI("chestVenomSacs");
    chestCrabClaws = GI("chestCrabClaws"); chestBearClaws = GI("chestBearClaws"); chestCrabShells = GI("chestCrabShells");
    chestSharkFins = GI("chestSharkFins"); chestSharkTeeth = GI("chestSharkTeeth"); chestSnakeSkins = GI("chestSnakeSkins");
    chestSnakeFangs = GI("chestSnakeFangs"); chestCrocScales = GI("chestCrocScales"); chestCrocTeeth = GI("chestCrocTeeth");
    chestLizardScales = GI("chestLizardScales"); chestEmberStones = GI("chestEmberStones"); chestMagmaShards = GI("chestMagmaShards");
    chestLavaCores = GI("chestLavaCores"); chestFeathers = GI("chestFeathers"); chestEagleTalons = GI("chestEagleTalons");
    chestHorns = GI("chestHorns"); chestGoatHooves = GI("chestGoatHooves");

    // ── Player loot materials ──
    player.DogFangs = GI("dogFangs"); player.WolfClaws = GI("wolfClaws"); player.VenomSacs = GI("venomSacs");
    player.CrabClaws = GI("crabClaws"); player.BearClaws = GI("bearClaws"); player.CrabShells = GI("crabShells");
    player.SharkFins = GI("sharkFins"); player.SharkTeeth = GI("sharkTeeth"); player.SnakeSkins = GI("snakeSkins");
    player.SnakeFangs = GI("snakeFangs"); player.CrocScales = GI("crocScales"); player.CrocTeeth = GI("crocTeeth");
    player.LizardScales = GI("lizardScales"); player.EmberStones = GI("emberStones"); player.MagmaShards = GI("magmaShards");
    player.LavaCores = GI("lavaCores"); player.Feathers = GI("feathers"); player.EagleTalons = GI("eagleTalons");
    player.Horns = GI("horns"); player.GoatHooves = GI("goatHooves");

    // ── Quests ──
    quests[0].Progress = GI("quest0prog"); quests[0].Completed = GB("quest0done");
    quests[1].Progress = GI("quest1prog"); quests[1].Completed = GB("quest1done");
    quests[2].Progress = GI("quest2prog"); quests[2].Completed = GB("quest2done");

    // ── World / time ──
    totalPlayTime = GF("playtime");
    dayOfMonth = GI("dayOfMonth"); currentMonth = GI("currentMonth");
    timeOfDay = GF("timeOfDay"); dayOfWeek = GI("dayOfWeek"); player.Tickets = GI("tickets");

    // ── Tool pickup flags ──
    axePickedUp = GB("axePicked"); pickaxePickedUp = GB("pickaxePicked");
    fishingRodPickedUp = GB("rodPicked"); fishingNetPickedUp = GB("netPicked");
    torchPickedUp = GB("torchPicked"); player.HasAxe = GB("hasAxe");

    // ── Weapons / ammo ──
    player.Arrows = GI("arrows"); player.Bolts = GI("bolts");
    player.HasBow = GB("hasBow"); player.HasCrossbow = GB("hasCrossbow");
    equipped1H = GN("equipped1H"); equipped2H = GN("equipped2H"); equippedAmmo = GN("equippedAmmo");
    if (equipped2H != null) armorWeapon = equipped2H;
    else if (equipped1H != null) armorWeapon = equipped1H;

    // ── Elemental / staff ──
    player.ArcaneEssence = GI("arcaneEssence"); player.EquippedStaff = GN("equippedStaff");

    // ── Armor ──
    armorHelmet = GN("armorHelmet"); armorBody = GN("armorBody"); armorLegs = GN("armorLegs");
    armorBoots = GN("armorBoots"); armorGloves = GN("armorGloves"); armorCape = GN("armorCape");
    armorShield = GN("armorShield");

    // ── Licences ──
    hasTheoryD = GB("theoryD"); hasTheoryC = GB("theoryC"); hasTheoryB = GB("theoryB");
    hasTheoryA = GB("theoryA"); hasTheoryS = GB("theoryS");
    hasPracticalD = GB("pracD"); hasPracticalC = GB("pracC"); hasPracticalB = GB("pracB");
    hasPracticalA = GB("pracA"); hasPracticalS = GB("pracS");

    // ── Tutorial state ──
    tutorialCompleted = GB("tutDone"); tutorialActive = GB("tutActive"); tutorialStep = GI("tutStep");
    for (int i = 0; i < tutorialTasks.Count; i++) tutorialTasks[i].Done = GB("tutTask." + i);
    tutorialMessage = ""; tutorialMessageTimer = 0f;
    SnapshotTutorialMarks();

    // Stats
    dungeonsCleared = GI("dungeonsCleared");
    timesCheated = GI("timesCheated");
    sportPlayCounts.Clear();
    int spc = GI("sportCounts.count");
    for (int i = 0; i < spc; i++) { var k = GS("sportCount." + i + ".k", ""); if (k != "") sportPlayCounts[k] = GI("sportCount." + i + ".v"); }
    minigamePlayCounts.Clear();
    int mpc = GI("miniCounts.count");
    for (int i = 0; i < mpc; i++) { var k = GS("miniCount." + i + ".k", ""); if (k != "") minigamePlayCounts[k] = GI("miniCount." + i + ".v"); }

    // ── Cards ──
    player.PlayingCardsLevel = GI("cardsLv", 1); player.PlayingCardsXP = GI("cardsXp");
    player.EuchreRating = GI("euchreRating"); player.FiveHundredRating = GI("fiveHundredRating");
    player.SequenceRating = GI("sequenceRating"); player.EuchreWins = GI("euchreWins");
    player.FiveHundredWins = GI("fiveHundredWins"); player.SequenceWins = GI("sequenceWins");

    // ── Gear ──
    player.OwnedGear.Clear();
    int gearCount = GI("gear.count");
    for (int i = 0; i < gearCount; i++) { var g = GS("gear." + i, "empty"); if (g != "empty") player.OwnedGear.Add(g); }

    // ── Toolbar ──
    for (int i = 0; i < 8; i++)
    {
        toolbarSlots[i] = GN("toolbar." + i + ".item");
        toolbarCounts[i] = GI("toolbar." + i + ".count");
    }

    // ── Backpack ──
    backpack.Clear();
    int bpCount = GI("backpack.count");
    for (int i = 0; i < bpCount; i++)
    {
        string k = GS("backpack." + i + ".key", "");
        if (k != "") backpack[k] = GI("backpack." + i + ".val");
    }

    // ── Houses ──
    ownedHousePlots.Clear();
    houseDataList.Clear();
    int houseCount = GI("houses.count");
    for (int i = 0; i < houseCount; i++)
    {
        int hx = GI("house." + i + ".x");
        int hy = GI("house." + i + ".y");
        var hd = new HouseData(hx, hy)
        {
            WallColor = GS("house." + i + ".wall", "Beige"),
            FloorColor = GS("house." + i + ".floor", "Oak")
        };
        int furnCount = GI("house." + i + ".furnCount");
        for (int j = 0; j < furnCount; j++)
        {
            string[] fp = GS("house." + i + ".furn." + j, "").Split('|');
            if (fp.Length >= 4 &&
                int.TryParse(fp[1], out int rx) &&
                int.TryParse(fp[2], out int ry) &&
                int.TryParse(fp[3], out int cost))
            {
                hd.Furniture.Add(new HouseFurniture(fp[0], rx, ry, cost, Color.Gray));
            }
        }
        ownedHousePlots.Add((hx, hy));
        houseDataList.Add(hd);
    }
    for (int i = 0; i < ownedHousePlots.Count; i++) { activeHousePlotIndex = i; SpawnPlayerHouse(i); }
    activeHousePlotIndex = Math.Max(0, ownedHousePlots.Count - 1);

    // ── Pets ──
    ownedEggs.Clear();
    int eggCount = GI("eggs.count");
    for (int i = 0; i < eggCount; i++) { var e = GS("egg." + i, "empty"); if (e != "empty") ownedEggs.Add(e); }
    incubatingEgg = GN("incubatingEgg");
    incubationProgress = GF("incubationProgress");
    incubationNeeded = 1f / daySpeed;
    storedPets.Clear();
    int spCount = GI("storedPets.count");
    for (int i = 0; i < spCount; i++) { var sp = GS("storedPet." + i, "empty"); if (sp != "empty") storedPets.Add(sp); }

    string apType = GS("activePet.type", "empty");
    activePet = apType == "empty" ? null
        : new Pet(new Vector2(GF("activePet.x"), GF("activePet.y")), apType, PetColorFor(apType + " Egg"));

    string ppType = GS("pendingPet.type", "empty");
    pendingPet = ppType == "empty" ? null
        : new Pet(new Vector2(GF("pendingPet.x"), GF("pendingPet.y")), ppType, PetColorFor(ppType + " Egg"));
}  

static void DrawIncubatorMenu()
{
    if (!incubatorMenuOpen) return;

    int pw = 460, ph = 320;
    int px = ScreenWidth / 2 - pw / 2, py = ScreenHeight / 2 - ph / 2;
    Raylib.DrawRectangle(0, 0, ScreenWidth, ScreenHeight, new Color((byte)0,(byte)0,(byte)0,(byte)120));
    Raylib.DrawRectangle(px, py, pw, ph, new Color((byte)24,(byte)24,(byte)34,(byte)245));
    Raylib.DrawRectangleLines(px, py, pw, ph, Color.Gold);
    Raylib.DrawText("INCUBATOR", px + 20, py + 18, 26, Color.Gold);

    Raylib.DrawText("[Q] Close", px + pw - 110, py + 22, 16, Color.LightGray);

    if (Raylib.IsKeyPressed(KeyboardKey.Q))
    {
        incubatorMenuOpen = false;
        return;
    }

    if (incubatingEgg != null)
    {
        // currently incubating: show egg + progress
        DrawEggIcon(incubatingEgg, px + 90, py + 150, 70);
        Raylib.DrawText(incubatingEgg, px + 150, py + 90, 22, Color.White);

        float prog = incubationNeeded > 0 ? incubationProgress / incubationNeeded : 0f;
        prog = Math.Clamp(prog, 0f, 1f);
        int barX = px + 150, barY = py + 140, barW = 260;
        Raylib.DrawRectangle(barX, barY, barW, 22, new Color((byte)40,(byte)40,(byte)40,(byte)255));
        Raylib.DrawRectangle(barX, barY, (int)(barW * prog), 22, new Color((byte)255,(byte)160,(byte)40,(byte)255));
        Raylib.DrawRectangleLines(barX, barY, barW, 22, Color.White);
        Raylib.DrawText($"{(int)(prog * 100)}%  —  hatches after one full day",
            barX, barY + 30, 16, Color.LightGray);
    }
    else
    {
        Raylib.DrawText("Select an egg to incubate:", px + 20, py + 60, 18, Color.LightGray);

        // list eggs found in the toolbar
        int row = 0;
        for (int s = 0; s < toolbarSlots.Length; s++)
        {
            if (toolbarSlots[s] == null || !IsEgg(toolbarSlots[s])) continue;
            string egg = toolbarSlots[s];
            int ry = py + 95 + row * 56;
            Rectangle r = new Rectangle(px + 20, ry, pw - 40, 48);
            bool hov = Raylib.CheckCollisionPointRec(Raylib.GetMousePosition(), r);
            Raylib.DrawRectangleRec(r, hov ? new Color((byte)60,(byte)60,(byte)80,(byte)255)
                                           : new Color((byte)40,(byte)40,(byte)55,(byte)255));
            Raylib.DrawRectangleLinesEx(r, 2, hov ? Color.Gold : Color.DarkGray);
            DrawEggIcon(egg, px + 48, ry + 24, 34);
            Raylib.DrawText($"{egg}  x{toolbarCounts[s]}", px + 78, ry + 14, 20, Color.White);
            Raylib.DrawText("[Incubate]", px + pw - 130, ry + 16, 18, Color.Gold);

            if (hov && Raylib.IsMouseButtonPressed(MouseButton.Left))
            {
                StartIncubation(egg);
                toolbarCounts[s]--;
                if (toolbarCounts[s] <= 0) toolbarSlots[s] = null;
            }
            row++;
        }
        if (row == 0)
            Raylib.DrawText("No eggs. Defeat a world boss for a chance at one.",
                px + 20, py + 110, 18, Color.Gray);
    }
}

