static void DropToGround(string item)
{
    RemoveOneItem(item);
    droppedItems.Add(new DroppedItem(item, 1, player.Center + new Vector2(0, 20)));
    ShowNotification($"Dropped {item}");
}
static void UpdateDroppedItems(float dt)
{
    for (int i = droppedItems.Count - 1; i >= 0; i--)
    {
        var d = droppedItems[i];
        d.Lifetime -= dt;
        if (d.Lifetime <= 0)
        {
            droppedItems.RemoveAt(i);
            continue;
        }

        // press F near it to collect
        if (Vector2.Distance(player.Center, d.Position) < 50 && Raylib.IsKeyPressed(KeyboardKey.F))
        {
            GiveItemBack(d.Name, d.Count);
            ShowNotification($"Picked up {d.Name}");
            droppedItems.RemoveAt(i);
        }
    }
}

static void SpawnSplat(Vector2 center, Color baseColor, int count = 8)
{
    for (int i = 0; i < count; i++)
    {
        float ang = Raylib.GetRandomValue(0, 360) * (MathF.PI / 180f);
        float spd = Raylib.GetRandomValue(40, 160);
        splats.Add(new Splat {
            Position  = center,
            Velocity  = new Vector2(MathF.Cos(ang), MathF.Sin(ang)) * spd,
            Timer     = 0.45f,
            MaxTimer  = 0.45f,
            Radius    = Raylib.GetRandomValue(2, 5),
            SplatColor = baseColor
        });
    }
}

static void UpdateSplats(float dt)
{
    for (int i = splats.Count - 1; i >= 0; i--)
    {
        var s = splats[i];
        s.Timer -= dt;
        if (s.Timer <= 0f) { splats.RemoveAt(i); continue; }
        s.Position += s.Velocity * dt;
        s.Velocity *= 0.88f;            // drag, so they fan out then settle
        splats[i] = s;
    }
}

static void DrawSplats()
{
    foreach (var s in splats)
    {
        float a = s.Timer / s.MaxTimer;          // 1 → 0
        Raylib.DrawCircleV(s.Position, s.Radius * a,
            new Color(s.SplatColor.R, s.SplatColor.G, s.SplatColor.B, (byte)(220 * a)));
    }
}

static void SpawnDeathFx(Vector2 center, Color tint, string type)
{
    deathFx.Add(new DeathFx {
        Position = center, Type = type,
        Timer = 0.6f, MaxTimer = 0.6f, TintColor = tint
    });
    // burst of corpse particles, reusing the splat system
    SpawnSplat(center, tint, 18);

    // fire/magma types throw extra orange embers
    if (type == "Fire Lizard" || type == "Magma Beetle")
        SpawnSplat(center, new Color((byte)240,(byte)120,(byte)20,(byte)255), 12);

    
}

static void UpdateDeathFx(float dt)
{
    for (int i = deathFx.Count - 1; i >= 0; i--)
    {
        var d = deathFx[i];
        d.Timer -= dt;
        if (d.Timer <= 0f) { deathFx.RemoveAt(i); continue; }
        deathFx[i] = d;
    }
}

static void DrawDeathFx()
{
    foreach (var d in deathFx)
    {
        float p = 1f - (d.Timer / d.MaxTimer);   // 0 → 1 progress
        float a = d.Timer / d.MaxTimer;           // 1 → 0 fade

        // expanding shockwave ring
        float ringR = 6f + p * 38f;
        Raylib.DrawCircleLines((int)d.Position.X, (int)d.Position.Y, ringR,
            new Color(d.TintColor.R, d.TintColor.G, d.TintColor.B, (byte)(200 * a)));

        // fading, rising silhouette
        int sy = (int)(d.Position.Y - p * 18f);
        Raylib.DrawCircle((int)d.Position.X, sy, (int)(14 * a),
            new Color(d.TintColor.R, d.TintColor.G, d.TintColor.B, (byte)(140 * a)));
    }
}

static void GiveItemBack(string item, int count)
{
    switch (item)
    {
        case "Money": player.Money += count; break;
        case "Dog Fangs": player.DogFangs += count; break;
        case "Wolf Claw": player.WolfClaws += count; break;
        case "Venom Sac": player.VenomSacs += count; break;
        case "Crab Claw": player.CrabClaws += count; break;
        case "Bear Claw": player.BearClaws += count; break;
        case "Crab Shell": player.CrabShells += count; break;
        case "Shark Fin": player.SharkFins += count; break;
        case "Shark Tooth": player.SharkTeeth += count; break;
        case "Snake Skin": player.SnakeSkins += count; break;
        case "Snake Fang": player.SnakeFangs += count; break;
        case "Croc Scale": player.CrocScales += count; break;
        case "Croc Tooth": player.CrocTeeth += count; break;
        case "Lizard Scale": player.LizardScales += count; break;
        case "Ember Stone": player.EmberStones += count; break;
        case "Magma Shard": player.MagmaShards += count; break;
        case "Lava Core": player.LavaCores += count; break;
        case "Feather": player.Feathers += count; break;
        case "Eagle Talon": player.EagleTalons += count; break;
        case "Horn": player.Horns += count; break;
        case "Goat Hoof": player.GoatHooves += count; break;
        // armor/weapons go back to owned gear; everything else to the backpack
        default:
            if (GetItemSlot(item) != null) AcquireGear(item);
            else BackpackAdd(item, count);
            break;
    }
}
static void DrawDropConfirm()
{
    if (!dropConfirmOpen) return;

    Raylib.DrawRectangle(0, 0, ScreenWidth, ScreenHeight, new Color((byte)0,(byte)0,(byte)0,(byte)150));

    int w = 440, h = 200;
    int px = ScreenWidth / 2 - w / 2;
    int py = ScreenHeight / 2 - h / 2;
    Raylib.DrawRectangle(px, py, w, h, new Color((byte)20,(byte)20,(byte)30,(byte)255));
    Raylib.DrawRectangleLines(px, py, w, h, Color.Red);

    string title = "Drop this item?";
    int tw = Raylib.MeasureText(title, 28);
    Raylib.DrawText(title, ScreenWidth / 2 - tw / 2, py + 20, 28, Color.Red);

    string warn = $"{dropConfirmItem} is valuable. Drop it on the ground?";
    int ww = Raylib.MeasureText(warn, 18);
    Raylib.DrawText(warn, ScreenWidth / 2 - ww / 2, py + 64, 18, Color.LightGray);

    Vector2 mouse = Raylib.GetMousePosition();
    Rectangle yesBtn = new Rectangle(ScreenWidth / 2 - 160, py + 120, 140, 44);
    Rectangle noBtn  = new Rectangle(ScreenWidth / 2 + 20,  py + 120, 140, 44);
    bool hYes = Raylib.CheckCollisionPointRec(mouse, yesBtn);
    bool hNo  = Raylib.CheckCollisionPointRec(mouse, noBtn);

    Raylib.DrawRectangleRec(yesBtn, hYes ? new Color((byte)160,(byte)30,(byte)30,(byte)255) : new Color((byte)80,(byte)20,(byte)20,(byte)255));
    Raylib.DrawRectangleLinesEx(yesBtn, 2, hYes ? Color.Red : Color.DarkGray);
    Raylib.DrawText("Yes, Drop", (int)yesBtn.X + 22, (int)yesBtn.Y + 12, 20, Color.White);

    Raylib.DrawRectangleRec(noBtn, hNo ? new Color((byte)30,(byte)100,(byte)30,(byte)255) : new Color((byte)20,(byte)60,(byte)20,(byte)255));
    Raylib.DrawRectangleLinesEx(noBtn, 2, hNo ? Color.Green : Color.DarkGray);
    Raylib.DrawText("Cancel", (int)noBtn.X + 36, (int)noBtn.Y + 12, 20, Color.White);

    if (Raylib.IsMouseButtonPressed(MouseButton.Left))
    {
        if (hYes)
        {
            dropConfirmOpen = false;
            dropQtyItem = dropConfirmItem;
            dropQtyAvailable = dropConfirmItem == "Money" ? player.Money : GetItemCount(dropConfirmItem);
            dropQtyOpen = true;
            dropConfirmItem = "";
        }
    }
}
 static void UpdateWeather(float dt)
{
    rainTimer += dt;

    float interval = isRaining ? rainDuration : rainInterval;

    if (rainTimer >= interval)
    {
        rainTimer = 0f;
        isRaining = !isRaining;

        if (isRaining)
        {
            // just started raining — pick how long this rain lasts
            rainDuration = Raylib.GetRandomValue(15, 45);   // seconds of rain
            raindrops.Clear();
            for (int i = 0; i < 200; i++)
            {
                raindrops.Add(new Vector2(
                    Raylib.GetRandomValue(0, ScreenWidth),
                    Raylib.GetRandomValue(0, ScreenHeight)
                ));
            }
            musicBeforeRain = currentMusic;
            SwitchMusic(musicRain);
        }
        else
        {
            // just stopped raining — pick how long until the next rain
            rainInterval = Raylib.GetRandomValue(150, 1000);  // seconds of dry weather
            lastZoneMusic = default;
            CheckZoneMusic();
        }
    }

    if (isRaining)
    {
        for (int i = 0; i < raindrops.Count; i++)
        {
            Vector2 drop = raindrops[i];
            drop.Y += 400f * dt;
            drop.X += 50f * dt;
            if (drop.Y > ScreenHeight) drop.Y = 0;
            if (drop.X > ScreenWidth) drop.X = 0;
            raindrops[i] = drop;
        }
    }
}
        static void DrawWeather()
{
    if (!isRaining) return;

    Raylib.DrawRectangle(0, 0, ScreenWidth, ScreenHeight, new Color((byte)0, (byte)20, (byte)40, (byte)60));

    foreach (Vector2 drop in raindrops)
    {
        Raylib.DrawLine(
            (int)drop.X, (int)drop.Y,
            (int)drop.X + 4, (int)drop.Y + 12,
            new Color((byte)150, (byte)200, (byte)255, (byte)180)
        );
    }
}
        static void UpdateQuests()
{
    foreach (Quest quest in quests)
    {
        if (quest.Completed) continue;

        if (quest.Title == "Lumberjack")
            quest.Progress = player.Logs;

        if (quest.Title == "Fisher")
            quest.Progress = player.Fish;

        if (quest.Title == "Big Money")
            quest.Progress = player.Money;

        if (quest.Progress >= quest.Target)
        {
            quest.Completed = true;
            quest.Progress = quest.Target;
            player.Money += quest.Reward;
            ShowLevelUp($"Quest Complete: {quest.Title}! +${quest.Reward}", 0);
        }
    }
}
            static void DrawQuestsUI()
{
    // QUESTS button
    Rectangle questsBtn = new Rectangle(ScreenWidth - 320, ScreenHeight - 60, 140, 40);
