    static void DrawSkillDetailMenu()
    {
        if (skillDetailOpen == "") return;

        int mx = ScreenWidth / 2 - 300;
        int my = ScreenHeight / 2 - 260;
        int mw = 600;
        int mh = 520;

        Raylib.DrawRectangle(0, 0, ScreenWidth, ScreenHeight, new Color((byte)0,(byte)0,(byte)0,(byte)110));
        Raylib.DrawRectangle(mx, my, mw, mh, new Color((byte)10,(byte)14,(byte)22,(byte)248));
        Raylib.DrawRectangleLines(mx, my, mw, mh, Color.Gold);
        Raylib.DrawText("Click outside to close", mx + mw - 172, my + 8, 13, Color.DarkGray);

        if (skillDetailOpen == "wc")
        {
            Color green = new Color((byte)100,(byte)210,(byte)80,(byte)255);
            Raylib.DrawText("WOODCUTTING", mx + 20, my + 14, 26, green);

            int wcReq = player.WoodcuttingLevel * player.WoodcuttingLevel * 50;
            Raylib.DrawText($"Level {player.WoodcuttingLevel}   XP: {player.WoodcuttingXP} / {wcReq}",
                mx + 20, my + 48, 17, Color.LightGray);

            int pbW = mw - 40;
            float wcP = Math.Clamp((float)player.WoodcuttingXP / wcReq, 0f, 1f);
            Raylib.DrawRectangle(mx + 20, my + 72, pbW, 10, new Color((byte)30,(byte)30,(byte)30,(byte)255));
            Raylib.DrawRectangle(mx + 20, my + 72, (int)(pbW * wcP), 10, green);
            Raylib.DrawRectangleLines(mx + 20, my + 72, pbW, 10, Color.DarkGray);

            Raylib.DrawLine(mx + 10, my + 94, mx + mw - 10, my + 94, Color.DarkGray);

            Raylib.DrawText("Tree",       mx + 20,  my + 102, 15, Color.Gray);
            Raylib.DrawText("Lv Req",     mx + 230, my + 102, 15, Color.Gray);
            Raylib.DrawText("Log Type",   mx + 320, my + 102, 15, Color.Gray);
            Raylib.DrawText("Status",     mx + 470, my + 102, 15, Color.Gray);
            Raylib.DrawLine(mx + 10, my + 120, mx + mw - 10, my + 120, new Color((byte)50,(byte)50,(byte)50,(byte)255));

            (string tree, int lvl, string log, Color col)[] trees =
            {
                ("Dead Wood",   1,  "Dead Wood",   new Color((byte)120,(byte)90,(byte)60,(byte)255)),
                ("Normal Tree", 1,  "Logs",        new Color((byte)160,(byte)130,(byte)80,(byte)255)),
                ("Birch Tree",  3,  "Birch Logs",  new Color((byte)200,(byte)200,(byte)170,(byte)255)),
                ("Oak Tree",    5,  "Oak Logs",    new Color((byte)160,(byte)110,(byte)50,(byte)255)),
                ("Pine Tree",   10, "Pine Logs",   new Color((byte)80,(byte)150,(byte)80,(byte)255)),
                ("Arctic Tree", 15, "Arctic Logs", new Color((byte)180,(byte)220,(byte)240,(byte)255)),
            };

            for (int i = 0; i < trees.Length; i++)
            {
                var (tName, tLvl, tLog, tCol) = trees[i];
                int ry = my + 128 + i * 38;
                bool unlocked = player.WoodcuttingLevel >= tLvl;

                if (unlocked)
                    Raylib.DrawRectangle(mx + 10, ry - 2, mw - 20, 34, new Color((byte)20,(byte)40,(byte)20,(byte)140));

                Color nameCol = unlocked ? tCol : new Color((byte)70,(byte)70,(byte)70,(byte)255);
                Raylib.DrawText(tName, mx + 20, ry + 6, 17, nameCol);
                Raylib.DrawText($"Lv {tLvl}", mx + 230, ry + 6, 17, unlocked ? Color.White : Color.DarkGray);
                Raylib.DrawText(tLog, mx + 320, ry + 6, 15, unlocked ? Color.LightGray : Color.DarkGray);

                if (unlocked)
                    Raylib.DrawText("UNLOCKED", mx + 470, ry + 6, 15, new Color((byte)80,(byte)220,(byte)80,(byte)255));
                else
                    Raylib.DrawText($"Need Lv {tLvl}", mx + 470, ry + 6, 14, new Color((byte)160,(byte)60,(byte)60,(byte)255));
            }
        }
        else if (skillDetailOpen == "cards")
        {
            Raylib.DrawText("PLAYING CARDS", mx + 20, my + 14, 26, Color.Gold);

            int cReq = player.PlayingCardsLevel * player.PlayingCardsLevel * 40;
            Raylib.DrawText($"Level {player.PlayingCardsLevel}   XP: {player.PlayingCardsXP} / {cReq}",
                mx + 20, my + 48, 17, Color.LightGray);

            int pbW = mw - 40;
            float cP = Math.Clamp((float)player.PlayingCardsXP / cReq, 0f, 1f);
            Raylib.DrawRectangle(mx + 20, my + 72, pbW, 10, new Color((byte)30,(byte)30,(byte)30,(byte)255));
            Raylib.DrawRectangle(mx + 20, my + 72, (int)(pbW * cP), 10, Color.Gold);
            Raylib.DrawRectangleLines(mx + 20, my + 72, pbW, 10, Color.DarkGray);

            Raylib.DrawLine(mx + 10, my + 94, mx + mw - 10, my + 94, Color.DarkGray);

            // Ratings
            Raylib.DrawText("YOUR RATINGS", mx + 20, my + 102, 18, Color.White);

            (string game, int rating)[] games =
            {
                ("Euchre",   player.EuchreRating),
                ("500",      player.FiveHundredRating),
                ("Sequence", player.SequenceRating),
            };

            for (int i = 0; i < games.Length; i++)
            {
                var (gName, gRating) = games[i];
                int ry = my + 130 + i * 62;

                Raylib.DrawRectangle(mx + 10, ry, mw - 20, 54, new Color((byte)15,(byte)15,(byte)30,(byte)200));
                Raylib.DrawRectangleLines(mx + 10, ry, mw - 20, 54, new Color((byte)55,(byte)55,(byte)55,(byte)255));

                string rank = gRating >= 1800 ? "Grand Master" :
                              gRating >= 1500 ? "Master" :
                              gRating >= 1200 ? "Expert" :
                              gRating >= 800  ? "Intermediate" : "Beginner";

                Color rankCol = gRating >= 1800 ? Color.Gold :
                                gRating >= 1500 ? new Color((byte)180,(byte)100,(byte)255,(byte)255) :
                                gRating >= 1200 ? Color.SkyBlue :
                                gRating >= 800  ? Color.LightGray : Color.DarkGray;

                Raylib.DrawText(gName, mx + 20, ry + 6, 18, Color.White);
                Raylib.DrawText($"Rating: {gRating}", mx + 20, ry + 30, 14, Color.LightGray);
                Raylib.DrawText(rank, mx + 290, ry + 16, 20, rankCol);

                float rP = Math.Clamp(gRating / 2000f, 0f, 1f);
                Raylib.DrawRectangle(mx + 430, ry + 20, 140, 8, new Color((byte)30,(byte)30,(byte)30,(byte)255));
                Raylib.DrawRectangle(mx + 430, ry + 20, (int)(140 * rP), 8, rankCol);
            }

            Raylib.DrawLine(mx + 10, my + 322, mx + mw - 10, my + 322, Color.DarkGray);
            Raylib.DrawText("LEVEL PERKS", mx + 20, my + 330, 18, Color.White);

            (int lvl, string perk)[] perks =
            {
                (1,  "Access to Euchre"),
                (10, "Access to 500"),
                (20, "Access to Sequence"),
                (30, "Improved AI tells in bidding"),
                (50, "Bonus XP on wins"),
                (75, "Legendary Card Player title"),
            };

            for (int i = 0; i < perks.Length; i++)
            {
                var (pLvl, pText) = perks[i];
                bool has = player.PlayingCardsLevel >= pLvl;
                Color pc = has ? new Color((byte)80,(byte)220,(byte)80,(byte)255) : new Color((byte)90,(byte)90,(byte)90,(byte)255);
                string prefix = has ? "✓" : $"Lv {pLvl}";
                Raylib.DrawText($"{prefix}  {pText}", mx + 20, my + 356 + i * 22, 15, pc);
            }
        }
    }

    static void DrawMinimap()
{
    Raylib.DrawRectangle(minimapX, minimapY, minimapSize, minimapSize, new Color((byte)0,(byte)0,(byte)0,(byte)180));
    Raylib.BeginScissorMode(minimapX, minimapY, minimapSize, minimapSize);

    int cx = minimapX + minimapSize / 2;
    int cy = minimapY + minimapSize / 2;

    // 1. Base grasslands
    Raylib.DrawRectangle(minimapX, minimapY, minimapSize, minimapSize, new Color((byte)140, (byte)195, (byte)80, (byte)255));;

    // 2. Forest top band (Y < -12000)
    int forestTopY = cy + (int)((-12000 - player.Position.Y) * minimapScale);
    Raylib.DrawRectangle(minimapX, minimapY, minimapSize, Math.Clamp(forestTopY - minimapY, 0, minimapSize), new Color((byte)40,(byte)100,(byte)40,(byte)220));

    // 3. Forest bottom band (Y > 12000)
    int forestBotY = cy + (int)((12000 - player.Position.Y) * minimapScale);
    Raylib.DrawRectangle(minimapX, forestBotY, minimapSize, Math.Clamp(minimapY + minimapSize - forestBotY, 0, minimapSize), new Color((byte)40,(byte)100,(byte)40,(byte)220));

    // 4. Swamp (X -55000 to -30000, middle strip)
    int swampL = cx + (int)((-55000 - player.Position.X) * minimapScale);
    int swampR = cx + (int)((-30000 - player.Position.X) * minimapScale);
    int swampT = cy + (int)((-12000 - player.Position.Y) * minimapScale);
    int swampB = cy + (int)((12000  - player.Position.Y) * minimapScale);
    int swX  = Math.Clamp(swampL, minimapX, minimapX + minimapSize);
    int swX2 = Math.Clamp(swampR, minimapX, minimapX + minimapSize);
    int swY  = Math.Clamp(swampT, minimapY, minimapY + minimapSize);
    int swY2 = Math.Clamp(swampB, minimapY, minimapY + minimapSize);
    Raylib.DrawRectangle(swX, swY, swX2 - swX, swY2 - swY,
        new Color((byte)55,(byte)75,(byte)35,(byte)220));

    // 5. Snow (X -30000 to -10000, middle strip)
    int snowL = cx + (int)((-60000 - player.Position.X) * minimapScale);
    int snowR = cx + (int)((-30000 - player.Position.X) * minimapScale);
    int snowT = cy + (int)((-12000 - player.Position.Y) * minimapScale);
    int snowB = cy + (int)((12000  - player.Position.Y) * minimapScale);
    int snX  = Math.Clamp(snowL, minimapX, minimapX + minimapSize);
    int snX2 = Math.Clamp(snowR, minimapX, minimapX + minimapSize);
    int snY  = Math.Clamp(snowT, minimapY, minimapY + minimapSize);
    int snY2 = Math.Clamp(snowB, minimapY, minimapY + minimapSize);
    Raylib.DrawRectangle(snX, snY, snX2 - snX, snY2 - snY,
        new Color((byte)220,(byte)235,(byte)255,(byte)220));

    // 6. Desert (X 8000 to 22000, middle strip)
    int desL = cx + (int)((8000  - player.Position.X) * minimapScale);
    int desR = cx + (int)((22000 - player.Position.X) * minimapScale);
    int desT = cy + (int)((-12000 - player.Position.Y) * minimapScale);
    int desB = cy + (int)((12000  - player.Position.Y) * minimapScale);
    int dX  = Math.Clamp(desL, minimapX, minimapX + minimapSize);
    int dX2 = Math.Clamp(desR, minimapX, minimapX + minimapSize);
    int dY  = Math.Clamp(desT, minimapY, minimapY + minimapSize);
    int dY2 = Math.Clamp(desB, minimapY, minimapY + minimapSize);
    Raylib.DrawRectangle(dX, dY, dX2 - dX, dY2 - dY,
        new Color((byte)210,(byte)180,(byte)100,(byte)220));

    // 7. Beach (X 22000 to 28000, full height)
    int beachX = cx + (int)((22000 - player.Position.X) * minimapScale);
    int oceanX = cx + (int)((28000 - player.Position.X) * minimapScale);
    Raylib.DrawRectangle(Math.Clamp(beachX, minimapX, minimapX + minimapSize), minimapY,
        Math.Clamp(oceanX - beachX, 0, minimapSize), minimapSize,
        new Color((byte)240,(byte)220,(byte)150,(byte)220));

    // 8. Ocean (X 28000+, full height)
    Raylib.DrawRectangle(Math.Clamp(oceanX, minimapX, minimapX + minimapSize), minimapY,
        Math.Clamp(minimapX + minimapSize - oceanX, 0, minimapSize), minimapSize,
        new Color((byte)30,(byte)100,(byte)180,(byte)220));

    // 9. Volcano (X 22000+, Y above -12000)
    int volL = cx + (int)((22000 - player.Position.X) * minimapScale);
    int volB = cy + (int)((-12000 - player.Position.Y) * minimapScale);
    int vX = Math.Clamp(volL, minimapX, minimapX + minimapSize);
    Raylib.DrawRectangle(vX, minimapY,
        Math.Clamp(minimapX + minimapSize - vX, 0, minimapSize),
        Math.Clamp(volB - minimapY, 0, minimapSize),
        new Color((byte)40,(byte)20,(byte)10,(byte)220));

    // 10. Mountains (X -30000 to -10000, Y -15000 to 23000)
    int mtL = cx + (int)((-30000 - player.Position.X) * minimapScale);
    int mtR = cx + (int)((-10000 - player.Position.X) * minimapScale);
    int mtT = cy + (int)((-12000 - player.Position.Y) * minimapScale);
    int mtB = cy + (int)((12000  - player.Position.Y) * minimapScale);
    int mX  = Math.Clamp(mtL, minimapX, minimapX + minimapSize);
    int mX2 = Math.Clamp(mtR, minimapX, minimapX + minimapSize);
    int mY  = Math.Clamp(mtT, minimapY, minimapY + minimapSize);
    int mY2 = Math.Clamp(mtB, minimapY, minimapY + minimapSize);
    Raylib.DrawRectangle(mX, mY, mX2 - mX, mY2 - mY,
        new Color((byte)100,(byte)95,(byte)90,(byte)220));

    // 11. Safe zone
    int szX  = cx + (int)((-3000 - player.Position.X) * minimapScale);
    int szY  = cy + (int)((-1500 - player.Position.Y) * minimapScale);
    int szX2 = cx + (int)((4000  - player.Position.X) * minimapScale);
    int szY2 = cy + (int)((2500  - player.Position.Y) * minimapScale);
    int csX  = Math.Clamp(szX,  minimapX, minimapX + minimapSize);
    int csY  = Math.Clamp(szY,  minimapY, minimapY + minimapSize);
    int csX2 = Math.Clamp(szX2, minimapX, minimapX + minimapSize);
    int csY2 = Math.Clamp(szY2, minimapY, minimapY + minimapSize);
    Raylib.DrawRectangle(csX, csY, csX2 - csX, csY2 - csY, new Color((byte)90,(byte)170,(byte)90,(byte)180));

    // 12. Farm zone
    int farmX1 = cx + (int)((-3000  - player.Position.X) * minimapScale);
    int farmX2 = cx + (int)((0      - player.Position.X) * minimapScale);
    int farmY1 = cy + (int)((-10000 - player.Position.Y) * minimapScale);
    int farmY2 = cy + (int)((-6000  - player.Position.Y) * minimapScale);
    int fX  = Math.Clamp(farmX1, minimapX, minimapX + minimapSize);
    int fY  = Math.Clamp(farmY1, minimapY, minimapY + minimapSize);
    int fX2 = Math.Clamp(farmX2, minimapX, minimapX + minimapSize);
    int fY2 = Math.Clamp(farmY2, minimapY, minimapY + minimapSize);
    Raylib.DrawRectangle(fX, fY, fX2 - fX, fY2 - fY,
        new Color((byte)139,(byte)90,(byte)43,(byte)220));

    // 13. Hamiltron City (X 11800–18200, Y 3000–8200)
    int htL = cx + (int)((11800 - player.Position.X) * minimapScale);
    int htR = cx + (int)((18200 - player.Position.X) * minimapScale);
    int htT = cy + (int)((3000  - player.Position.Y) * minimapScale);
    int htB = cy + (int)((8200  - player.Position.Y) * minimapScale);
    int hcX  = Math.Clamp(htL, minimapX, minimapX + minimapSize);
    int hcY  = Math.Clamp(htT, minimapY, minimapY + minimapSize);
    int hcX2 = Math.Clamp(htR, minimapX, minimapX + minimapSize);
    int hcY2 = Math.Clamp(htB, minimapY, minimapY + minimapSize);
    Raylib.DrawRectangle(hcX, hcY, hcX2 - hcX, hcY2 - hcY, new Color((byte)160,(byte)160,(byte)175,(byte)220));

    // 14. Rotoaira (X -18000 to -13800, Y 3200–6200)
    int rtL = cx + (int)((-18000 - player.Position.X) * minimapScale);
    int rtR = cx + (int)((-13800 - player.Position.X) * minimapScale);
    int rtT = cy + (int)((3200   - player.Position.Y) * minimapScale);
    int rtB = cy + (int)((6200   - player.Position.Y) * minimapScale);
    int rcX  = Math.Clamp(rtL, minimapX, minimapX + minimapSize);
    int rcY  = Math.Clamp(rtT, minimapY, minimapY + minimapSize);
    int rcX2 = Math.Clamp(rtR, minimapX, minimapX + minimapSize);
    int rcY2 = Math.Clamp(rtB, minimapY, minimapY + minimapSize);
    Raylib.DrawRectangle(rcX, rcY, rcX2 - rcX, rcY2 - rcY, new Color((byte)160,(byte)160,(byte)175,(byte)220));

    // Buildings — dot only, no label
    foreach (Building building in buildings)
    {
        int bx = cx + (int)MathF.Round((building.Bounds.X - player.Position.X) * minimapScale);
        int by = cy + (int)MathF.Round((building.Bounds.Y - player.Position.Y) * minimapScale);
        if (bx >= minimapX && bx <= minimapX + minimapSize && by >= minimapY && by <= minimapY + minimapSize)
            Raylib.DrawRectangle(bx - 1, by - 1, 3, 3, Color.Yellow);
    }

    // Roads drawn on top of buildings
    Color roadCol = new Color((byte)75,(byte)75,(byte)75,(byte)255);
    int mmRoadT  = cy + (int)((550 - player.Position.Y) * minimapScale);
    int mmHwyX   = cx + (int)((200 - player.Position.X) * minimapScale);
    int mmSideY  = cy + (int)((200 - player.Position.Y) * minimapScale);

    // Main horizontal road
    Raylib.DrawRectangle(minimapX, mmRoadT, minimapSize, 2, roadCol);
    // North + south highway
    Raylib.DrawRectangle(mmHwyX, minimapY, 2, minimapSize, roadCol);
    // Desert side road (rightward from X 4000)
    int desSideX = cx + (int)((4000 - player.Position.X) * minimapScale);
    Raylib.DrawRectangle(Math.Clamp(desSideX, minimapX, minimapX+minimapSize), mmSideY,
        Math.Clamp(minimapX+minimapSize - desSideX, 0, minimapSize), 2, roadCol);
    // Snow side road (leftward to X -3000)
    int snSideEndX = cx + (int)((-3000 - player.Position.X) * minimapScale);
    Raylib.DrawRectangle(minimapX, mmSideY,
        Math.Clamp(snSideEndX - minimapX, 0, minimapSize), 2, roadCol);

    // Ring roads
    int ringTopY   = cy + (int)((-38000 - player.Position.Y) * minimapScale);
    int ringBotY   = cy + (int)((38000  - player.Position.Y) * minimapScale);
    int ringLeftX  = cx + (int)((-40000 - player.Position.X) * minimapScale);
    int ringRightX = cx + (int)((39820  - player.Position.X) * minimapScale);
    Raylib.DrawRectangle(minimapX, ringTopY,   minimapSize, 2, roadCol);
    Raylib.DrawRectangle(minimapX, ringBotY,   minimapSize, 2, roadCol);
    Raylib.DrawRectangle(ringLeftX,  minimapY, 2, minimapSize, roadCol);
    Raylib.DrawRectangle(ringRightX, minimapY, 2, minimapSize, roadCol);

    // Snow/mountain vertical connectors (clipped to Y -12000 to 12000)
    int connT = Math.Clamp(cy + (int)((-12000 - player.Position.Y) * minimapScale), minimapY, minimapY+minimapSize);
    int connB = Math.Clamp(cy + (int)((12000  - player.Position.Y) * minimapScale), minimapY, minimapY+minimapSize);
    int snow1X = cx + (int)((-20000 - player.Position.X) * minimapScale);
    int snow2X = cx + (int)((-10000 - player.Position.X) * minimapScale);
    Raylib.DrawRectangle(snow1X, connT, 2, connB - connT, roadCol);
    Raylib.DrawRectangle(snow2X, connT, 2, connB - connT, roadCol);
    // Desert vertical connectors
    int des1X = cx + (int)((15000 - player.Position.X) * minimapScale);
    int des2X = cx + (int)((25000 - player.Position.X) * minimapScale);
    Raylib.DrawRectangle(des1X, connT, 2, connB - connT, roadCol);
    Raylib.DrawRectangle(des2X, connT, 2, connB - connT, roadCol);

    // City of Hamiltron roads
    int cityWX  = Math.Clamp(cx + (int)((11800 - player.Position.X) * minimapScale), minimapX, minimapX+minimapSize);
    int cityEX  = Math.Clamp(cx + (int)((18200 - player.Position.X) * minimapScale), minimapX, minimapX+minimapSize);
    int cityNY  = Math.Clamp(cy + (int)((3000  - player.Position.Y) * minimapScale), minimapY, minimapY+minimapSize);
    int citySY  = Math.Clamp(cy + (int)((8200  - player.Position.Y) * minimapScale), minimapY, minimapY+minimapSize);
    int cityBoulY   = cy + (int)((5500  - player.Position.Y) * minimapScale);
    int cityNAveX   = cx + (int)((14800 - player.Position.X) * minimapScale);
    int cityCrossNY = cy + (int)((3900  - player.Position.Y) * minimapScale);
    int cityCrossSY = cy + (int)((7200  - player.Position.Y) * minimapScale);
    Raylib.DrawRectangle(cityWX, cityBoulY,   cityEX-cityWX, 2, roadCol);
    Raylib.DrawRectangle(cityNAveX, cityNY,   2, citySY-cityNY, roadCol);
    Raylib.DrawRectangle(cityWX, cityCrossNY, cityEX-cityWX, 2, roadCol);
    Raylib.DrawRectangle(cityWX, cityCrossSY, cityEX-cityWX, 2, roadCol);
    Raylib.DrawRectangle(cityWX, cityNY, cityEX-cityWX, 2, roadCol);
    Raylib.DrawRectangle(cityWX, citySY, cityEX-cityWX, 2, roadCol);
    Raylib.DrawRectangle(cityWX, cityNY, 2, citySY-cityNY, roadCol);
    Raylib.DrawRectangle(cityEX, cityNY, 2, citySY-cityNY, roadCol);

    // Rotoaira roads
    int rtWX  = Math.Clamp(cx + (int)((-18000 - player.Position.X) * minimapScale), minimapX, minimapX+minimapSize);
    int rtEX  = Math.Clamp(cx + (int)((-13800 - player.Position.X) * minimapScale), minimapX, minimapX+minimapSize);
    int rtNY  = Math.Clamp(cy + (int)((3200   - player.Position.Y) * minimapScale), minimapY, minimapY+minimapSize);
    int rtSY  = Math.Clamp(cy + (int)((6200   - player.Position.Y) * minimapScale), minimapY, minimapY+minimapSize);
    int rtMainY = cy + (int)((4400 - player.Position.Y) * minimapScale);
    Raylib.DrawRectangle(rtWX, rtMainY,  rtEX-rtWX, 2, roadCol);
    Raylib.DrawRectangle(rtWX, rtNY,     rtEX-rtWX, 2, roadCol);
    Raylib.DrawRectangle(rtWX, rtSY,     rtEX-rtWX, 2, roadCol);
    Raylib.DrawRectangle(rtWX, rtNY,     2, rtSY-rtNY, roadCol);
    Raylib.DrawRectangle(rtEX, rtNY,     2, rtSY-rtNY, roadCol);

    Raylib.DrawRectangleLines(minimapX, minimapY, minimapSize, minimapSize, Color.White);
    Raylib.DrawCircle(cx, cy, 4, Color.White);
    Raylib.EndScissorMode();

    Raylib.DrawRectangleLines(minimapX, minimapY, minimapSize, minimapSize, Color.White);
    Raylib.DrawText(playerName, minimapX, minimapY + minimapSize + 6, 18, Color.LightGray);

    // Legend
    int lx = minimapX;
    int ly = minimapY + minimapSize + 28;
    (Color col, string label)[] legend = {
        (new Color((byte)90,(byte)170,(byte)90,(byte)255),  "Safe"),
        (new Color((byte)40,(byte)100,(byte)40,(byte)255),  "Forest"),
        (new Color((byte)210,(byte)180,(byte)100,(byte)255),"Desert"),
        (new Color((byte)220,(byte)235,(byte)255,(byte)255),"Snow"),
        (new Color((byte)55,(byte)75,(byte)35,(byte)255),   "Swamp"),
        (new Color((byte)40,(byte)20,(byte)10,(byte)255),   "Volcano"),
        (new Color((byte)100,(byte)95,(byte)90,(byte)255),  "Mountains"),
        (new Color((byte)240,(byte)220,(byte)150,(byte)255),"Beach"),
        (new Color((byte)30,(byte)100,(byte)180,(byte)255), "Ocean"),
        (new Color((byte)139,(byte)90,(byte)43,(byte)255),  "Farm"),
    };

    for (int i = 0; i < legend.Length; i++)
    {
        int row = i / 2;
        int col = i % 2;
        int lbx = lx + col * 55;
        int lby = ly + row * 16;
        Raylib.DrawRectangle(lbx, lby, 10, 10, legend[i].col);
        Raylib.DrawText(legend[i].label, lbx + 13, lby, 12, Color.LightGray);
    }
}

        static void Main()
        {
            Raylib.InitWindow(ScreenWidth, ScreenHeight, "Open World RPG V3");
            Raylib.SetTargetFPS(60);
            Raylib.SetExitKey(KeyboardKey.Null);
            Raylib.InitAudioDevice();
            
            if (Raylib.IsAudioDeviceReady())
        {
            musicMainMenu = Raylib.LoadMusicStream("resources/music/Meadow Thoughts.ogg");
            musicDbar   = Raylib.LoadMusicStream("resources/music/dbarMusic.mp3");
            musicFarm  = Raylib.LoadMusicStream("resources/music/farmMusic.mp3");
            musicCity  = Raylib.LoadMusicStream("resources/music/Pleasant Creek.mp3");
            musicHouse = Raylib.LoadMusicStream("resources/music/Meadow Thoughts.ogg");
            musicRain = Raylib.LoadMusicStream("resources/music/rainMusic.ogg");
            musicMeadowlands = Raylib.LoadMusicStream("resources/music/meadowlandsMusic.mp3");
            musicForest = Raylib.LoadMusicStream("resources/music/forestMusic.mp3");
            musicBeach = Raylib.LoadMusicStream("resources/music/beachMusic.mp3");
            musicDesert = Raylib.LoadMusicStream("resources/music/desertTownMusic.mp3");
            musicSnow = Raylib.LoadMusicStream("resources/music/snowMusic.mp3");
            musicTakeaways = Raylib.LoadMusicStream("resources/music/takeawayMusic.ogg");
            musicOcean  = Raylib.LoadMusicStream("resources/music/farmMusic.mp3");
            musicVolcano  = Raylib.LoadMusicStream("resources/music/wastelands.ogg");

            // Load these once at startup/asset loading section
            soundPauseOpen  = Raylib.LoadSound("resources/sound/pauseOpen.wav");
            soundPauseClose = Raylib.LoadSound("resources/sound/pauseClose.wav");
            soundTreeChop  = Raylib.LoadSound("resources/sound/treeChop.wav");
            soundTreeFall  = Raylib.LoadSound("resources/sound/treeFall.wav");
            soundRockHit   = Raylib.LoadSound("resources/sound/rockHit.wav");
            soundRockBreak = Raylib.LoadSound("resources/sound/rockBreak.wav");
            soundHorseGallop = Raylib.LoadSound("resources/sound/horseGallop.ogg");
            soundCarHorn = Raylib.LoadSound("path/to/horn.wav");
            soundSwordSwing = Raylib.LoadSound("resources/sound/swordSwing.wav");
            soundStickSwing = Raylib.LoadSound("resources/sound/stickSwing.wav");
            soundDogHit     = Raylib.LoadSound("resources/sound/dogHit.wav");
            soundDogDie     = Raylib.LoadSound("resources/sound/dogDie.ogg");
        

            Raylib.SetMusicVolume(musicMainMenu, musicVolume);
            Raylib.SetMusicVolume(musicDbar,   musicVolume);
            Raylib.SetMusicVolume(musicFarm,   musicVolume);
            Raylib.SetMusicVolume(musicHouse, musicVolume);
            Raylib.SetMusicVolume(musicRain, musicVolume);
            Raylib.SetMusicVolume(musicForest, musicVolume);
            Raylib.SetMusicVolume(musicBeach, musicVolume);
            Raylib.SetMusicVolume(musicDesert, musicVolume);
            Raylib.SetMusicVolume(musicSnow, musicVolume);
            Raylib.SetMusicVolume(musicTakeaways, musicVolume);
            Raylib.SetMusicVolume(musicMeadowlands, musicVolume);
            Raylib.SetMusicVolume(musicCity, musicVolume);
            Raylib.SetMusicVolume(musicOcean, musicVolume);
            Raylib.SetMusicVolume(musicVolcano, musicVolume);
           
           
           
           

            Raylib.SetSoundVolume(soundPauseOpen, soundVolume);
            Raylib.SetSoundVolume(soundPauseClose, soundVolume);
            Raylib.SetSoundVolume(soundSwordSwing, soundVolume);
            Raylib.SetSoundVolume(soundStickSwing, soundVolume);
            Raylib.SetSoundVolume(soundDogHit,     soundVolume);
            Raylib.SetSoundVolume(soundDogDie,     soundVolume);

            // Start on main menu track
            currentMusic = musicMainMenu;
            Raylib.PlayMusicStream(currentMusic);
            musicLoaded = true;
            musicPlaying = true;
        }

            GenerateWorld();

            camera.Offset = new Vector2(ScreenWidth / 2, ScreenHeight / 2);
            camera.Zoom = 1f;

            while (!Raylib.WindowShouldClose())
            {
                float dt = Raylib.GetFrameTime();
                if (musicLoaded)
                {
                Raylib.UpdateMusicStream(currentMusic);
                UpdateMusicFade(dt);
                }
                Update(dt);
                Draw();
            }
            if (musicLoaded)
{
    Raylib.StopMusicStream(currentMusic);
    Raylib.UnloadMusicStream(musicMainMenu);
    Raylib.UnloadMusicStream(musicDbar);
    Raylib.UnloadMusicStream(musicTakeaways);
    Raylib.UnloadMusicStream(musicBeach);
    Raylib.UnloadMusicStream(musicDesert);
    Raylib.UnloadMusicStream(musicSnow);

    Raylib.UnloadSound(soundPauseOpen);   
    Raylib.UnloadSound(soundPauseClose);
    Raylib.UnloadSound(soundRockHit);
    Raylib.UnloadSound(soundRockBreak);
    Raylib.UnloadSound(soundTreeChop);
    Raylib.UnloadSound(soundTreeFall);
    Raylib.UnloadSound(soundHorseGallop);
    Raylib.UnloadSound(soundSwordSwing);
    Raylib.UnloadSound(soundStickSwing);
    Raylib.UnloadSound(soundDogHit);
    Raylib.UnloadSound(soundDogDie);
    Raylib.CloseAudioDevice();
}
            Raylib.CloseWindow();
        }


        static void Update(float dt)
        
        {
            if (Raylib.IsKeyPressed(KeyboardKey.Tab))
            {
            if (!pauseMenuOpen && !armorMenuOpen && !skillsOpen && !questsOpen)
                    player.InventoryOpen = !player.InventoryOpen;
            }
            switch(currentScene)
            {
                case SceneState.MainMenu:


    if (!mainMenuChoice)
    {
        Vector2 mouse = Raylib.GetMousePosition();
        Rectangle newGameBtn = new Rectangle(ScreenWidth / 2 - 150, 360, 300, 60);
        Rectangle loadGameBtn = new Rectangle(ScreenWidth / 2 - 150, 440, 300, 60);

        bool anySaveExists = savePaths.Any(p => System.IO.File.Exists(p));

if (Raylib.IsMouseButtonPressed(MouseButton.Left) && !multiplayerMenuOpen)
{
    if (Raylib.CheckCollisionPointRec(mouse, newGameBtn))
    {
        mainMenuChoice = true;
        isLoadingGame = false;
    }

    if (anySaveExists && Raylib.CheckCollisionPointRec(mouse, loadGameBtn))
    {
        mainMenuChoice = true;
        isLoadingGame = true;
    }
}
    }
    else
    {
        Vector2 mouse = Raylib.GetMousePosition();

        for (int i = 0; i < 3; i++)
        {
            Rectangle slotBtn = new Rectangle(ScreenWidth / 2 - 250, 300 + i * 100, 500, 80);
            var (exists, name, info) = GetSlotInfo(i);

      if (Raylib.CheckCollisionPointRec(mouse, slotBtn))
{
    if (Raylib.IsMouseButtonPressed(MouseButton.Left))
    {
        if (isLoadingGame && exists)
        {
            selectedSlot = i;
            slotSelected = true;
            LoadGame();
            currentScene = SceneState.World;
        }
        else if (!isLoadingGame && !exists)
        {
            selectedSlot = i;
            slotSelected = true;
            playerName = "typing";
            nameEntered = false;
            totalPlayTime = 0f;
        }
        else if (!isLoadingGame && exists)
        {
            overwriteConfirmOpen = true;
            overwriteSlot = i;
        }
    }
}
        }

        if (slotSelected && !nameEntered)
{
    if (playerName == "typing") playerName = "";

            int key = Raylib.GetCharPressed();
            while (key > 0)
            {
                if (playerName.Length < 12)
                    playerName += (char)key;
                key = Raylib.GetCharPressed();
            }

            if (Raylib.IsKeyPressed(KeyboardKey.Backspace) && playerName.Length > 0)
                playerName = playerName.Substring(0, playerName.Length - 1);

            if (Raylib.IsKeyPressed(KeyboardKey.Enter) && playerName.Length > 0)
                nameEntered = true;
        }
        else if (nameEntered)
        {
            if (Raylib.IsKeyPressed(KeyboardKey.Enter))
            {
                player = new Player(new Vector2(-1917, -9720));
                ResetGameState();  
                chestLogs = 0; chestFish = 0; chestBones = 0;
                chestFur = 0; chestStingers = 0; chestBearPelts = 0;
                chestDogFangs = 0;
                // new loot materials
                chestWolfClaws = 0; chestVenomSacs = 0; chestCrabClaws = 0;
                chestBearClaws = 0; chestCrabShells = 0; chestSharkFins = 0;
                chestSharkTeeth = 0; chestSnakeSkins = 0; chestSnakeFangs = 0;
                chestCrocScales = 0; chestCrocTeeth = 0; chestLizardScales = 0;
                chestEmberStones = 0; chestMagmaShards = 0; chestLavaCores = 0;
                chestFeathers = 0; chestEagleTalons = 0; chestHorns = 0;
                chestGoatHooves = 0;
                timeOfDay = 0f; dayOfWeek = 0;
                quests[0].Progress = 0; quests[0].Completed = false;
                quests[1].Progress = 0; quests[1].Completed = false;
                quests[2].Progress = 0; quests[2].Completed = false;
                totalPlayTime = 0f;
                tutorialActive = true;
                tutorialStep = 0;
                tutorialNpcPos = player.Position + new Vector2(-60, -40);
                foreach (var t in tutorialTasks) t.Done = false;
                SnapshotTutorialMarks();
                currentScene = SceneState.World;
            }
        }

        if (Raylib.IsKeyPressed(KeyboardKey.Escape) && playerName.Length == 0)
            {
                mainMenuChoice = false;
                slotSelected = false;
                playerName = "";
                nameEntered = false;
            }
        }

    break;

                case SceneState.World:


                CheckZoneMusic();

                        // ── CHAT INPUT ────────────────────────────────────────────────────────────
       if (chatInputCooldown > 0f) chatInputCooldown -= dt;

        // ── CHAT INPUT ────────────────────────────────────────────────────────────
        if (chatInputOpen)
        {
            int key = Raylib.GetCharPressed();
            while (key > 0)
            {
                if (key >= 32 && key <= 125 && chatInputText.Length < 60)
                    chatInputText += (char)key;
                key = Raylib.GetCharPressed();
            }
            if (Raylib.IsKeyPressed(KeyboardKey.Backspace) && chatInputText.Length > 0)
                chatInputText = chatInputText[..^1];

            if (Raylib.IsKeyPressed(KeyboardKey.Enter) && chatInputText.Length > 0)
            {
                playerChatMessage = chatInputText;
                playerChatTimer   = playerChatDuration;
                multiplayer.SendChat(chatInputText);
                multiplayer.SendTyping(false);
                chatInputText = "";
                chatInputOpen = false;
            }
            if (Raylib.IsKeyPressed(KeyboardKey.Escape))
            {
                multiplayer.SendTyping(false);
                chatInputText = "";
                chatInputOpen = false;
            }
        }
        else
        {
            if (Raylib.IsKeyPressed(KeyboardKey.Enter) && chatInputCooldown <= 0f)
            {
                chatInputOpen = true;
                multiplayer.SendTyping(true);
            }
        }

        // age the local speech bubble
        if (playerChatTimer > 0f)
            playerChatTimer -= Raylib.GetFrameTime();
             bool blockShortcutsForChat = chatInputOpen;

                string mpSceneTag = currentScene == SceneState.Building && currentBuilding != null
                ? $"Building:{currentBuilding.BuildingName}"
                : currentScene.ToString();
                multiplayer.Update(player, playerName, mpSceneTag);
                CheckSendAppearanceIfChanged();
                UpdateTutorial(dt);
                UpdateDroppedItems(dt);

// Toolbar slot selection — number keys 1-8
if (!chatInputOpen)
{
    for (int k = 0; k < 8; k++)
    {
        if (Raylib.IsKeyPressed(KeyboardKey.One + k))
            toolbarSelectedSlot = k;
    }
}

if (Raylib.IsKeyPressed(KeyboardKey.Space) && !chatInputOpen)
{
    string held = toolbarSlots[toolbarSelectedSlot];
    if (held != null && IsUsable(held))
        UseToolbarItem(toolbarSelectedSlot);
   
}

// Also mouse scroll wheel
float scroll = Raylib.GetMouseWheelMove();
if (scroll != 0)
    camera.Zoom = Math.Clamp(camera.Zoom + scroll * 0.1f, 0.2f, 4.0f);

                // Axe pickup
                if (!axePickedUp && Vector2.Distance(player.Center, axePosition) < 60)
                {
                    if (Raylib.IsKeyPressed(KeyboardKey.E) && !chatInputOpen)
                    {
                        player.HasAxe = true;
                        axePickedUp = true;
                        AddToToolbar("Axe");
                        ShowNotification("You picked up an Axe! You can now chop trees.");
                    }
                }

                // Pickaxe pickup
if (!pickaxePickedUp && Vector2.Distance(player.Center, pickaxePosition) < 60)
{
    if (Raylib.IsKeyPressed(KeyboardKey.E) && !chatInputOpen)
    {
        pickaxePickedUp = true;
        AddToToolbar("Pickaxe");
        ShowNotification("Pickaxe added to toolbar!");
    }
}

// Fishing rod pickup
if (!fishingRodPickedUp && Vector2.Distance(player.Center, fishingRodPosition) < 60)
{
    if (Raylib.IsKeyPressed(KeyboardKey.E) && !chatInputOpen)
    {
        fishingRodPickedUp = true;
        AddToToolbar("Rod");
        ShowNotification("Fishing Rod added to toolbar! Equip it near lakes.");
    }
}

// Fishing net pickup
if (!fishingNetPickedUp && Vector2.Distance(player.Center, fishingNetPosition) < 60)
{
    if (Raylib.IsKeyPressed(KeyboardKey.E) && !chatInputOpen)
    {
        fishingNetPickedUp = true;
        AddToToolbar("Net");
        ShowNotification("Fishing Net added to toolbar!");
    }
}

// Torch pickup
if (!torchPickedUp && Vector2.Distance(player.Center, torchPosition) < 60)
{
    if (Raylib.IsKeyPressed(KeyboardKey.E) && !chatInputOpen)
    {
        torchPickedUp = true;
        AddToToolbar("Torch");
        ShowNotification("Torch added to toolbar!");
    }
}

// Weapon pickups and routing to there weapon holders
// Stick pickup
if (!stickPickedUp && Vector2.Distance(player.Center, stickPosition) < 60)
{
    if (Raylib.IsKeyPressed(KeyboardKey.E) && !chatInputOpen)
    {
        stickPickedUp = true;   // now owned → appears in inventory
        if (equipped1H == null)
        {
            equipped1H  = "Stick";
            equipped2H  = null;
            armorWeapon = "Stick";
            ShowNotification("Stick equipped in 1H weapon slot! Press T to draw it.");
        }
        else
        {
            ShowNotification("Stick added to inventory (1H slot full).");
        }
    }
}

// Sword pickup
if (!swordPickedUp && Vector2.Distance(player.Center, swordPosition) < 60)
{
    if (Raylib.IsKeyPressed(KeyboardKey.E) && !chatInputOpen)
    {
        swordPickedUp = true;   // now owned → appears in inventory
        if (equipped1H == null)
        {
            equipped1H  = "Sword";
