        new Color((byte)255,(byte)255,(byte)0,(byte)150));

    // canopy pillars
    Raylib.DrawRectangle((int)x + 50,  (int)y - 350, 20, 140,
        new Color((byte)60,(byte)60,(byte)60,(byte)255));
    Raylib.DrawRectangle((int)x + 290, (int)y - 350, 20, 140,
        new Color((byte)60,(byte)60,(byte)60,(byte)255));
