    Raylib.DrawRectangle((int)x + 280, (int)y - 20, 80, 20, Color.Yellow);
    Raylib.DrawRectangle((int)x + 480, (int)y - 20, 80, 20, Color.Yellow);

    // pump 1
    Vector2 p1 = station.Pump1Pos;
