            int sy = shelfY[row];
            Color shelfProduct = aisleColors[(row / 2) % aisleColors.Length][row % 2];
            // shelf backing
            Raylib.DrawRectangle(ax, sy, 220, 35, new Color((byte)150,(byte)120,(byte)80,(byte)255));
