private void DrawScorpion(int x, int y)
{
    Color shell = new Color((byte)180, (byte)120, (byte)0, (byte)255);
    Color dark  = new Color((byte)100, (byte)60,  (byte)0, (byte)255);
    Color sting = new Color((byte)220, (byte)60,  (byte)0, (byte)255);

    // Body segments
