        int r = great ? 8 : 5;
        Raylib.DrawLineEx(new Vector2(x + 25, y + 40 + armSwingRight), new Vector2(x + len, y + 40 + armSwingRight), great ? 6 : 5, new Color((byte)110,(byte)80,(byte)45,(byte)255));
