                Raylib.DrawRectangle(x + 10, y + 6, 80, 24, VehicleColor);
                Raylib.DrawRectangle(x + 28, y - 4, 44, 14, VehicleColor);   // cabin
                Raylib.DrawRectangle(x + 32, y - 1, 36, 9, new Color((byte)100,(byte)180,(byte)220,(byte)200));
