        Raylib.DrawRectangle(x + 74, y + 14, 4, 8, Color.Black);
        // grilles / bull bar
        Raylib.DrawRectangle(x + 13, y + 34, 54, 9, new Color((byte)40, (byte)40, (byte)40, (byte)255));
        for (int i = x + 18; i < x + 52; i += 5)
